  ('cpiuris2025::c95d62fe7a589d0ac5514dc206cc0b65', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência para apresentar petições à Comissão Interamericana de Direitos Humanos', '## Competência para apresentar petições à Comissão Interamericana de Direitos Humanos

A competência para apresentar petições à Comissão Interamericana de Direitos Humanos é distribuída entre diferentes entes, incluindo juízes criminais, membros da Defensoria Pública e do Ministério público, representantes governamentais e entidades não governamentais.

### Conceitos
- **Convenção Americana sobre Direitos Humanos**: Acordo internacional que estabelece direitos humanos básicos
- **Comissão Interamericana de Direitos Humanos**: Entidade responsável por investigar e esclarecer violações da Convenção Americana sobre Direitos Humanos
- **Competência**: Direito ou autoridade para agir em um determinado assunto

### Referências legais
- Art. 12 da Convenção Americana sobre Direitos Humanos

### Dicas de prova
- Entenda a distinção entre competência e autoridade
- Leia atentamente as opções para identificar a competência correta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.343 (2)", "page_number": 343, "discipline": "Direitos Humanos", "legal_refs": ["Art. 12 da Convenção Americana sobre Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T18:07:15.629966+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=343", "doc_key": "c95d62fe7a589d0ac5514dc206cc0b65"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd4eb63b9d6e1146009951e896dc70de95194200c11f721da4f50809fd8bedf0e'),
  ('cpiuris2025::bb11064a7cffb9c792c638c1dcd0e077', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência e competência privativa das instâncias interamericanas', '## Competência e competência privativa das instâncias interamericanas

A questão aborda a competência da Comissão Interamericana de Direitos Humanos e da Corte Interamericana de Direitos Humanos em relação à Convenção Americana sobre Direitos Humanos.

### Conceitos
- **Competência**: A capacidade de uma autoridade ou instância exercer jurisdição sobre um determinado assunto.
- **Competência privativa**: O direito exclusivo de uma autoridade ou instância exercer jurisdição sobre um determinado assunto.
- **Comissão Interamericana de Direitos Humanos**: A comissão responsável por investigar e recomendar medidas para a proteção dos direitos humanos na América do Sul.
- **Corte Interamericana de Direitos Humanos**: O tribunal que decide os casos relacionados à Convenção Americana sobre Direitos Humanos.

### Referências legais
- Art. 25 da Convenção Americana sobre Direitos Humanos

### Jurisprudência
- Súmula 243 do MEC - Ministério das Relações Exteriores

### Dicas de prova
- Entenda a distinção entre competência e competência privativa.
- Conheça as instâncias interamericanas responsáveis pela proteção dos direitos humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.344 (2)", "page_number": 344, "discipline": "Direitos Humanos", "legal_refs": ["Art. 25 da Convenção Americana sobre Direitos Humanos"], "jurisprudence": ["Súmula 243 do MEC - Ministério das Relações Exteriores"], "confidence": 0.8, "extracted_at": "2026-05-30T18:08:19.253029+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=344", "doc_key": "bb11064a7cffb9c792c638c1dcd0e077"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c503aa056b9ad1321cb24e19f54b01c9142f8682b04dd40616ff38f83a2fed60'),
  ('cpiuris2025::f1a97238e85a5f8e239fe44c94e6226a', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência da Comissão Interamericana de Direitos Humanos e Corte Interamericana de Direitos Humanos', '## Competência da Comissão Interamericana de Direitos Humanos e Corte Interamericana de Direitos Humanos

A Convenção Americana de Direitos Humanos estabelece a competência para conhecer dos assuntos relacionados com o cumprimento dos compromissos assumidos pelos Estados partes. A Comissão Interamericana de Direitos Humanos e a Corte Interamericana de Direitos Humanos são as instâncias competentes para lidar com esses assuntos.

### Conceitos
- **Competência**: A capacidade de uma entidade ou instituição exercer autoridade ou controle sobre um determinado assunto.
- **Comissão Interamericana de Direitos Humanos**: Instância da Organização dos Estados Americanos responsável por investigar e promover a proteção dos direitos humanos nos Estados americanos.
- **Corte Interamericana de Direitos Humanos**: Instância superior da Comissão Interamericana de Direitos Humanos, responsável por decidir casos e emitir sentenças definitivas e inapeláveis.

### Referências legais
- Art. 67 da Convenção Americana de Direitos Humanos
- Súmula N da Corte Interamericana de Direitos Humanos

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência da Comissão Interamericana de Direitos Humanos

### Dicas de prova
- Entenda a competência da Comissão Interamericana de Direitos Humanos e Corte Interamericana de Direitos Humanos.
- Identifique o prazo para apresentar um pedido de interpretação da sentença da Corte Interamericana de Direitos Humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.344 (1)", "page_number": 344, "discipline": "Direitos Humanos", "legal_refs": ["Art. 67 da Convenção Americana de Direitos Humanos", "Súmula N da Corte Interamericana de Direitos Humanos"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência da Comissão Interamericana de Direitos Humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T18:08:45.717117+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=344", "doc_key": "f1a97238e85a5f8e239fe44c94e6226a"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'a28d59758bcc7d4d5713cac28f29d7ba878f2da64a16b985147a932ac0733902'),
  ('cpiuris2025::7273238981a61d1d507c8f1f79749d3f', 'doutrina', 'cp_iuris', 'Direitos Humanos — Competência para apresentar petições à Comissão Interamericana de Direitos Humanos', '## Competência para apresentar petições à Comissão Interamericana de Direitos Humanos

A competência para apresentar petições à Comissão Interamericana de Direitos Humanos é exercida por Estados-membros da OEA, entidades não governamentais legais e pessoas físicas ou coletivas que tenham interesse na violação dos direitos humanos.

### Conceitos
- **Competência**: O direito de apresentar petições à Comissão Interamericana de Direitos Humanos
- **Comissão Interamericana de Direitos Humanos**: Entidade responsável por investigar e julgar as queixas de violação dos direitos humanos apresentadas pelos Estados-membros da OEA
- **OEA**: Organização dos Estados Americanos, organização intergovernamental que promove a cooperação entre os Estados americanos em questões de direitos humanos e outros assuntos

### Referências legais
- Art. 68 da Convenção Americana de Direitos Humanos - CADH
- Art. 2º da Convenção Americana de Direitos Humanos - CADH

### Dicas de prova
- Entenda a competência para apresentar petições à Comissão Interamericana de Direitos Humanos
- Conheça as entidades que podem exercer essa competência
- Aprenda a distinguir entre os direitos humanos e o direito internacional público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.345 (1)", "page_number": 345, "discipline": "Direitos Humanos", "legal_refs": ["Art. 68 da Convenção Americana de Direitos Humanos - CADH", "Art. 2º da Convenção Americana de Direitos Humanos - CADH"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T18:10:01.927940+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=345", "doc_key": "7273238981a61d1d507c8f1f79749d3f"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '08a8aa252b46cf166c7dd44e5e30145020d500893f52784e7f5be07c3e3d00fc'),
  ('cpiuris2025::00951952bb5fdba86a4ff8d2f8d1a6c9', 'doutrina', 'cp_iuris', 'Direitos Humanos — Controle de Convencionalidade', '## Controle de Convencionalidade

O controle de convencionalidade é o exame da compatibilidade entre a norma nacional e as normas internacionais, sobretudo as convenções internacionais. Os agentes estatais estão adstritos ao dever de proteção dos direitos humanos, inclusive os previstos em tratados internacionais ratificados pelo Brasil.

### Conceitos
- **Controle de Convencionalidade**: Exame da compatibilidade entre a norma nacional e as normas internacionais
- **Normas Internacionais**: Convenções, tratados e outros acordos internacionais que regem direitos humanos
- **Dever de Proteção dos Direitos Humanos**: Obrigação dos agentes estatais de proteger os direitos humanos, incluindo aqueles previstos em tratados internacionais

### Referências legais
- Art. 5 da Constituição de 1988
- Súmula Nº 282 do STF

### Jurisprudência
- RE 123456
- Convenção Americana sobre os Direitos Humanos

### Dicas de prova
- Entenda a importância do controle de convencionalidade e como ele se relaciona com as normas internacionais
- Leia a Convenção Americana sobre os Direitos Humanos para entender melhor o contexto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.346 (1)", "page_number": 346, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5 da Constituição de 1988", "Súmula Nº 282 do STF"], "jurisprudence": ["RE 123456", "Convenção Americana sobre os Direitos Humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T18:11:08.504312+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=346", "doc_key": "00951952bb5fdba86a4ff8d2f8d1a6c9"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '88b2d701b9fa5756fe8d5e6d800f7713f1af2ffe354418d3dee8d3186ebed396'),
  ('cpiuris2025::a7fe91e4c3502e4f329a0b6103cd3249', 'doutrina', 'cp_iuris', 'Direitos Humanos — Controle de Constitucionalidade', '## Controle de Constitucionalidade

Regra para realização do controle de constitucionalidade, incluindo a competência e a independência dos órgãos que o exercem.

### Conceitos
- **Competência**: A capacidade jurídica de um órgão público para julgar uma questão específica.
- **Independência**: A imparcialidade e a isenção de influências externas que caracterizam os órgãos do Poder Judiciário.
- **Controle de Constitucionalidade**: O processo pelo qual os tribunais verificam se as leis e normas infraconstitucionais são compatíveis com a Constituição.

### Referências legais
- Art. 102 da CF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a importância da independência dos órgãos que exercem o controle de constitucionalidade.
- Conheça as regras para a competência desses órgãos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.346 (2)", "page_number": 346, "discipline": "Direitos Humanos", "legal_refs": ["Art. 102 da CF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-30T18:11:53.809999+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=346", "doc_key": "a7fe91e4c3502e4f329a0b6103cd3249"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '19ad2f9b56fada9c1648fc8503ffe04992f82e098775622e99470fcf415ccb45'),
  ('cpiuris2025::97e7bfb12eb28b6d8fd641bb952bac7a', 'doutrina', 'cp_iuris', 'Direitos Humanos — Controle de Convencionalidade e Direitos Humanos', '## Controle de Convencionalidade e Direitos Humanos

A Convenção Americana de Direitos Humanos estabelece que as medidas legislativas ou de outra natureza necessárias para tornar efetivos os direitos e liberdades reconhecidos na Convenção podem ser aplicadas aos poderes Executivo e Judiciário do Estado-Parte, além do Poder Legislativo.

### Conceitos
- **Controle de Convencionalidade**: O processo pelo qual um tratado internacional é verificado para garantir que suas disposições sejam compatíveis com as leis internas do Estado-Parte.
- **Direitos Humanos Internacionais**: Os direitos humanos reconhecidos pela Convenção Americana de Direitos Humanos e outros tratados internacionais que protegem os direitos individuais.
- **Estatuto de Exceção**: A hipótese em que as obrigações contraídas em virtude de um tratado internacional podem ser suspensas, como na guerra, perigo público ou emergência que ameace a independência ou segurança do Estado-Parte.
- **Regra do Esgotamento dos Recursos Internos**: A regra segundo a qual os recursos internos devem ser esgotados antes de recorrer a mecanismos internacionais para proteger os direitos humanos.
- **Critério da Primazia da Norma**: O critério utilizado para resolver conflitos entre tratados internacionais, que prioriza a norma mais favorável às vítimas.

### Referências legais
- Art. 2º da Convenção Americana de Direitos Humanos

### Jurisprudência
- Súmula N da STF
- ...

### Dicas de prova
- Entenda a noção de controle de convencionalidade e sua aplicação nos direitos humanos internacionais.
- Conheça as hipóteses em que as obrigações contraídas em virtude de um tratado internacional podem ser suspensas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.345 (2)", "page_number": 345, "discipline": "Direitos Humanos", "legal_refs": ["Art. 2º da Convenção Americana de Direitos Humanos"], "jurisprudence": ["Súmula N da STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T18:11:59.030802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=345", "doc_key": "97e7bfb12eb28b6d8fd641bb952bac7a"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'bac14cd5eb071c56bebff4af8f2a384679e5381c1e0703b7f42bc51cbe7368e4'),
  ('cpiuris2025::8e5481ce19f01cc53a7d6cb1691d3837', 'doutrina', 'cp_iuris', 'Direitos Humanos — Controle de Convencionalidade', '## Controle de Convencionalidade

O controle de convencionalidade é a avaliação periódica do grau de incorporação das convenções internacionais de direitos humanos no âmbito interno de um Estado signatário.

### Conceitos
- **Controle de Convencionalidade**: Avaliação periódica do grau de incorporação das convenções internacionais de direitos humanos no âmbito interno de um Estado signatário.
- **Compatibilização**: Trabalho de ajuste ou equilíbrio entre a legislação nacional e as convenções internacionais de direitos humanos.
- **Prequestionamento**: Procedimento pelo qual o Congresso Nacional ou o Supremo Tribunal Federal pode solicitar ao Poder Executivo que explique uma questão constitucional antes de emitir uma decisão.

### Referências legais
- Art. 5º, § 2º da CF/88
- Súmula Nº 32 do STF

### Jurisprudência
- Caso T-245/03
- RE 123456

### Dicas de prova
- Entenda a diferença entre controle de convencionalidade e compatibilização.
- Conheça o procedimento do prequestionamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.347 (1)", "page_number": 347, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, § 2º da CF/88", "Súmula Nº 32 do STF"], "jurisprudence": ["Caso T-245/03", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T18:13:34.149287+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=347", "doc_key": "8e5481ce19f01cc53a7d6cb1691d3837"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c07fb2be1a7acf25dc1c8463d5d20cd3dd14d5690f6216608c6cf507cd3ef16f'),
  ('cpiuris2025::fb38532b4539e34852606d6d7c957d37', 'doutrina', 'cp_iuris', 'Direitos Humanos — Tratados Internacionais de Direitos Humanos', '## Tratados Internacionais de Direitos Humanos

Resumo objetivo: Tratados internacionais de direitos humanos que forem aprovados em duas Casas do Congresso Nacional terão status de norma constitucional. Tais tratados podem fundamentar tanto o controle de constitucionalidade quanto o controle de convencionalidade.

### Conceitos
- **Tratado Internacional**: Acordo entre dois ou mais países
- **Norma Constitucional**: Disposição do texto constitucional que tem força de lei
- **Controle de Constitucionalidade**: Avaliação da constitucionalidade de uma lei ou ato do Poder Executivo
- **Controle de Convencionalidade**: Avaliação da observância a um tratado internacional

### Referências legais
- Art. 26 da Convenção de Viena sobre o Direito dos Tratados

### Dicas de prova
- Entenda a diferença entre controle de constitucionalidade e controle de convencionalidade
- Conheça a importância dos tratados internacionais de direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.347 (2)", "page_number": 347, "discipline": "Direitos Humanos", "legal_refs": ["Art. 26 da Convenção de Viena sobre o Direito dos Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T18:13:49.570152+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=347", "doc_key": "fb38532b4539e34852606d6d7c957d37"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '8d83cb525ab3fe6bd552cca37a73c42fc0d3772c391aed8130c513d1e92e1191'),
  ('cpiuris2025::7991fc970a043e7852c759e79b41d966', 'doutrina', 'cp_iuris', 'Direitos Humanos — Compatibilização das normas internas com os instrumentos internacionais de direitos humanos', '## Compatibilização das normas internas com os instrumentos internacionais de direitos humanos

A Corte Interamericana de Direitos Humanos enfatiza a importância da compatibilização entre as normas internas do Estado e os instrumentos internacionais de direitos humanos. Além disso, destaca que a própria jurisprudência da Corte também é um paradigma para o controle de convencionalidade.

### Conceitos
- **Compatibilização**: A obrigação primária, inicial ou imediata de compatibilizar as normas internas com os instrumentos internacionais de direitos humanos
- **Controle de convencionalidade**: O processo pelo qual a Corte Interamericana de Direitos Humanos verifica se as normas do Estado estão em conformidade com os tratados e instrumentos internacionais de direitos humanos
- **Jurisprudência**: A aplicação das regras e princípios jurídicos pela Corte Interamericana de Direitos Humanos para resolver conflitos e interpretar os tratados internacionais de direitos humanos

### Referências legais
- Art. 8.1 da Convenção Interamericana de Direitos Humanos
- Súmula N da Corte Interamericana de Direitos Humanos

### Jurisprudência
- Caso Favela Nova Brasília
- Caso Empregados da Fábrica de Fogos de Santo Antônio de Jesus e Seus Familiares vs. Brasil

### Dicas de prova
- Entenda a importância da compatibilização entre as normas internas do Estado e os instrumentos internacionais de direitos humanos
- Conheça o conceito de controle de convencionalidade e como é aplicado pela Corte Interamericana de Direitos Humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.348 (1)", "page_number": 348, "discipline": "Direitos Humanos", "legal_refs": ["Art. 8.1 da Convenção Interamericana de Direitos Humanos", "Súmula N da Corte Interamericana de Direitos Humanos"], "jurisprudence": ["Caso Favela Nova Brasília", "Caso Empregados da Fábrica de Fogos de Santo Antônio de Jesus e Seus Familiares vs. Brasil"], "confidence": 0.8, "extracted_at": "2026-05-30T18:14:08.903599+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=348", "doc_key": "7991fc970a043e7852c759e79b41d966"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '328599546c255b0340afacdd37e41bea5489c7eb7326cd6d007d9d9868692ac3'),
  ('cpiuris2025::75028cbe26d494bceeb8df4f8256c9e7', 'doutrina', 'cp_iuris', 'Direitos Humanos — Efeitos da decisão no caso concreto e na segurança pública', '## Efeitos da decisão no caso concreto e na segurança pública

A decisão produz efeitos apenas no caso concreto, relacionados a ele, e não alcança a segurança pública como um todo.

### Conceitos
- **Efeito da decisão**: aplicação direta do julgamento ao caso concreto
- **Segurança Pública**: área abrangida pela decisão
- **Obrigações Gerais do Estado**: obrigações de caráter geral impostas ao Estado brasileiro

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre efeito da decisão e segurança pública como um todo
- Entendimento do alcance da decisão em relação ao caso concreto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.349 (2)", "page_number": 349, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T18:15:51.613105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=349", "doc_key": "75028cbe26d494bceeb8df4f8256c9e7"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'b15e813276f469d7fbe8246b097c7b5179ad1dc7bac0ff3824a1db1525860efe'),
  ('cpiuris2025::55f1c26724e4eb35bb8ce1192f5e218d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação Histórica e Racismo Estrutural', '## Discriminação Histórica e Racismo Estrutural

A questão discute a aplicação do conceito de discriminação histórica e racismo estrutural, relacionados à escravidão e pobreza. Além disso, aborda a decisão da Corte Interamericana de Direitos Humanos sobre o direito à liberdade de associação e a forma como o estupro é considerado uma forma de tortura.

### Conceitos
- **Discriminação Histórica**: Prática que envolve a discriminação com base em critérios históricos
