  ('cpiuris2025::a4eb4f82039ad96c2e984789ccafcbec', 'doutrina', 'cp_iuris', 'Direitos Humanos — Responsabilidade Estatal por Violações de Direitos Humanos', '## Responsabilidade Estatal por Violações de Direitos Humanos

A Corte Interamericana considerou o Estado brasileiro responsável por violações de direitos humanos em vários casos, incluindo a demarcação do território dos Povo Indígena Xucuru e a prática de trabalho forçado.

### Conceitos
- **Responsabilidade Estatal**: O Estado é responsável por violações de direitos humanos cometidas dentro de seu território.
- **Convenção Americana sobre Direitos Humanos**: Uma convenção internacional que estabelece padrões para a proteção dos direitos humanos.
- **Demarcação de Territórios Indígenas**: O processo de definição de áreas específicas para os povos indígenas.
- **Trabalho Forçado**: A prática de obrigar alguém a trabalhar sem remuneração ou contra sua vontade.
- **Súmula do Tribunal Interamericano**: Uma decisão final e não suscetível de recurso da Corte Interamericana sobre um caso específico.
- **Jurisprudência**: A coletividade das decisões e súmulas de uma corte ou tribunal.
- **Competência dos Tribunais**: A capacidade de um tribunal processar e julgar um caso específico.

### Referências legais
- Convenção Americana sobre Direitos Humanos

### Jurisprudência
- Súmula do Tribunal Interamericano sobre Trabalho Forçado
- Caso Povo Indígena Xucuru

