  ('cpiuris2025::ee4c34aaeb0e81b504b0ee916d710825', 'doutrina', 'cp_iuris', 'Direitos Humanos — Autotutela e responsabilidade dos servidores públicos', '## Autotutela e responsabilidade dos servidores públicos

A autotutela é um direito que permite aos servidores públicos qualificar e capacitar-se constantemente, garantindo a eficiência e a qualidade no desempenho de suas funções.

### Conceitos
- **Autotutela**: Direito que permite aos servidores públicos qualificar e capacitar-se constantemente
- **Responsabilidade dos servidores públicos**: Servidores públicos devem ser qualificados para atender à demanda social com capacitação específica
- **Continuidade dos serviços públicos**: Atividades executadas pelos agentes públicos não devem ser interrompidas e devem ser desempenhadas com presteza e qualidade
- **Razoabilidade**: Proporcionalidade, de maneira que os agentes públicos devem ser qualificados para atender à demanda social
- **Eficiência**: Comando constitucional que prevê a participação do usuário na administração pública direta e indireta

### Referências legais
- Art. 37, Capítulo III, da Constituição Federal

### Jurisprudência
- Súmula 646/2012 do Supremo Tribunal Federal (STF)

### Dicas de prova
- Entenda a importância da autotutela e sua relação com a responsabilidade dos servidores públicos
