  ('cpiuris2025::57e17e9d57b1b69244232164873bab28', 'doutrina', 'cp_iuris', 'Direitos Humanos — Reconhecimento de responsabilidade internacional e investigação de casos de violência policial', '## Reconhecimento de responsabilidade internacional e investigação de casos de violência policial

A sentença proferida pela Corte Interamericana de Direitos Humanos estabelece parâmetros importantes na definição da discriminação estrutural e intersecional, incluindo a consideração da pobreza e da marginalização em casos de discriminação. Além disso, a sentença também estabelece que deve ser realizado um ato público de reconhecimento de responsabilidade internacional em relação aos fatos do caso e sua posterior investigação.

### Conceitos
- **Discriminação estrutural**: Prestação de tratamento desigual a indivíduos ou grupos com base em características como raça, gênero, orientação sexual, entre outras.
- **Investigação independente**: Realização de uma investigação separada e imparcial, sem envolvimento da força pública que realizou a ação policial.

### Referências legais
- Art. 5º, caput, da CF
- Súmula 281 do STF

### Jurisprudência
- Garibaldi e outros
- Damião Ximenes Lopes

### Dicas de prova
- Entenda a discriminação estrutural e intersecional, bem como a importância da investigação independente em casos de violência policial.
- Leia atentamente as opções e escolha a que melhor se alinha com os parâmetros estabelecidos pela Corte Interamericana de Direitos Humanos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.352 (1)", "page_number": 352, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, caput, da CF", "Súmula 281 do STF"], "jurisprudence": ["Garibaldi e outros", "Damião Ximenes Lopes"], "confidence": 0.8, "extracted_at": "2026-05-30T18:21:37.684302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=352", "doc_key": "57e17e9d57b1b69244232164873bab28"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f35db58f71c522efe06b27dff3737e3d696d214e960078ed0391684cebfe59b6'),
  ('cpiuris2025::48502331ecf19edb78cf8ad417bb4cd9', 'doutrina', 'cp_iuris', 'Direitos Humanos — Investigação e responsabilidade de agentes do Estado', '## Investigação e responsabilidade de agentes do Estado

Resumo objetivo: A atuação de agentes do Estado em operações que resultam em violações dos direitos humanos, como execuções sumárias, tortura e violência sexual, é investigada e pode ser responsabilizada.

### Conceitos
- **Investigação**: Ação de determinar a veracidade de fatos
- **Responsabilidade do Estado**: O dever do Estado de responder por atos ou omissões que violam os direitos humanos
- **Direitos Humanos**: Bens e direitos inalienáveis de cada indivíduo
- **Tortura**: Prática que envolve a aplicação de medidas físicas ou psicológicas para obter confissões ou punir
- **Execução Sumária**: Morte imediata sem julgamento ou processo legal

### Referências legais
- Lei n° 6.683/1979
- Convenção Americana de Direitos Humanos

### Dicas de prova
- Distinção entre investigação e responsabilidade do Estado
- Importância da Lei de Anistia em relação à Convenção Americana de Direitos Humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.352 (2)", "page_number": 352, "discipline": "Direitos Humanos", "legal_refs": ["Lei n° 6.683/1979", "Convenção Americana de Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T18:22:41.191136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=352", "doc_key": "48502331ecf19edb78cf8ad417bb4cd9"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '75c94fcfcac174a7f499db639df4d81e666e7fb2e2c2d6bdc3fd7afdd10d37ad'),
  ('cpiuris2025::7ecd1830a3a4315dd2c6d03db7f40859', 'doutrina', 'cp_iuris', 'Direitos Humanos — Investigação Policial e Responsabilidade Internacional do Estado', '## Investigação Policial e Responsabilidade Internacional do Estado

A questão discute a responsabilidade internacional do estado em relação às violações dos direitos humanos, destacando a importância da independência das autoridades investigadoras e a responsabilidade dos órgãos ou funcionários do Estado.

### Conceitos
- **Investigação Policial**: Ação realizada pelas autoridades para esclarecer fatos relacionados a um incidente
- **Responsabilidade Internacional do Estado**: O dever do estado de cumprir com os direitos humanos e responder às violações
- **Independência das Autoridades Investigadoras**: A ausência de relação institucional ou hierárquica entre o órgão investigador e os funcionários envolvidos no incidente
- **Garantia de Justiça e Punição**: O direito das vítimas à justiça e punição dos perpetradores

### Referências legais
- Art. 7.1 da Convenção Americana de Direitos Humanos
- Art. 25.1 da Convenção Americana de Direitos Humanos
- Art. 1.1 da Convenção Americana de Direitos Humanos

### Jurisprudência
- Caso Favela Nova Brasília
- Caso Ximenes Lopes vs. Brasil

### Dicas de prova
- Reconheça a importância da independência das autoridades investigadoras em relação às violações dos direitos humanos.
- Entenda a responsabilidade internacional do estado em relação às ações atribuíveis aos órgãos ou funcionários do Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.353 (1)", "page_number": 353, "discipline": "Direitos Humanos", "legal_refs": ["Art. 7.1 da Convenção Americana de Direitos Humanos", "Art. 25.1 da Convenção Americana de Direitos Humanos", "Art. 1.1 da Convenção Americana de Direitos Humanos"], "jurisprudence": ["Caso Favela Nova Brasília", "Caso Ximenes Lopes vs. Brasil"], "confidence": 0.8, "extracted_at": "2026-05-30T18:23:28.684164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=353", "doc_key": "7ecd1830a3a4315dd2c6d03db7f40859"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '51a6b91fc0aa5a744978d508865a5ddd5b38072925fb4a6136a693f34a129b8c'),
  ('cpiuris2025::35a77ccfc57af1ed92ccedc5fe85c2e4', 'doutrina', 'cp_iuris', 'Direitos Humanos — Extensão da Anistia', '## Extensão da Anistia

A questão discute a extensão da Lei da Anistia (Lei nº 6.683/79) aos crimes praticados pelos agentes do Estado contra os que lutavam contra o Estado de exceção, com referência às decisões do STF e da Corte Interamericana de Direitos Humanos.

### Conceitos
- **Anistia**: Conceito jurídico que se refere à imunidade concedida a indivíduos ou entidades por um período determinado, geralmente após um evento político ou social, contra as consequências legais de suas ações cometidas durante esse período.
- **Lei da Anistia**: Lei brasileira que concede imunidade a indivíduos e entidades por um período determinado, geralmente após um evento político ou social, contra as consequências legais de suas ações cometidas durante esse período.
- **Extensão da Anistia**: A questão se refere à aplicação da Lei da Anistia aos crimes praticados pelos agentes do Estado contra os que lutavam contra o Estado de exceção.

### Referências legais
- Art. 107 da Constituição Federal
- Lei nº 6.683/79

### Jurisprudência
- ADPF 153/DF
- Caso Gomes Lund e outros vs. Brasil

### Dicas de prova
- Entenda a diferença entre as decisões do STF e da Corte Interamericana de Direitos Humanos.
- Avalie a extensão da Lei da Anistia aos crimes praticados pelos agentes do Estado contra os que lutavam contra o Estado de exceção.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.353 (2)", "page_number": 353, "discipline": "Direitos Humanos", "legal_refs": ["Art. 107 da Constituição Federal", "Lei nº 6.683/79"], "jurisprudence": ["ADPF 153/DF", "Caso Gomes Lund e outros vs. Brasil"], "confidence": 0.8, "extracted_at": "2026-05-30T18:24:27.266595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=353", "doc_key": "35a77ccfc57af1ed92ccedc5fe85c2e4"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ab16266110ebafa937e9cfe2a259828d487f99ac796fd5a97133bb427a2518ec'),
  ('cpiuris2025::62abd3a6488c79e8d309dec218bdb7c2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Anistia e responsabilidade por violações de direitos humanos', '## Anistia e responsabilidade por violações de direitos humanos

A Lei de Anistia brasileira estendeu anistia aos crimes praticados pelos agentes do Estado contra os que lutavam contra o Estado de exceção, mas não alcança anistias anteriormente à sua vigência consumadas. A Corte Interamericana de Direitos Humanos considerou que as disposições da Lei de Anistia carecem de efeitos jurídicos.

### Conceitos
- **Anistia**: Concessão de imunidade a processamento de crimes
- **Responsabilidade por violações de direitos humanos**: Obrigação de punir os responsáveis por violações de direitos humanos
- **Efeitos jurídicos**: Implicação legal das disposições de uma lei ou tratado

### Referências legais
- Art. 85 da Lei nº 6.683/79
- Súmula 288 do STF
- Sentença Corte Interamericana de Direitos Humanos no caso Escher e outros

### Jurisprudência
- Caso Gomes Lund e outros vs. Brasil
- Caso Trabalhadores da Fazenda Brasil Verde vs. Brasil
- Caso Ximenes Lopes vs. Brasil

### Dicas de prova
- Entenda a diferença entre anistia e imunidade a processamento de crimes
- Conheça as limitações da Lei de Anistia brasileira
