  ('cpiuris2025::233b998e5037d9066aaabeedbdedffcc', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção da Privacidade e Comunicações Telefônicas', '## Proteção da Privacidade e Comunicações Telefônicas

A Corte considerou que a comunicação telefônica está abrangida pela garantia de proteção à privacidade prevista na Convenção Americana sobre Direitos do Homem, mesmo sem previsão expressa no texto.

### Conceitos
- **Garantia de Proteção à Privacidade**: Direito fundamental que protege a vida privada das pessoas
- **Convenção Americana sobre Direitos do Homem**: Tratado internacional que estabelece direitos humanos fundamentais
- **Comunicação Telefônica**: Forma de comunicação que envolve a transmissão de informações por meio de telefone
- **Proteção da Privacidade**: Direito que protege a vida privada das pessoas

### Referências legais
- Art. 5º, X da Constituição Brasileira
- Súmula 292 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Proteção à Privacidade e Comunicações Telefônicas

### Dicas de prova
- Entenda a importância da garantia de proteção à privacidade em relação às comunicações telefônicas
- Conheça a Convenção Americana sobre Direitos do Homem e sua aplicação no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.354 (2)", "page_number": 354, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, X da Constituição Brasileira", "Súmula 292 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Proteção à Privacidade e Comunicações Telefônicas"], "confidence": 0.8, "extracted_at": "2026-05-30T18:25:56.388735+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=354", "doc_key": "233b998e5037d9066aaabeedbdedffcc"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'c82d80e307798980742662c77901860df561422fe1b6e97262f164890bdfb5d1'),
  ('cpiuris2025::aeb57feb98cdadcda696d39a6d378b73', 'doutrina', 'cp_iuris', 'Direitos Humanos — Tratados internacionais de direitos humanos e sua equivalência às emendas constitucionais', '## Tratados internacionais de direitos humanos e sua equivalência às emendas constitucionais

O Brasil considera tratados internacionais de direitos humanos equivalentes às emendas constitucionais desde a entrada em vigor da Constituição Federal de 1988.

### Conceitos
- **Esgotamento dos recursos internos**: Requisito para apresentação de exceção preliminar pelo Estado-parte
- **Prisão civil do depositário infiel**: Pena imposta ao depositário que não paga dívidas
- **Tratados supraconstitucionais**: Instrumentos normativos internacionais de caráter inclusivo e equivalência às emendas constitucionais

### Referências legais
- Art. 5º, §3º da Constituição Federal de 1988

### Jurisprudência
- Caso do Pacto de San José da Costa Rica

### Dicas de prova
- Entenda a equivalência dos tratados internacionais de direitos humanos às emendas constitucionais
- Conheça o requisito de esgotamento dos recursos internos para apresentação de exceção preliminar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.355 (1)", "page_number": 355, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, §3º da Constituição Federal de 1988"], "jurisprudence": ["Caso do Pacto de San José da Costa Rica"], "confidence": 0.8, "extracted_at": "2026-05-30T18:26:45.443076+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=355", "doc_key": "aeb57feb98cdadcda696d39a6d378b73"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '440edd7a17a139894e2f4acdf2d3603e4c8fcc35de3c6af508280bf148be136d'),
  ('cpiuris2025::8c624e1f2755f99234bc7d50cd251101', 'doutrina', 'cp_iuris', 'Direitos Humanos — Tratados Internacionais e Ordem Jurídica Nacional', '## Tratados Internacionais e Ordem Jurídica Nacional

A Constituição Federal determina a aplicabilidade dos tratados internacionais de direitos humanos, superando a legislação infraconstitucional conflitante.

### Conceitos
- **status normativo**: nível jurídico dos tratados internacionais
- **legislação infraconstitucional**: leis que não fazem parte da Constituição
- **Convenção Internacional sobre os Direitos das Pessoas com Deficiência**: convenção internacional sobre direitos humanos
- **Convenção Internacional sobre a Eliminação de todas as Formas de Discriminação Racial**: convenção internacional sobre direitos humanos

### Referências legais
- Art. 5º, §3º da CRFB/88
- Emenda Constitucional n° 45/2004

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o status normativo dos tratados internacionais e a hierarquia jurídica
- Conheça as convenções internacionais sobre direitos humanos
