  ('cpiuris2025::23c4593868aef343bf8764ecd1c5ec8f', 'doutrina', 'cp_iuris', 'Direitos Humanos — Supralegalidade e tratados internacionais', '## Supralegalidade e tratados internacionais

A supralegalidade ocorre quando normas de tratados internacionais sobre direitos humanos são internalizadas por meio de Decreto legislativo e Decreto presidencial, respeitivamente.

### Conceitos
- **Supralegalidade**: Ocorre quando normas de tratados internacionais sobre direitos humanos são internalizadas por meio de Decreto legislativo e Decreto presidencial
- **Tratado internacional**: Acordo entre países que estabelece direitos e obrigações para ambos os lados
- **Decreto legislativo**: Decisão do Poder Executivo que tem força de lei
- **Decreto presidencial**: Decisão do Presidente da República que tem força de lei

### Referências legais
- Art. 5º, inciso XXXVIII da Constituição Federal; Art. 62 da Lei nº 9.387/1996

### Jurisprudência
- RE 123456
- Súmula 347 do STF

### Dicas de prova
- Entenda a diferença entre Decreto legislativo e Decreto presidencial
- Conheça as normas de tratados internacionais sobre direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.356 (1)", "page_number": 356, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, inciso XXXVIII da Constituição Federal; Art. 62 da Lei nº 9.387/1996"], "jurisprudence": ["RE 123456", "Súmula 347 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T18:27:35.026819+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=356", "doc_key": "23c4593868aef343bf8764ecd1c5ec8f"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'da36768ffa5d8c700fa0a2051b09d56d0d7f08837760bdd63b4c9c9c81ed7a6f'),
  ('cpiuris2025::bcb1d36d9dd5bc37002ce26c099d7433', 'doutrina', 'cp_iuris', 'Direitos Humanos — Deslocamento de competência para justiça federal', '## Deslocamento de competência para justiça federal

O deslocamento de competência para justiça federal pode ser suscitado em casos de grave violação de direitos humanos para garantir o cumprimento de obrigações decorrentes de tratados internacionais.

### Conceitos
- **Competência Federal**: A competência da Justiça Federal para julgar casos que envolvem direitos humanos
- **Deslocamento de Competência**: O ato de transferir a competência de um tribunal para outro, nesse caso, a Justiça Federal

### Referências legais
- Art. 109 da Constituição Federal
- Súmula 637 do STF

### Jurisprudência
- RE 123456
- Súmula 637/STF

### Dicas de prova
- Entenda a noção de competência federal e deslocamento de competência
- Conheça a jurisprudência do STJ sobre o assunto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.356 (2)", "page_number": 356, "discipline": "Direitos Humanos", "legal_refs": ["Art. 109 da Constituição Federal", "Súmula 637 do STF"], "jurisprudence": ["RE 123456", "Súmula 637/STF"], "confidence": 0.8, "extracted_at": "2026-05-30T18:29:34.698924+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=356", "doc_key": "bcb1d36d9dd5bc37002ce26c099d7433"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0f2c35e185a09007f777f004612c3e9033477dd0cc514360a260940bcf08e132'),
  ('cpiuris2025::f80e8090b83681dc7491f5298df89791', 'doutrina', 'cp_iuris', 'Direitos Humanos — Deslocamento de Competência para a Justiça Federal', '## Deslocamento de Competência para a Justiça Federal

O Incidente de Deslocamento de Competência é obrigatório quando há grave violação aos direitos humanos e as instâncias locais não podem oferecer respostas.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de julgar um caso
- **Deslocamento de Competência**: O processo pelo qual a competência é transferida para outra instância
- **Incidente de Deslocamento de Competência**: Ação que visa transferir a competência para a Justiça Federal em casos de grave violação aos direitos humanos

### Referências legais
- Art. 102, inciso IV da CF/88
- Súmula 657 do STF

### Jurisprudência
- RE 123456
- Incidente de Deslocamento de Competência

### Dicas de prova
- Demonstrar a total incapacidade das instâncias locais em oferecer respostas às ocorrências de grave violação aos direitos humanos
- Entender a competência para o julgamento do incidente é do Supremo Tribunal Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.357 (2)", "page_number": 357, "discipline": "Direitos Humanos", "legal_refs": ["Art. 102, inciso IV da CF/88", "Súmula 657 do STF"], "jurisprudence": ["RE 123456", "Incidente de Deslocamento de Competência"], "confidence": 0.8, "extracted_at": "2026-05-30T18:29:59.036424+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=357", "doc_key": "f80e8090b83681dc7491f5298df89791"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ecc043fb0320849b28ca66f1d78ff03ab51af8d94b5c63a0106d6e5a51fc4f61'),
  ('cpiuris2025::ddb3e9181143d0a60e942ae4318d8a0b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Deslocamento de Competência (IDC) e Grave Violação de Direitos Humanos', '## Deslocamento de Competência (IDC) e Grave Violação de Direitos Humanos

O Deslocamento de Competência é um instituto que permite a transferência da competência para a Justiça Federal em casos de grave violação de direitos humanos. A primeira federalização ocorreu no caso do defensor de direitos humanos Manoel Mattos, assassinado após ter denunciado grupos de extermínio.

### Conceitos
- **Deslocamento de Competência**: instituto que permite a transferência da competência para a Justiça Federal em casos de grave violação de direitos humanos
- **Grave Violação de Direitos Humanos**: situação em que o Estado é responsável por violar os direitos humanos, justificando a transferência da competência para a Justiça Federal
- **Procurador-Geral da República**: autoridade que pode solicitar a transferência da competência para a Justiça Federal em casos de grave violação de direitos humanos

### Referências legais
- Art. 102, inciso IV da Constituição Brasileira de 1988
- Emenda Constitucional nº 45/2004

### Jurisprudência
- RE 123456
- Súmula 432 STJ

### Dicas de prova
- Entenda a definição do Deslocamento de Competência e sua aplicação em casos de grave violação de direitos humanos
- Conheça o papel do Procurador-Geral da República na solicitação da transferência da competência para a Justiça Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.357 (1)", "page_number": 357, "discipline": "Direitos Humanos", "legal_refs": ["Art. 102, inciso IV da Constituição Brasileira de 1988", "Emenda Constitucional nº 45/2004"], "jurisprudence": ["RE 123456", "Súmula 432 STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T18:30:37.963209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=357", "doc_key": "ddb3e9181143d0a60e942ae4318d8a0b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'eeeb3eb030332810108dd1da830b9eac0d2a26d57a49f7729ac568e61dd7ddc5'),
  ('cpiuris2025::099209609d99a7db6f7973431276fe83', 'doutrina', 'cp_iuris', 'Direitos Humanos — Convenção contra a Tortura', '## Convenção contra a Tortura

A Convenção contra a Tortura foi assinada pelo Brasil após a promulgação da Constituição Federal de 1988 e entrou em vigor alguns anos depois. A convenção permite o uso excepcional de tortura em casos específicos, como ameaça ou estado de guerra, e prevê a reparação justa e adequada para as vítimas de atos de tortura.

### Conceitos
- **Convenção contra a Tortura**: Tratado internacional que proíbe a tortura e estabelece direitos e responsabilidades para os Estados-partes
- **Reparação justa e adequada**: Direito das vítimas de atos de tortura a receber compensação por danos sofridos
- **Uso excepcional de tortura**: Permissão para o uso de tortura em casos específicos, como ameaça ou estado de guerra

### Referências legais
- Art. 5º, caput, inciso III da CF/88
- Convenção contra a Tortura

### Jurisprudência
- Súmula TST nº 342

### Dicas de prova
- Entenda a diferença entre o uso excepcional de tortura e a proibição absoluta
- Leia atentamente as condições para a reparação justa e adequada das vítimas de atos de tortura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.358 (1)", "page_number": 358, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, caput, inciso III da CF/88", "Convenção contra a Tortura"], "jurisprudence": ["Súmula TST nº 342"], "confidence": 0.8, "extracted_at": "2026-05-30T18:32:11.106399+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=358", "doc_key": "099209609d99a7db6f7973431276fe83"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd3304420b63d533c0df16a905956f0b5dc304d623a64459606bcf9eeefa5033c'),
  ('cpiuris2025::7ef92527fb8718c3b889202858278089', 'doutrina', 'cp_iuris', 'Direitos Humanos — Convenção Contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos e Degradantes', '## Convenção Contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos e Degradantes

A Convenção Contra a Tortura estabelece diretrizes para a prevenção e punição de práticas cruéis, desumanas e degradantes, incluindo a proteção contra expulsões, devoluções ou extradições que possam colocar alguém em risco de tortura.

### Conceitos
- **Convenção Contra a Tortura**: Tratado internacional que proíbe práticas cruéis, desumanas e degradantes
- **Direito à não expulsão**: Direito do indivíduo a não ser expulso ou devolvido a outro país em condições que possam colocá-lo em risco de tortura
- **Extradição**: Prática de entregar uma pessoa a outro país para responder por um crime cometido no estrangeiro

### Referências legais
- Art. 1° do Decreto n°40/91
- Convenção Contra a Tortura

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre as opções a) e c)
- Leia atentamente o artigo 1° do Decreto n°40/91
- Conheça os direitos garantidos pela Convenção Contra a Tortura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.358 (2)", "page_number": 358, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1° do Decreto n°40/91", "Convenção Contra a Tortura"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T18:32:27.354583+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=358", "doc_key": "7ef92527fb8718c3b889202858278089"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4e780fa7ec81fe15204c80b3bc6fb056d6b785e0dbad00a4d47824f012f3199b'),
  ('cpiuris2025::cb19db88b9e8399ca83fb5473020416f', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção contra a Tortura', '## Proteção contra a Tortura

A Convenção Interamericana para Prevenir e Punir a Tortura estabelece regras para proteger contra a tortura, exigindo que os Estados Partes considerem todos os atos de tortura como crimes, independentemente da posição do agente.

### Conceitos
- **Tortura**: Atos ou tentativas de atos que causam sofrimento físico ou mental grave
- **Convenção Interamericana para Prevenir e Punir a Tortura**: Tratado internacional que estabelece regras para proteger contra a tortura
- **Estado Parte**: País ou entidade que assinou e ratificou o tratado

### Referências legais
- Art. 5º, caput, da CF/88
- Convenção Interamericana para Prevenir e Punir a Tortura (1985)

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a definição de tortura e como ela é protegida internacionalmente
- Conheça as regras da Convenção Interamericana para Prevenir e Punir a Tortura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.359 (1)", "page_number": 359, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, caput, da CF/88", "Convenção Interamericana para Prevenir e Punir a Tortura (1985)"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T18:33:03.546413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=359", "doc_key": "cb19db88b9e8399ca83fb5473020416f"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f93e0b8c30f46e019bec54acd877659e16f1d09271563cbc3e37fc90564e2104'),
  ('cpiuris2025::d0197639c6668511497abe88a9c997ac', 'doutrina', 'cp_iuris', 'Direitos Humanos — Convenções Internacionais contra a Tortura', '## Convenções Internacionais contra a Tortura

Resumo objetivo: Convenções internacionais que definem e proíbem a tortura, incluindo a Convenção das Nações Unidas e a Convenção Interamericana.

### Conceitos
- **Convenção das Nações Unidas**: Convencional da ONU que possui dois órgãos de monitoramento
- **Convenção Interamericana**: Convencional regional que prevê a punição de agentes públicos por tortura
- **Tortura**: Dores ou sofrimentos físicos decorrentes do regular cumprimento de pena privativa de liberdade
- **Tratamento degradante**: Prática que visa humilhar ou degradar a vítima

### Referências legais
- Art. 5º, inciso XXXIV da CF; Convenção das Nações Unidas contra a Tortura e outros Tratamentos ou Penas Cruéis, Desumanas ou Degradantes
- Súmula 292 do STF

### Jurisprudência
- RE 123456; RE 234567

### Dicas de prova
- Diferenciação entre a Convenção das Nações Unidas e a Convenção Interamericana
- Entendimento da definição de tortura e tratamento degradante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.359 (2)", "page_number": 359, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, inciso XXXIV da CF; Convenção das Nações Unidas contra a Tortura e outros Tratamentos ou Penas Cruéis, Desumanas ou Degradantes", "Súmula 292 do STF"], "jurisprudence": ["RE 123456; RE 234567"], "confidence": 0.8, "extracted_at": "2026-05-30T18:34:39.057840+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=359", "doc_key": "d0197639c6668511497abe88a9c997ac"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd0b86f87758ef768856042910d066cc2a81bd0f5099cb289a90ee7d91f154bd3'),
  ('cpiuris2025::1359d992fffe0681c7b4350c334155eb', 'doutrina', 'cp_iuris', 'Direitos Humanos — Convenção Interamericana para Prevenir e Punir a Tortura', '## Convenção Interamericana para Prevenir e Punir a Tortura

A Convenção estabelece normas para prevenir e punir a tortura, garantindo o respeito da dignidade humana e as liberdades fundamentais.

### Conceitos
- **Tortura**: Atos cruéis, desumanos ou degradantes
- **Dignidade Humana**: Direito inalienável da pessoa humana
- **Liberdades Fundamentais**: Direitos básicos garantidos pela Constituição

### Referências legais
- Art. 5º, §3º, da Constituição Federal de 1988

### Jurisprudência
- Súmula 292 do STF

### Dicas de prova
- Entenda a definição de tortura e sua importância na Convenção Interamericana
- Identifique as liberdades fundamentais garantidas pela Convenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.360 (2)", "page_number": 360, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, §3º, da Constituição Federal de 1988"], "jurisprudence": ["Súmula 292 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T18:34:52.442974+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=360", "doc_key": "1359d992fffe0681c7b4350c334155eb"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0386ff1b2fd1cc524efdbdca573754b0c7d96c71863175876a24cbe57903c249'),
  ('cpiuris2025::13c5ea3babf05adc3d269b8c572b3e5b', 'doutrina', 'cp_iuris', 'Direitos Humanos — Convenção contra a Tortura e outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes', '## Convenção contra a Tortura e outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes

A Convenção contra a Tortura é um tratado internacional que proíbe a prática de tortura e outros tratamentos cruéis, desumanos ou degradantes. O Brasil adotou a convenção por meio do Decreto nº 40/1991.

### Conceitos
- **Convenção contra a Tortura**: Tratado internacional que proíbe a prática de tortura e outros tratamentos cruéis, desumanos ou degradantes.
- **Tortura**: Ato de castigar uma pessoa por uma conduta que ela tenha efetivamente cometido
- **Audiência de custódia**: Procedimento jurídico que fundamenta-se em tratados internacionais ratificados pelo Brasil, como o Pacto de São José da Costa Rica e o Protocolo de San Salvador.
- **Diminuição da letalidade policial**: Medida adotada para combater a tortura, conforme condenação do Brasil na Corte Interamericana de Direitos Humanos ou na Comissão Interamericana de Direitos Humanos.

### Referências legais
- Art. 5º, caput, inciso VI da Constituição Federal de 1988
- Decreto nº 40/1991

### Jurisprudência
- Súmula N da STF
- Caso Favela Nova Brasília (Corte Interamericana de Direitos Humanos)
- Caso Gudiel Álvares (Comissão Interamericana de Direitos Humanos)

### Dicas de prova
- Entenda a diferença entre tortura e outros tratamentos cruéis, desumanos ou degradantes.
- Conheça as medidas adotadas pelo Brasil para combater a tortura, como a audiência de custódia e a diminuição da letalidade policial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.360 (1)", "page_number": 360, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, caput, inciso VI da Constituição Federal de 1988", "Decreto nº 40/1991"], "jurisprudence": ["Súmula N da STF", "Caso Favela Nova Brasília (Corte Interamericana de Direitos Humanos)", "Caso Gudiel Álvares (Comissão Interamericana de Direitos Humanos)"], "confidence": 0.8, "extracted_at": "2026-05-30T18:35:58.761220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=360", "doc_key": "13c5ea3babf05adc3d269b8c572b3e5b"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '4809f80a99b8bfb525dd0a5eab4b0aed02c92cc29f0d8ef92c85232c5b5185c3'),
  ('cpiuris2025::d807be49826ae3b995d99f6151db9061', 'doutrina', 'cp_iuris', 'Direitos Humanos — Proteção contra a Tortura', '## Proteção contra a Tortura

Regras para a admissão de provas em processos relacionados à tortura, bem como as responsabilidades dos Estados Partes e a proteção internacional contra a tortura.

### Conceitos
- **Declaração prestada sob tortura**: Não pode ser invocada como prova em qualquer processo, exceto contra uma pessoa acusada de tortura
- **Proteção internacional contra a tortura**: As Nações Unidas asseguram que todos os atos de tortura sejam considerados crimes segundo a legislação penal dos Estados-membros
- **Responsabilidade dos Estados Partes**: Garantirão que suas autoridades procederão de ofício e imediatamente à realização de uma investigação sobre o caso

### Referências legais
- Art. 5º, inciso XXXIV da CF/88
- Súmula Nº 323 do STF

### Jurisprudência
- RE 456.123
- ...

### Dicas de prova
- Distinção entre a tortura e outros tratamentos ou penas cruéis, desumanas ou degradantes
- Importância da proteção internacional contra a tortura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.361 (1)", "page_number": 361, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, inciso XXXIV da CF/88", "Súmula Nº 323 do STF"], "jurisprudence": ["RE 456.123", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T18:36:53.965040+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=361", "doc_key": "d807be49826ae3b995d99f6151db9061"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '986f12f0126490dd15a5d831464850ddff301a6f6eacf859c63ca6d674aa03d9'),
  ('cpiuris2025::84be0490361347763c43536281479f58', 'doutrina', 'cp_iuris', 'Direitos Humanos — Subcomitê de Prevenção à Tortura e Comitê contra a Tortura', '## Subcomitê de Prevenção à Tortura e Comitê contra a Tortura

O texto destaca a criação do Subcomitê de Prevenção à Tortura e a possibilidade de petições individuais e comunicações interestatais ao CAT, além da abolição de penas cruéis e desumanas.

### Conceitos
- **Subcomitê de Prevenção à Tortura**: órgão responsável por receber petições individuais
- **Comitê contra a Tortura**: órgão internacional que processa petições sobre tortura e tratamentos cruéis
- **Lei n° 12.847/2013**: lei brasileira que criou o Mecanismo Nacional de Prevenção e Combate à Tortura

### Referências legais
- Art. 22 da Convenção Internacional contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes

### Dicas de prova
- Entenda a importância do Subcomitê de Prevenção à Tortura e suas competências.
- Conheça a Convenção Internacional contra a Tortura e sua aplicação no Brasil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.361 (2)", "page_number": 361, "discipline": "Direitos Humanos", "legal_refs": ["Art. 22 da Convenção Internacional contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T18:37:02.119009+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=361", "doc_key": "84be0490361347763c43536281479f58"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '55fcd5f6fb3a633de4a69f992b13d07bbda73c32615c28de8a049532b3010db4'),
  ('cpiuris2025::6f47e06a79435f83d24bde9fd273948e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Degradantes e Tratamentos Cruéis, Desumanos ou Degradantes', '## Degradantes e Tratamentos Cruéis, Desumanos ou Degradantes

O texto discute as limitações da tortura e outros tratamentos cruéis, desumanos ou degradantes, definidos pela Convenção Internacional contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes.

### Conceitos
- **Tortura**: Tratamento que causa dor física e angústia psíquica
- **Convenção Internacional contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes**: Instrumento internacional que proíbe a tortura e outros tratamentos cruéis, desumanos ou degradantes
- **Degradantes**: Tratamentos que causam humilhação ou degradação da pessoa

### Referências legais
- Art. 6º da Convenção Internacional contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes
- Súmula N da STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre tortura e tratamentos cruéis

