- Entenda a distinção entre sanções legítimas e tratamentos cruéis
- Conheça as limitações da Convenção Internacional contra a Tortura', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.362 (1)", "page_number": 362, "discipline": "Direitos Humanos", "legal_refs": ["Art. 6º da Convenção Internacional contra a Tortura e Outros Tratamentos ou Penas Cruéis, Desumanos ou Degradantes", "Súmula N da STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre tortura e tratamentos cruéis"], "confidence": 0.8, "extracted_at": "2026-05-30T18:38:34.367939+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=362", "doc_key": "6f47e06a79435f83d24bde9fd273948e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ae9844a22e23e50e006fc2b63489852102a00a99bbd331e2d3c8b64b1e0c5200'),
  ('cpiuris2025::c42d2975eb5bc8f8872af60076f77810', 'doutrina', 'cp_iuris', 'Direitos Humanos — Obrigação de incluir curso de prevenção à tortura nos profissionais de segurança pública', '## Obrigação de incluir curso de prevenção à tortura nos profissionais de segurança pública

A lei prevê a obrigatoriedade de incluir curso de prevenção e combate à tortura para os profissionais responsáveis pela segurança pública. Além disso, define que certas penalidades ou sofrimentos não estão compreendidos no conceito de tortura.

### Conceitos
- **Tortura**: prática de atos cruéis, desumanos e degradantes
- **Discriminação direta**: distinção ou preferência que afeta diretamente uma pessoa ou grupo
- **Discriminação indireta**: distinção ou preferência que tem efeito desigual, mas não é intencional

### Referências legais
- Art. 5º da Constituição Federal
- ...

### Jurisprudência
- Súmula 326 do STF

### Dicas de prova
- Entenda a distinção entre discriminação direta e indireta
- Conheça o conceito de tortura e suas exceções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.362 (2)", "page_number": 362, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º da Constituição Federal", "..."], "jurisprudence": ["Súmula 326 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T18:39:04.713332+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=362", "doc_key": "c42d2975eb5bc8f8872af60076f77810"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '472e0942206f5de8912777642675ac392d57eaa7a6aff4684732c8a2ef257192'),
  ('cpiuris2025::376accb1653b35af18e1ae182d5dda26', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação e Preconceito Racial', '## Discriminação e Preconceito Racial

A discriminação racial é a atribuição de tratamento diferenciado a membros de grupos racialmente identificados, com o requisito fundamental do poder para atribuir vantagens ou desvantagens por conta da raça. O racismo é uma forma sistemática de discriminação que tem a raça como fundamento e se manifesta por meio de práticas conscientes ou inconscientes.

### Conceitos
- **Discriminação racial**: Atribuição de tratamento diferenciado a membros de grupos racialmente identificados
- **Preconceito racial**: Juízo baseado em estereótipos acerca de indivíduos que pertençam a determinado grupo racializado
- **Racismo**: Forma sistemática de discriminação que tem a raça como fundamento

### Referências legais
- Art. 5 da Constituição Federal

### Jurisprudência
- Súmula 326 do STF

### Dicas de prova
- Entenda a distinção entre preconceito racial e discriminação racial
- Conheça as formas de manifestação do racismo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.363 (1)", "page_number": 363, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5 da Constituição Federal"], "jurisprudence": ["Súmula 326 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T18:39:18.007764+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=363", "doc_key": "376accb1653b35af18e1ae182d5dda26"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '54973c1d3aef4a610d3bd33b62732014156f7d8cc46ac7a19aa2e3c5ddfa39cf'),
  ('cpiuris2025::af3ed2042c883fcb44064de4afaf1da6', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação Indireta e Direta', '## Discriminação Indireta e Direta

O texto destaca a discriminação indireta como processo em que a situação específica de grupos minoritários é ignorada, enquanto a discriminação direta envolve intencionalidade explícita de discriminar pessoas. Um caso apresentado ilustra a discriminação indireta na política pública.

### Conceitos
- **Discriminação Indireta**: Processo em que a situação específica de grupos minoritários é ignorada
- **Discriminação Direta**: Intencionalidade explícita de discriminar pessoas
- **Neutralidade Racial**: Regras de ''neutralidade racial'' sem considerar diferenças sociais significativas

### Referências legais
- Art. 5 da CF
- Súmula 326/2012 STF

### Jurisprudência
- RE 123456
- Tema Repetitivo: Discriminação Indireta e Direta

### Dicas de prova
- Entenda a distinção entre discriminação indireta e direta.
- Avalie se a política pública é neutra ou não.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.363 (2)", "page_number": 363, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5 da CF", "Súmula 326/2012 STF"], "jurisprudence": ["RE 123456", "Tema Repetitivo: Discriminação Indireta e Direta"], "confidence": 0.8, "extracted_at": "2026-05-30T18:40:19.562077+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=363", "doc_key": "af3ed2042c883fcb44064de4afaf1da6"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f648377386d52d5c2ec447dd33abe9e36c37e93e5d116e364ad21b6c1155b38a'),
  ('cpiuris2025::e5befe254073f0ac06572d64d568528c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação contra a Mulher', '## Discriminação contra a Mulher

A questão discute sobre discriminação indireta e múltipla, relacionada à política de transporte de água e às regras internacionais para detentas mulheres.

### Conceitos
- **Discriminação Indireta**: A discriminação indireta ocorre quando uma política ou prática não é direta, mas tem um impacto desproporcionalmente negativo em um grupo específico.
- **Discriminação Múltipla**: A discriminação múltipla ocorre quando um indivíduo é submetido a mais de uma forma de discriminação ao mesmo tempo.

### Referências legais
- Art. 14 da Lei nº 11.340/2006 (Lei Maria da Penha)

### Jurisprudência
- Súmula 342 do STF

### Dicas de prova
- Entenda a distinção entre discriminação direta e indireta, bem como a discriminação múltipla.
- Conheça as regras internacionais para detentas mulheres e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.364 (1)", "page_number": 364, "discipline": "Direitos Humanos", "legal_refs": ["Art. 14 da Lei nº 11.340/2006 (Lei Maria da Penha)"], "jurisprudence": ["Súmula 342 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T18:40:25.178926+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=364", "doc_key": "e5befe254073f0ac06572d64d568528c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '8b7549411c491482592a369673ebd199d47ce0836f507d14cd97ba2a142ea009'),
  ('cpiuris2025::7daa6b2464ab7392c6c0d38d059825d2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direitos das Mulheres', '## Direitos das Mulheres

Regras para a proteção de mulheres em situações de violência e discriminação, incluindo direito à igualdade em funções públicas.

### Conceitos
- **Regras de Bangkok**: Sistema de orientação para a aplicação de sanções disciplares em prisões
- **Lei Maria da Penha**: Lei brasileira que protege as mulheres contra o violência doméstica e familiar

### Referências legais
- Art. 12 da Lei nº 11.340/2006
- ...

### Jurisprudência
- Convenção Internacional sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher, de 1979

### Dicas de prova
- Entenda as Regras de Bangkok e sua aplicação nas prisões
- Identifique a Lei Maria da Penha e seu papel na proteção das mulheres', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.365 (2)", "page_number": 365, "discipline": "Direitos Humanos", "legal_refs": ["Art. 12 da Lei nº 11.340/2006", "..."], "jurisprudence": ["Convenção Internacional sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher, de 1979"], "confidence": 0.8, "extracted_at": "2026-05-30T18:42:14.119331+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=365", "doc_key": "7daa6b2464ab7392c6c0d38d059825d2"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0fd0a6c563d85139b9618c04bf595caec95d69d33abb00e68fb54332f78e8665'),
  ('cpiuris2025::9279774e9b7fb141d0146099ef282615', 'doutrina', 'cp_iuris', 'Direitos Humanos — Violência contra a Mulher', '## Violência contra a Mulher

A Convenção Americana sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher estabelece deveres dos Estados-partes para combater preconceitos e violência contra a mulher, independentemente da situação da vítima.

### Conceitos
- **Convenção Americana sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher**: Tratado internacional que estabelece deveres dos Estados-partes para combater preconceitos e violência contra a mulher.
- **Violação de direitos humanos**: Ações ou omissões do Estado que violam os direitos fundamentais das pessoas, como a mulher.
- **Preconceito**: Atitude ou comportamento discriminatório contra uma pessoa ou grupo com base em características como gênero, raça, origem étnica ou condição social.
- **Violência de gênero**: Todas as formas de violência exercida por um parceiro íntimo ou familiar contra a outra.
- **Direitos das mulheres**: Direitos fundamentais que protegem e promovem a igualdade, liberdade e dignidade das mulheres.
- **Justiça social**: Princípio que busca garantir a justiça e a igualdade para todos os cidadãos, independentemente de sua situação socioeconômica ou social.
- **Omissão estatal**: Ação do Estado que não toma medidas necessárias para proteger os direitos fundamentais das pessoas.
- **Responsabilidade estatal**: A responsabilidade do Estado por suas ações ou omissões que afetam os direitos fundamentais das pessoas.

### Referências legais
- Art. 5º, inciso XXXV da Constituição de 1988
- Convenção Americana sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda o conceito de violência de gênero e seus impactos na sociedade.
- Análise da responsabilidade estatal em relação à proteção dos direitos das mulheres.
- Conhecimento do artigo 5º, inciso XXXV da Constituição de 1988 e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.364 (2)", "page_number": 364, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, inciso XXXV da Constituição de 1988", "Convenção Americana sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.9, "extracted_at": "2026-05-30T18:44:29.253437+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=364", "doc_key": "9279774e9b7fb141d0146099ef282615"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '1d18d2a9ea5b0654aa3430d8cb6984a3ffa77e6b5e5919be2aebb5387866b6cd'),
  ('cpiuris2025::1e3a4ba27623e078ba3dd06af9213b76', 'doutrina', 'cp_iuris', 'Direitos Humanos — Condições para assegurar educação e participação igualitária às mulheres', '## Condições para assegurar educação e participação igualitária às mulheres

A Convenção estabelece condições para garantir educação adequada e acesso a oportunidades para as mulheres, bem como participação igualitária em atividades físicas e culturais.

### Conceitos
- **Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher**: Instrumento internacional que estabelece normas gerais de proteção dos direitos das mulheres
- **Direito à educação**: O direito fundamental à educação, garantido pela Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher
- **Participação igualitária**: Direito das mulheres à participação igualitária em atividades físicas, culturais e sociais

### Referências legais
- Art. X da Lei Y
- Súmula N STF
- Convenção Interamericana para Prevenir, Punir e Erradicar a Violência contra a Mulher de 1994

### Jurisprudência
- RE 123456
- Tema repetitivo Convenção sobre a Eliminação de todas as Formas de Discriminação contra a Mulher

### Dicas de prova
- Entenda o conceito de direitos humanos e sua aplicação às mulheres
