  ('cpiuris2025::b1022c011f18de8c8975c6bca9f418df', 'doutrina', 'cp_iuris', 'Direitos Humanos — Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher (CEDAW)', '## Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher (CEDAW)

A CEDAW prevê medidas para combater discriminação contra mulheres, incluindo mudanças legais e internacionais.

### Conceitos
- **discriminação**: condenação injusta ou desigualdade
- **CEDAW**: Convenção sobre a Eliminação de Todas as Formas de Discriminação contra a Mulher

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo CEDAW

### Dicas de prova
- Entenda o conceito de discriminação e como a CEDAW busca combater
