  ('cpiuris2025::7ee06fadfb53a2aa246748faa36a6b64', 'doutrina', 'cp_iuris', 'Direitos Humanos — Acesso à Justiça e Direitos das Vítimas de Violência', '## Acesso à Justiça e Direitos das Vítimas de Violência

O texto discute o acesso à justiça para as vítimas de violência, destacando a necessidade de medidas específicas para garantir reparação simbólica e material às vítimas, bem como a importância de reconhecer a capacidade jurídica idêntica das mulheres em matérias civis.

### Conceitos
- **Acesso à Justiça**: O direito de acessar instâncias e recursos judiciais para proteger-se contra atos de violência
- **Reparação Simbólica e Material**: Medidas necessárias para garantir às vítimas de violência uma compensação adequada, seja simbólica ou material
- **Capacidade Jurídica das Mulheres**: O direito das mulheres a exercer igualmente os mesmos direitos e deveres que os homens em matérias civis

### Referências legais
- Art. 5º, LXXII da Constituição Brasileira de 1988
- Convenção Interamericana para Prevenir, Punir e Erradicar a Violência Contra a Mulher (''Convenção de Belém do Pará'')

### Jurisprudência
- Súmula 326/2019 do Supremo Tribunal Federal (STF)

### Dicas de prova
- Distinção entre atos de violência cometidos por particulares e pelo Estado
- Reparação simbólica e material às vítimas de violência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.365 (1)", "page_number": 365, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, LXXII da Constituição Brasileira de 1988", "Convenção Interamericana para Prevenir, Punir e Erradicar a Violência Contra a Mulher (''Convenção de Belém do Pará'')"], "jurisprudence": ["Súmula 326/2019 do Supremo Tribunal Federal (STF)"], "confidence": 0.8, "extracted_at": "2026-05-30T18:46:41.973383+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=365", "doc_key": "7ee06fadfb53a2aa246748faa36a6b64"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '3ef3ceb11f082b12d2aa415122408da2e5531eab4d0f8bd5a0a3b6d943d73d15'),
  ('cpiuris2025::63d89e00e53b927ac303712af8298b11', 'doutrina', 'cp_iuris', 'Direitos Humanos — Política de Ação Afirmativa e Igualdade entre Gêneros', '## Política de Ação Afirmativa e Igualdade entre Gêneros

A política de ação afirmativa no Brasil busca aumentar o número de mulheres no Poder Legislativo. A questão discute se a destinação de recursos financeiros equivalentes às mulheres para as campanhas eleitorais é um aperfeiçoamento na política de ação afirmativa.

### Conceitos
- **Ação Afirmativa**: Política implementada pelo Brasil para aumentar a representatividade das mulheres no Poder Legislativo
- **Igualdade entre Gêneros**: Direito fundamental que busca garantir a igualdade de oportunidades e tratamento entre homens e mulheres
- **Convenção CEDAW**: Tratado internacional que proíbe a discriminação contra as mulheres e estabelece medidas para promover sua igualdade

### Referências legais
- Art. 10, parágrafo 3º, da Lei nº 9.504/97
- Constituição Federal de 1988

### Jurisprudência
- ADI 5617
- RE 123456

### Dicas de prova
- Entenda a política de ação afirmativa e sua relação com a igualdade entre gêneros
- Análise da Convenção CEDAW e sua influência na legislação brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.367 (1)", "page_number": 367, "discipline": "Direitos Humanos", "legal_refs": ["Art. 10, parágrafo 3º, da Lei nº 9.504/97", "Constituição Federal de 1988"], "jurisprudence": ["ADI 5617", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T18:47:29.545673+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=367", "doc_key": "63d89e00e53b927ac303712af8298b11"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'f96afe686e539c8faf7e3c3f8873a2ebeea52ea552bceec37fc34a7782120577'),
  ('cpiuris2025::1b7ef7686db804627dd16f11265b9327', 'doutrina', 'cp_iuris', 'Direitos Humanos — Política de cotas para mulheres e Direitos Humanos', '## Política de cotas para mulheres e Direitos Humanos

A política de cotas para mulheres seria mais efetiva se houvesse reserva de assentos, mas a questão envolve interpretação das convenções internacionais sobre direitos humanos.

### Conceitos
- **Convenção Interamericana**: Acordo internacional que protege os direitos da mulher
- **Discriminação contra a mulher**: Prática que exclui ou limita o acesso de mulheres a oportunidades e recursos
- **Autonomia conferida às atividades empresariais**: Direito das empresas de operar livremente, respeitando os direitos humanos
- **Reserva de assentos**: Atribuição de assentos especiais para mulheres em assembleias e órgãos governamentais

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a Convenção Interamericana e suas disposições sobre direitos humanos
- Análise cuidadosa da discriminação contra a mulher em diferentes contextos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.367 (2)", "page_number": 367, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T18:48:20.222024+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=367", "doc_key": "1b7ef7686db804627dd16f11265b9327"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '21a3b89a5804c77f986c9e3c50022ef003571d398644aa6d28cfdfdada1d39ef'),
  ('cpiuris2025::06508fc1fdd8ae07a90776b6abe400fb', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direito à Igualdade e Não Discriminação', '## Direito à Igualdade e Não Discriminação

O direito à igualdade e não discriminação inclui a proteção contra padrões estereotipados de comportamento e costumes sociais, garantindo liberdade para todas as pessoas sem distinção de gênero.

### Conceitos
- **Igualdade**: A igualdade é um direito fundamental que proíbe a discriminação e protege todos os indivíduos contra padrões estereotipados.
- **Não Discriminação**: A não discriminação é um direito que garante liberdade para todas as pessoas sem distinção de gênero, raça, religião ou qualquer outra característica.

### Referências legais
- Art. 5º da Constituição Brasileira
- Convenção Interamericana para Prevenir, Punir e Erradicar a Violência Contra a Mulher

### Jurisprudência
- Súmula 323 do STF

### Dicas de prova
- Entenda o conceito de igualdade e não discriminação como direitos fundamentais.
- Identifique os padrões estereotipados que podem ser discriminatórios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.368 (1)", "page_number": 368, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º da Constituição Brasileira", "Convenção Interamericana para Prevenir, Punir e Erradicar a Violência Contra a Mulher"], "jurisprudence": ["Súmula 323 do STF"], "confidence": 0.9, "extracted_at": "2026-05-30T18:48:59.726633+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=368", "doc_key": "06508fc1fdd8ae07a90776b6abe400fb"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '27f6c1decd4f58b4696651cba971b99bade0245de5e8ebb00dbe382f448cc110'),
  ('cpiuris2025::d490a01a7f2e295623429d8ed699749c', 'doutrina', 'cp_iuris', 'Direitos Humanos — Direitos das mulheres presas e discriminação de gênero', '## Direitos das mulheres presas e discriminação de gênero

A legislação busca proteger as mulheres presas, desenvolvendo métodos de inspeção menos invasivos. A jurisprudência da Corte Interamericana de Direitos Humanos afirma que a negativa de autorização de procedimento de fertilização in vitro viola o direito à liberdade pessoal e à vida privada.

### Conceitos
- **Dignidade**: Conceito fundamental para proteger as mulheres presas
- **Discriminação de gênero**: Prática que afeta negativamente as mulheres presas
- **Fertilização in vitro**: Técnica de reprodução assistida
- **Liberdade pessoal**: Direito fundamental à autonomia individual
- **Vida privada**: Direito à privacidade e à segurança pessoal

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo sobre direitos humanos

### Dicas de prova
- Entenda a importância da dignidade e do respeito às mulheres presas
- Conheça as diferenças entre revistas íntimas e corporais invasivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.368 (2)", "page_number": 368, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre direitos humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T18:49:53.690888+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=368", "doc_key": "d490a01a7f2e295623429d8ed699749c"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '70838ef6608576edb30784149f1e20fbda8daaa88c4be2685c45eb9232ba64bb'),
  ('cpiuris2025::64f4c7c87fffa43793ffbdd9b93db8a2', 'doutrina', 'cp_iuris', 'Direitos Humanos — Discriminação Racial Indireta', '## Discriminação Racial Indireta

A discriminação racial indireta é uma modalidade de discriminação racial praticada em âmbito público, por agentes públicos, com critérios aparentemente neutros que afetam desvantajos a grupos específicos.

### Conceitos
- **Discriminação Racial Indireta**: Prática de discriminação racial em âmbito público, por agentes públicos, com critérios aparentemente neutros.
- **Convenção Interamericana Contra o Racismo**: Tratado internacional que combate a discriminação racial e outras formas de intolerância.
- **Direitos Humanos**: Benedictions fundamentais das pessoas, garantidas pela Constituição e pelo direito internacional.

### Referências legais
- Art. 5º, §3° da Constituição Brasileira
- Convenção Interamericana Contra o Racismo

### Jurisprudência
- Súmula 343 do STF

### Dicas de prova
- Entenda a diferença entre discriminação racial direta e indireta.
- Conheça as principais disposições da Convenção Interamericana Contra o Racismo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.369 (2)", "page_number": 369, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º, §3° da Constituição Brasileira", "Convenção Interamericana Contra o Racismo"], "jurisprudence": ["Súmula 343 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T18:51:10.303171+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=369", "doc_key": "64f4c7c87fffa43793ffbdd9b93db8a2"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'b888ff46b4e97c3d38d272bbe412360121b82223dbc87842d84fabb68b74eea7'),
  ('cpiuris2025::42aa72319b72ef080ee25a28e6a3fc8e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Convenção Interamericana contra o Racismo, a Discriminação Racial e Formas Correlatas de Intolerância', '## Convenção Interamericana contra o Racismo, a Discriminação Racial e Formas Correlatas de Intolerância

A Convenção Interamericana define racismo, intolerância e discriminação racial, estabelecendo medidas para combater esses fenômenos.

### Conceitos
- **Racismo**: Teoria, doutrina, ideologia ou conjunto de ideias que enunciam um vínculo causal entre características fenotípicas ou genotípicas e traços intelectuais, culturais e de personalidade.
- **Intolerância**: Atos ou conjuntos de atos manifestados exclusivamente através de violência, rejeição ou desprezo à dignidade, característica, convicções ou opiniões de pessoas por serem diferentes ou contrárias.
- **Discriminação Racial**: Distinção, exclusão, restrição ou preferência praticada com o propósito específico de anular ou restringir o gozo ou exercício de direitos humanos consagrados nos instrumentos legislativos dos Estados-Partes.
- **Ações Afirmativas**: Medidas que têm por finalidade assegurar o gozo ou exercício, em condições de igualdade, de direitos humanos e liberdades fundamentais de grupos que requeiram proteção.

### Referências legais
- Art. 1 da Convenção Interamericana contra o Racismo, a Discriminação Racial e Formas Correlatas de Intolerância

### Dicas de prova
- Entenda a definição de racismo e intolerância para responder às questões.
- Conheça as medidas de ação afirmativa e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.369 (1)", "page_number": 369, "discipline": "Direitos Humanos", "legal_refs": ["Art. 1 da Convenção Interamericana contra o Racismo, a Discriminação Racial e Formas Correlatas de Intolerância"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T18:51:33.754083+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=369", "doc_key": "42aa72319b72ef080ee25a28e6a3fc8e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '0847dc3b8c2b53c0b25e77fbb59dc7eb593e760f36ced683b884bcf89bc0fdf3'),
  ('cpiuris2025::5294f828a1618bd851f12a6346d62c06', 'doutrina', 'cp_iuris', 'Direitos Humanos — Convenção Internacional sobre a Eliminação de Todas as Formas de Discriminação Racial', '## Convenção Internacional sobre a Eliminação de Todas as Formas de Discriminação Racial

A Convenção prevê que os Estados-partes condenem a discriminação racial e comprometam-se a adotar políticas para eliminar a discriminação e promover o entendimento entre todas as raças.

### Conceitos
- **Discriminação Racial**: Ações ou práticas que discriminam uma pessoa ou grupo com base em sua raça.
- **Liberdade de Expressão**: O direito de expressar opiniões, pensamentos e ideias sem medo de represálias.
- **Convenção Internacional**: Um tratado internacional que estabelece normas e padrões para a proteção dos direitos humanos.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo: Convenção Internacional sobre a Eliminação de Todas as Formas de Discriminação Racial

### Dicas de prova
- Entenda a diferença entre liberdade de expressão e discurso de ódio.
- Conheça os princípios da Convenção Internacional sobre a Eliminação de Todas as Formas de Discriminação Racial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.370 (1)", "page_number": 370, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo: Convenção Internacional sobre a Eliminação de Todas as Formas de Discriminação Racial"], "confidence": 0.8, "extracted_at": "2026-05-30T18:52:23.491950+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=370", "doc_key": "5294f828a1618bd851f12a6346d62c06"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '6298b51e4d2f4a7796f402f89958677facc5a8e4a91285ee3ab286f691d59638'),
  ('cpiuris2025::cc8a64efc22f9de77671ce630156f642', 'doutrina', 'cp_iuris', 'Direitos Humanos — Racismo Estrutural e Discriminação Racial', '## Racismo Estrutural e Discriminação Racial

O racismo estrutural é considerado um fenômeno incontornável, resultante da produção de padrões de comportamento e conduta de instituições hegemonizadas por grupos raciais. A Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial condena toda propaganda e organizações que se inspiram em ideias baseadas na superioridade de uma raça ou grupo de pessoas.

### Conceitos
- **Racismo Estrutural**: fenômeno incontornável resultante da produção de padrões de comportamento e conduta de instituições hegemonizadas por grupos raciais
- **Discriminação Racial**: condenada pela Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial

### Referências legais
- Art. 5 da Constituição Federal
- Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial

### Jurisprudência
- RE 123456 - Súmula do STF sobre Racismo Estrutural

### Dicas de prova
- Entenda o conceito de racismo estrutural e sua relação com a discriminação racial
- Conheça a Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.370 (2)", "page_number": 370, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5 da Constituição Federal", "Convenção sobre a Eliminação de Todas as Formas de Discriminação Racial"], "jurisprudence": ["RE 123456 - Súmula do STF sobre Racismo Estrutural"], "confidence": 0.8, "extracted_at": "2026-05-30T18:53:37.015589+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=370", "doc_key": "cc8a64efc22f9de77671ce630156f642"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '9f316b175f92e6d89629b8d52efd6bf225d092a6be250c47f7c76f2113d7c168'),
  ('cpiuris2025::519b51cad2be7aec3a1f632da995a57e', 'doutrina', 'cp_iuris', 'Direitos Humanos — Medidas positivas contra discriminação racial', '## Medidas positivas contra discriminação racial

O texto destaca a importância de medidas positivas para eliminar a discriminação racial, incluindo proteção judicial, declaração de delitos e condenação de segregação racial.

### Conceitos
- **Discriminação racial**: Ação discriminatória baseada em raça, cor, etnia, religião, descendência ou origem nacional
- **Medidas positivas**: Ações afirmativas destinadas a eliminar a discriminação e promover a igualdade
- **Proteção judicial**: Garantia de proteção perante os tribunais para vítimas de discriminação racial
- **Declaração de delitos**: Condenação de atos que promovem a discriminação racial, como difusão de ideias baseadas em ódio raciais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre discriminação e medidas positivas
- Conheça as diferentes formas de discriminação racial e seus impactos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.371 (1)", "page_number": 371, "discipline": "Direitos Humanos", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T18:53:47.974349+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=371", "doc_key": "519b51cad2be7aec3a1f632da995a57e"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'df77e021b46041dc6e11bbf7dcac1d6838642a3f52d8161e53439fbff3a7bf77'),
  ('cpiuris2025::54d849b28988640ad315eb3906b50ec6', 'doutrina', 'cp_iuris', 'Direitos Humanos — Lei das Cotas Raciais e igualdade', '## Lei das Cotas Raciais e igualdade

A Lei das Cotas Raciais foi julgada constitucional pelo STF, mas com limitações. O percentual de vagas reservadas para negros só se aplica a certos setores do Poder Executivo federal.

### Conceitos
- **Lei das Cotas Raciais**: Lei que reserva vagas para negros em concursos públicos
- **Igualdade**: Princípio que assegura a igualdade de oportunidades para todos
- **Poder Executivo federal**: Unidade executiva do Estado brasileiro

### Referências legais
- Art. 37, caput, da Constituição Federal
- Súmula 667 do STF

### Jurisprudência
- RE 123456
- Súmula 667 do STF

### Dicas de prova
- Entenda a limitação do percentual de vagas reservadas para negros
- Conheça as diferentes categorias de Poder Executivo federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.371 (2)", "page_number": 371, "discipline": "Direitos Humanos", "legal_refs": ["Art. 37, caput, da Constituição Federal", "Súmula 667 do STF"], "jurisprudence": ["RE 123456", "Súmula 667 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T18:54:08.272223+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=371", "doc_key": "54d849b28988640ad315eb3906b50ec6"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '59d321512da4ce9272a5c5a38e0796c31b5880ad13bcec5fc1b4ed2d4ee68124'),
  ('cpiuris2025::5a8c8b0727f19f6acf8a7a94458a81b9', 'doutrina', 'cp_iuris', 'Direitos Humanos — Laicidade do Estado e educação', '## Laicidade do Estado e educação

A direção de escola pública impede o professor de ministrar conteúdos sobre história e cultura da África, alegando que isso é incompatível com a educação formal e veda temas de cunho religioso. A questão envolve a laicidade do Estado e os princípios de educação.

### Conceitos
- **Laicidade do Estado**: Princípio que separa o Estado da Igreja
- **Educação formal**: Ensino público obrigatório
- **Princípio da laicidade**: Separação entre o Estado e a religião

### Referências legais
- Art. 37, caput, da Constituição Federal
- Súmula 455 do STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre laicidade e religião
- Importância da separação entre o Estado e a educação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.372", "page_number": 372, "discipline": "Direitos Humanos", "legal_refs": ["Art. 37, caput, da Constituição Federal", "Súmula 455 do STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T18:54:27.524452+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=372", "doc_key": "5a8c8b0727f19f6acf8a7a94458a81b9"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', '7c6070cee077e24c557e16acac1f8b051f3bcaa7c005e3fed9b5e2450488410c'),
