  ('cpiuris2025::be61e56b24d595e106e42e279b90919f', 'doutrina', 'cp_iuris', 'Direitos Humanos — Ações Diretas e Constitucionais', '## Ações Diretas e Constitucionais

Resumo de ações diretas e constitucionais, incluindo ADIs, ADCs, ADOs, AgRg''s e HC''s.

### Conceitos
- **ADI**: Ação Direta de Inconstitucionalidade
- **ADC**: Ação Direta de Constitucionalidade
- **ADO**: Ação de Descumprimento de Preceito Fundamental
- **AgRg**: Agravo no REsp, AREsp ou HC
- **HC**: Habeas Corpus

### Referências legais
- Art. 5º da CF/88
- Súmula 634 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Ações Diretas e Constitucionais

### Dicas de prova
- Entenda a diferença entre ADI, ADC e ADO.
- Conheça as formas de agravo nos REsp, AREsp e HC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.375", "page_number": 375, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5º da CF/88", "Súmula 634 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Ações Diretas e Constitucionais"], "confidence": 0.8, "extracted_at": "2026-05-30T18:56:54.509152+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=375", "doc_key": "be61e56b24d595e106e42e279b90919f"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'd32123490551b67dd58d36ffdcafd40f0f991de39028978756859bf8667af5c8'),
  ('cpiuris2025::96b8dbfe41d3ad9347126851baefd1ed', 'doutrina', 'cp_iuris', 'Direitos Humanos — Questões de Direitos Humanos', '## Questões de Direitos Humanos

Resumo de questões de direitos humanos, com opções de resposta e resultados.

### Conceitos
- **Direito à Vida**: O direito à vida é um dos direitos humanos fundamentais.
- **Garantia Constitucional**: A garantia constitucional é um mecanismo que protege os direitos humanos.
- **Proteção de Minorias**: A proteção de minorias é fundamental para garantir a igualdade e a justiça.
- **Direito à Liberdade**: O direito à liberdade é um dos direitos humanos mais importantes.
- **Revisão de Decisões**: A revisão de decisões é um processo que garante a justiça e a igualdade.
- **Proteção de Crianças**: A proteção de crianças é fundamental para garantir sua segurança e bem-estar.
- **Direito à Saúde**: O direito à saúde é um dos direitos humanos mais importantes.
- **Garantia de Igualdade**: A garantia de igualdade é fundamental para garantir a justiça e a igualdade.

### Referências legais
- Art. 5 da Constituição Brasileira
- Súmula 326 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Direitos Humanos

### Dicas de prova
- Perguntas que envolvem direitos humanos fundamentais.
- Importância da garantia constitucional e proteção de minorias.
- Revisão de decisões é fundamental para garantir a justiça e igualdade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.374", "page_number": 374, "discipline": "Direitos Humanos", "legal_refs": ["Art. 5 da Constituição Brasileira", "Súmula 326 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Direitos Humanos"], "confidence": 0.8, "extracted_at": "2026-05-30T18:57:51.679593+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=374", "doc_key": "96b8dbfe41d3ad9347126851baefd1ed"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'adf1b8ef2de5bc4ac2a0e4b174852751ceaa44ddef16dfab4c67d2b7eff2ceeb'),
  ('cpiuris2025::2c9dd4f06fce60412fa13a797d99cc5d', 'doutrina', 'cp_iuris', 'Direitos Humanos — Referências Bibliográficas no Processo Penal', '## Referências Bibliográficas no Processo Penal

