  ('cpiuris2025::0dc87b6c17ff7b09a99dc7d0420f1ecb', 'doutrina', 'cp_iuris', 'Direitos Humanos — Leis e Tratados de Direitos Humanos', '## Leis e Tratados de Direitos Humanos

Lista de leis e tratados internacionais relacionados aos direitos humanos, incluindo convenções e declarações universais.

### Conceitos
- **Convenção Americana de Direitos Humanos**: Pacto de São José da Costa Rica
- **Declaração Universal dos Direitos Humanos**: Declaração fundamental que estabelece os direitos e liberdades fundamentais das pessoas
- **Convenção Internacional para a eliminação de todas as formas de discriminação racial (CERD)**: Tratado internacional que proíbe a discriminação racial
- **Convenção sobre a eliminação de todas as formas de discriminação contra a mulher**: Tratado internacional que combate a discriminação contra a mulher
- **Convenção Internacional sobre os Direitos das Pessoas com Deficiência (Convenção de Nova York)**: Tratado internacional que protege os direitos das pessoas com deficiência

### Referências legais
- Lei 5.172/1966
- Lei 6.683/1979
- Lei 8.069/1990
- Lei 8.742/1993
- Lei 9.140/1995
- Lei 7.716/1989
- Lei Complementar 13.146/2015
- Lei Complementar 142/2013

### Jurisprudência
- RE 349.703/RS
- RE 567.985/MT
- Súmula 7/STJ
- Súmula 22/STJ
- Súmula 125/STJ

### Dicas de prova
- Reconheça as convenções e declarações internacionais relacionadas aos direitos humanos.
- Entenda a importância das leis complementares e a discriminação racial.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf", "source_ref": "IURIS - Direitos Humanos - 2025.pdf · p.376", "page_number": 376, "discipline": "Direitos Humanos", "legal_refs": ["Lei 5.172/1966", "Lei 6.683/1979", "Lei 8.069/1990", "Lei 8.742/1993", "Lei 9.140/1995", "Lei 7.716/1989", "Lei Complementar 13.146/2015", "Lei Complementar 142/2013"], "jurisprudence": ["RE 349.703/RS", "RE 567.985/MT", "Súmula 7/STJ", "Súmula 22/STJ", "Súmula 125/STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T18:59:22.962209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Humanos - 2025.pdf#page=376", "doc_key": "0dc87b6c17ff7b09a99dc7d0420f1ecb"}'::jsonb, '{"materia": "Direitos Humanos"}'::jsonb, 'cp_iuris_2025', 'ca328a5ae62536b4e1dbe202dfcd0fa38f7769a33a8b70dbfbeed15643fb6c88'),
