  ('cpiuris2025::ce59ccae1c073ece7f8f10e345e1fe26', 'doutrina', 'cp_iuris', 'Direitos Internacional — Introdução ao Direito Internacional', '## Introdução ao Direito Internacional

Resumo objetivo: O Direito Internacional é um sistema jurídico que regula as relações entre os Estados e outras entidades internacionais. É uma disciplina que estuda as regras e normas que governam a conduta dos Estados em relação uns aos outros.

### Conceitos
- **Direito Internacional**: Sistema jurídico que regula as relações entre os Estados e outras entidades internacionais.
- **Relações Internacionais**: Interatividade entre os Estados e outras entidades internacionais.

### Referências legais
- Art. 1 da Convenção de Viena sobre o Direito dos Tratados
- Súmula 441 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: soberania nacional

### Dicas de prova
- Entenda a definição de Direito Internacional e suas principais características.
- Conheça as regras básicas do Direito Internacional, como a soberania nacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.2", "page_number": 2, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1 da Convenção de Viena sobre o Direito dos Tratados", "Súmula 441 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: soberania nacional"], "confidence": 0.8, "extracted_at": "2026-05-30T18:59:40.482461+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=2", "doc_key": "ce59ccae1c073ece7f8f10e345e1fe26"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '92fdafac9185cae2adbdf5ea3b827646410fe2a92e95dba6fb3f6abe961322da'),
  ('cpiuris2025::60a42363900da03a0a3b2c259ff6d617', 'doutrina', 'cp_iuris', 'Direitos Internacional — Noções Históricas e Conceito de Direito Internacional', '## Noções Históricas e Conceito de Direito Internacional

Discute as noções históricas e o conceito do direito internacional, destacando a dualidade entre sociedade e comunidade internacionais.

### Conceitos
- **Tese Dualista**: Teoria que considera o direito internacional como uma criação da sociedade internacional
- **Tese Pluralista**: Teoria que considera o direito internacional como um sistema de leis estatais
- **Tese Monista**: Teoria que considera o direito internacional como uma fonte de direitos objetivos

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre tese dualista e pluralista
- Conheça as principais teorias do fundamento do direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.4 (1)", "page_number": 4, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:00:57.161924+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=4", "doc_key": "60a42363900da03a0a3b2c259ff6d617"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd766f9cf0dad2908729e91eac08ee0917665ea92bcc8c085974eabd808017194'),
  ('cpiuris2025::5f352e435463260c5e3820cdddfb6d8a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Classificação', '## Classificação

A classificação é um aspecto fundamental dos tratados internacionais, sendo objeto de estudo neste capítulo.

### Conceitos
- **Tratado**: Acordo internacional que tem por objetivo a cooperação ou a solução de problemas comuns.
- **Convenção**: Acordo internacional que visa a criação de um direito subjetivo para o Estado ou pessoa jurídica.
- **Tratado bilateral**: Acordo internacional entre dois Estados.
- **Tratado multilateral**: Acordo internacional com mais de dois Estados.
- **Tratado regional**: Acordo internacional que visa a cooperação entre Estados de uma região específica.
- **Tratado de neceidade**: Acordo internacional que visa a solução de problemas urgentes ou de interesse comum.

### Referências legais
- Art. 46 da Carta das Nações Unidas

### Dicas de prova
- Entenda a classificação dos tratados internacionais.
- Destaque a importância da classificação nos acordos internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.4 (3)", "page_number": 4, "discipline": "Direitos Internacional", "legal_refs": ["Art. 46 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:01:32.605721+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=4", "doc_key": "5f352e435463260c5e3820cdddfb6d8a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f09a554f5404eeb9976435ae604e7ebfad0a1cd9e61e2f8318bab01accba2af1'),
  ('cpiuris2025::a4717e071ff0df0594ac28369bcfa7a2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Costume Internacional', '## Costume Internacional

Descreve os elementos e classificações do costume internacional, bem como sua aplicabilidade e relações com tratados internacionais.

### Conceitos
- **Elementos do costume internacional**: Princípios e regras que compõem o costume internacional
- **Classificações dos costumes internacionais**: Categorias ou categorias utilizadas para classificar os costumes internacionais
- **Prova dos costumes**: Métodos legais utilizados para comprovar a existência de um costume internacional
- **Derrogação dos costumes internacionais**: Situações em que o costume internacional pode ser derogado por outros meios legais
- **Aplicabilidade do costume internacional em âmbito interno**: Regras que determinam a aplicação do costume internacional em contextos internos

