  ('cpiuris2025::66685ba201392fd5926337e106d4ad7d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Condições de validade e outros aspectos dos tratados internacionais', '## Condições de validade e outros aspectos dos tratados internacionais

Resumo objetivo: Este trecho aborda as condições de validade, processos de elaboração, vigência, aplicação, interpretação, alteração, suspensão e fim dos tratados internacionais, bem como as normas de jus cogens.

### Conceitos
- **Tratado internacional**: Acordo entre Estados
- **Condições de validade**: Requisitos necessários para a entrada em vigor de um tratado
- **Jus cogens**: Normas fundamentais do direito internacional que não podem ser violadas

### Referências legais
- Art. 59 da Convenção de Viena sobre Tratados de Relações entre Estados
- ...

