  ('cpiuris2025::e48313e188e5b8d6db5fbc3dc6cd14c0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Nacionalidade e Relações Diplomáticas', '## Nacionalidade e Relações Diplomáticas

