### Conceitos
- **Nacionalidade**: Conceito jurídico que define a relação entre um Estado e seus cidadãos.
- **Quase-nacionalidade**: Conceito que equipara os portugueses no exterior à nacionalidade portuguesa.
- **Relações diplomáticas**: Conexões entre dois ou mais Estados, regulamentadas por acordos bilaterais.

### Referências legais
- Art. 13 da Convenção de Viena sobre Relações Diplomáticas

