  ('cpiuris2025::942d980dbca598514af2c1d71400ad31', 'doutrina', 'cp_iuris', 'Direitos Internacional — Termos relacionados a sanções econômicas', '## Termos relacionados a sanções econômicas

Sanções econômicas impostas a um país, incluindo embargo, bloqueio e boicote.

### Conceitos
- **Embargo**: Restrição imposta por um país a importações ou exportações de bens ou serviços de outro país.
- **Bloqueio**: Medida adotada por um país para congelar os ativos e recursos de outra nação.
- **Boicote**: Ação econômica tomada por um país para protestar contra uma política ou ação de outro país.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferenciar entre embargo e bloqueio
- Entender o conceito de boicote como uma ação econômica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.6 (3)", "page_number": 6, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:04:31.405318+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=6", "doc_key": "942d980dbca598514af2c1d71400ad31"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7ca5ba594ee6d603ccccbe55675866b77227a582127f3c406c71a99c3d14f8df'),
  ('cpiuris2025::b88f20db5737c6bf1a80f4d8fa9c4eef', 'doutrina', 'cp_iuris', 'Direitos Internacional — Solução de Controvérsias Internacionais', '## Solução de Controvérsias Internacionais

Discute os meios pacíficos e não pacíficos de solução de controvérsias internacionais, incluindo negociações diplomáticas, consultas, inquérito, bons ofícios, mediação, conciliação, arbitragem e soluções judiciais.

### Conceitos
- **Negociações Diplomáticas**: Negociações entre os Estados para resolver controvérsias
- **Consultas**: Encontro entre os Estados para discutir uma questão específica
- **Inquérito**: Investigação sobre um fato ou situação
- **Bons de Ofícios**: Solicitação formal por parte de um Estado a outro para resolver uma controvérsia
- **Mediação**: Processo em que um terceiro neutral ajuda a encontrar uma solução
- **Conciliação**: Negociação direta entre as partes para resolver uma controvérsia
- **Arbitragem**: Decisão de um terceiro neutro sobre uma questão em disputa
- **Soluções Judiciais**: Decisões de tribunais internacionais

### Referências legais
- Art. 36 da Convenção de Viena sobre Relações de Tratados

### Dicas de prova
- Entenda a diferença entre meios pacíficos e não pacíficos de solução de controvérsias
- Conheça as diferentes formas de mediação e conciliação
- Aprenda a aplicar o artigo 36 da Convenção de Viena sobre Relações de Tratados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.6 (2)", "page_number": 6, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36 da Convenção de Viena sobre Relações de Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:04:52.842157+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=6", "doc_key": "b88f20db5737c6bf1a80f4d8fa9c4eef"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fb6f78dedd38991ce7cc64b546ed3f53e94ce8cd84787d633dddd2b1a3d87f98'),
  ('cpiuris2025::f7a99126ac65264f9449f49a46d6d819', 'doutrina', 'cp_iuris', 'Direitos Internacional — Estrutura do TPI', '## Estrutura do TPI

