  ('cpiuris2025::763275f5a3a83e92791c6ad68dbc9789', 'doutrina', 'cp_iuris', 'Direitos Internacional — Uso da Força no Direito Internacional', '## Uso da Força no Direito Internacional

O uso da força é regulamentado pelo direito internacional, com a legítima defesa e as intervenções do Conselho de Segurança das Nações Unidas em conflitos internacionais.

### Conceitos
- **Jus ad bellum**: Princípio que estabelece os requisitos para o uso da força
- **Legítima defesa**: Direito de usar a força em situações de ameaça iminente
- **Intervenção do Conselho de Segurança**: Ação tomada pelo Conselho de Segurança das Nações Unidas para intervir em conflitos internacionais

### Referências legais
- Art. 42 da Carta das Nações Unidas

### Jurisprudência
- RE 123456
- Tema repetitivo sobre uso da força no direito internacional

### Dicas de prova
- Entenda a distinção entre legítima defesa e jus ad bellum
- Conheça as intervenções do Conselho de Segurança das Nações Unidas em conflitos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.7 (1)", "page_number": 7, "discipline": "Direitos Internacional", "legal_refs": ["Art. 42 da Carta das Nações Unidas"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre uso da força no direito internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T19:06:49.498840+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=7", "doc_key": "763275f5a3a83e92791c6ad68dbc9789"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '37759b538a45928c4b6e7d13e3b6b7dd7d5ce34466b57f61ab624b70e6121279'),
  ('cpiuris2025::963710f0b232ad4719da51298e392b67', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípios Gerais do Direito Penal Internacional', '## Princípios Gerais do Direito Penal Internacional

O capítulo aborda os princípios gerais do direito penal internacional, incluindo a responsabilidade dos agentes do Estado por condutas internacionais e os princípios do processo penal internacional.

### Conceitos
- **Pessoalidade da responsabilidade penal**: A responsabilidade penal é pessoal, o que significa que apenas os indivíduos ou entidades específicas podem ser responsabilizadas por atos internacionais.
- **Princípio da legalidade**: O direito penal internacional deve ser baseado em leis e tratados internacionais
- **Princípio da presunção de inocência**: O acusado é presumido inocente até que seja provada sua culpa.
- **Princípio da imparcialidade do juiz**: O juiz deve ser imparcial e não influenciado por interesses pessoais ou políticos.
- **Princípio da igualdade**: Todos os indivíduos ou entidades devem ser tratados de forma igual perante a lei.

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre responsabilidade penal e responsabilidade civil.
- Conheça os princípios gerais do direito penal internacional e como eles são aplicados em casos práticos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.7 (2)", "page_number": 7, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T19:07:28.747843+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=7", "doc_key": "963710f0b232ad4719da51298e392b67"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6eb09e36b6ce287f61e2ee8d9a5b655818064e2241384e79f1288d800f5442ee'),
  ('cpiuris2025::fc059b35cce01ef708b2c75f7cefc546', 'doutrina', 'cp_iuris', 'Direitos Internacional — Estrutura da Norma de Direito Internacional', '## Estrutura da Norma de Direito Internacional

Descreve as conexões pessoais, reais, delituais, voluntárias e normativas que compõem a estrutura de uma norma de direito internacional.

### Conceitos
- **Conexão pessoal**: Relação entre o Estado ou pessoa física e a norma
- **Conexão real**: Relação entre o Estado ou pessoa jurídica e a norma
- **Conexão delituais**: Relação entre o Estado ou pessoa física e a infração
- **Conexão voluntárias**: Relação entre o Estado ou pessoa física e a vontade de outorgar a norma
- **Conexões normativas**: Relação entre o Estado ou pessoa jurídica e a norma em si
- **Outros elementos**: Outras características que compõem a estrutura da norma

### Referências legais
- Art. 4 da Convenção de Viena sobre Direitos do Comércio Internacional

### Dicas de prova
- Entenda as conexões pessoais, reais, delituais, voluntárias e normativas
- Identifique os outros elementos que compõem a estrutura da norma', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.8 (1)", "page_number": 8, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4 da Convenção de Viena sobre Direitos do Comércio Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:08:21.702051+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=8", "doc_key": "fc059b35cce01ef708b2c75f7cefc546"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9dd6ac5bb65999d36ee43121a803ce95ac6f5ff7322b17e42b74d4dd45bb9bdf'),
  ('cpiuris2025::2895ce577d1b702bdbd1548d2d2a8c60', 'doutrina', 'cp_iuris', 'Direitos Internacional — Noções Históricas do Direito Internacional', '## Noções Históricas do Direito Internacional

O direito internacional público surgiu na Idade Moderna, como disciplina jurídica subsidiária ao poder absolutista dos soberanos europeus e do Estado nacional moderno.

### Conceitos
- **Direito Internacional Público**: disciplina jurídica subsidiária ao poder absolutista dos soberanos europeus e do Estado nacional moderno
- **Sistema Vestfaliano**: sistema que gera efeitos até hoje e é o principal marco do Direito Internacional

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre o direito internacional público e o direito internacional privado
- Conheça os principais marcos do Direito Internacional, como a Paz de Westfália', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.9 (1)", "page_number": 9, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:09:04.438965+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=9", "doc_key": "2895ce577d1b702bdbd1548d2d2a8c60"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1a3c765a2fd22b5bf2bc96e9c80fd2257a65e06dbfc35064e2d81ddfb5984ac2'),
  ('cpiuris2025::0d356306a52472558b60b23e0a8cdbd8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Direito Processual Civil Internacional', '## Direito Processual Civil Internacional

Trata-se de uma seção que aborda as regras processuais aplicáveis aos procedimentos internacionais, incluindo a competência internacional e a cooperação jurídica.

### Conceitos
- **Competência internacional**: A capacidade do Estado de julgar um caso que envolve questões internacionais.
- **Cooperação jurídica internacional**: A colaboração entre os Estados para a resolução de disputas e a aplicação da lei internacional.
- **Prova dos fatos ocorridos no exterior**: A forma como se procede à prova de fatos que ocorreram fora do território nacional.
- **Carta rogatória**: Um documento que solicita a coleta de informações ou provas a um Estado estrangeiro.
- **Homologação de sentença estrangeira**: O processo pelo qual uma sentença proferida em um país estrangeiro é reconhecida e executada no território nacional.
- **Auxílio-direto**: A assistência direta que pode ser prestada por um Estado a outro em casos específicos.
- **Objeto da cooperação internacional**: O assunto ou questão que é objeto de cooperação entre os Estados.

### Referências legais
- Art. 87 do Código de Processo Civil
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo da cooperação jurídica internacional

### Dicas de prova
- Entenda a competência internacional e como ela se aplica às relações internacionais.
- Conheça as diferentes formas de cooperação jurídica internacional, incluindo o auxílio-direto e a homologação de sentença estrangeira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.8 (2)", "page_number": 8, "discipline": "Direitos Internacional", "legal_refs": ["Art. 87 do Código de Processo Civil", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo da cooperação jurídica internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T19:09:55.572105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=8", "doc_key": "0d356306a52472558b60b23e0a8cdbd8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8d538fbe724aa4418d630dd02594355e4ed49e0b7e36b4e1a96fb5a3265a5642'),
  ('cpiuris2025::914a6c8d7b7720a25af3f4c58aaf680c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Origem e conceituação do Direito Internacional', '## Origem e conceituação do Direito Internacional

O termo Direito Internacional foi cunhado por Jeremy Bentham em 1780, enquanto os termos ''Direito das Gentes'' e ''Direito entre as Nações'' foram utilizados anteriormente. A definição do que é Direito Internacional não é um consenso na doutrina.

### Conceitos
- **Direito Internacional**: Conceito jurídico que regula as relações entre os Estados
- **Direito das Gentes**: Antigo termo utilizado para descrever o Direito Internacional
- **Direito entre as Nações**: Outro antigo termo utilizado para descrever o Direito Internacional

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a origem do termo Direito Internacional e suas evoluções ao longo do tempo.
- Identifique os critérios utilizados para conceituar o Direito Internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.9 (2)", "page_number": 9, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:10:15.549085+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=9", "doc_key": "914a6c8d7b7720a25af3f4c58aaf680c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f6b014844a3545c5926af7f869d435d174de63e538e6b6103ed040ed0ea6b411'),
  ('cpiuris2025::b7efe47c6ec1e7a8622ee04893879d59', 'doutrina', 'cp_iuris', 'Direitos Internacional — Definição do Direito Internacional', '## Definição do Direito Internacional

A definição do Direito Internacional é objeto de debate entre os juristas, com quatro critérios principais: o sistema jurídico autônomo; a crítica à existência de outros entes além dos Estados; a definição baseada nos sujeitos do Direito Internacional; e a definição baseada no objeto ou na natureza fática da relação regulada.

### Conceitos
- **Sistema jurídico autônomo**: o sistema jurídico que regula as relações entre Estados Soberanos
- **Personalidade jurídica internacional**: a existência de outros entes além dos Estados que compõem a vida jurídica internacional
- **Sujeitos do Direito Internacional**: os entes que compõem a comunidade internacional e são sujeitos do Direito Internacional
- **Objeto ou natureza fática da relação regulada**: a definição baseada na natureza fática da relação regulada pelas normas do Direito Internacional

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a definição do Direito Internacional

### Dicas de prova
- Entenda os quatro critérios principais para definir o Direito Internacional e suas implicações.
- Destaque as limitações de cada critério e como eles se relacionam entre si.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.10 (1)", "page_number": 10, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a definição do Direito Internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T19:11:48.528379+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=10", "doc_key": "b7efe47c6ec1e7a8622ee04893879d59"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '083a76d18774d9e1bb22137e9c7fb5b3db48032a6d967486b945ad749b7e0eb2'),
  ('cpiuris2025::44b28e0cfdc32014dadfe97fd7146036', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conceituação do Direito Internacional', '## Conceituação do Direito Internacional

O Direito Internacional é definido como conjunto de normas que regem os sujeitos internacionais, buscando manter a paz e justiça internacional, além promover o desenvolvimento dos povos.

### Conceitos
- **Direito Internacional**: conjunto de normas que regem os sujeitos internacionais
- **Sociedade Internacional**: conjunto de Estados e outros atores internacionais
- **Processo**: fenômeno que antecede a norma internacional
- **Normas**: resultados de decisões passadas
- **Conceituação**: definição genérica ou sintética do Direito Internacional

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a conceituação do Direito Internacional como conjunto de normas e processo.
- Aprenda a distinguir entre conceituação genérica e sintética.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.11 (1)", "page_number": 11, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T19:12:10.153024+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=11", "doc_key": "44b28e0cfdc32014dadfe97fd7146036"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b266cdff7aa97433ec979e0767cddefa0b10088545a014cab9a34641abe68c73'),
  ('cpiuris2025::3d592408b43ace30bb5352d770b2489d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Critérios para definição do Direito Internacional', '## Critérios para definição do Direito Internacional

A definição do Direito Internacional é problemática, pois não há um critério único que a aborde. Os cinco critérios (formalidade, objetividade, fonte normativa, existência de uma comunidade internacional e finalidade) são insuficientes para uma definição completa da disciplina.

### Conceitos
- **Critérios para definição do Direito Internacional**: Métodos utilizados para abordar a noção de Direito Internacional
- **Fonte normativa**: A comunidade internacional que produz as normas do Direito Internacional
- **Comunidade internacional**: A existência de uma comunidade internacional é fundamental para a formação das normas do Direito Internacional

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a definição do Direito Internacional

### Dicas de prova
- Entenda os critérios para definição do Direito Internacional e suas limitações.
- Avalie a importância da fonte normativa na formação das normas do Direito Internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.10 (2)", "page_number": 10, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a definição do Direito Internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T19:12:22.150677+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=10", "doc_key": "3d592408b43ace30bb5352d770b2489d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '944afa8fb83ac1ec4b4a1972422779889473c4b4012dc0405ff63581d87398ad'),
  ('cpiuris2025::3aca9ffcbd019e800d2634b2809baa1d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sociedade Internacional e Relações Internacionais', '## Sociedade Internacional e Relações Internacionais

A sociedade internacional é aberta, não tendo um número determinado de atores que intervêm nas relações internacionais.

### Conceitos
- **Sociedade Internacional**: aberta e dinâmica
- **Relações Internacionais**: interação entre estados e outras entidades

### Referências legais
- Art. 23 da Carta das Nações Unidas

### Dicas de prova
- Entenda a abordagem de Sidney Guerra sobre a sociedade internacional.
- Reconheça que não há um número determinado de atores nas relações internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.12 (2)", "page_number": 12, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:13:32.804178+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=12", "doc_key": "3aca9ffcbd019e800d2634b2809baa1d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9241b11ac8119c71d41c87dc9010f309ba7ccf1b144c3370acfacee42c056997'),
  ('cpiuris2025::abc361cb68e5011a775a198a6b1627f9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Comunidade Internacional', '## Comunidade Internacional

A comunidade internacional é um termo utilizado para descrever a relação entre os países, caracterizada por vínculos espontâneos e subjetivos, envolvendo fatores como identidade, laços culturais e sociais.

### Conceitos
- **Comunidade Internacional**: relação entre os países, caracterizada por vínculos espontâneos e subjetivos
- **Vínculos Espontâneos**: fatores como identidade, laços culturais e sociais comuns dos membros da comunidade
- **Sinônimos**: sociedade internacional

### Referências legais
- Art. 53 da Convenção de Viena sobre Tratados

### Dicas de prova
- Entenda a diferença entre comunidade internacional e sociedade internacional
- Identifique os fatores que caracterizam uma comunidade internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.11 (2)", "page_number": 11, "discipline": "Direitos Internacional", "legal_refs": ["Art. 53 da Convenção de Viena sobre Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:13:44.241932+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=11", "doc_key": "abc361cb68e5011a775a198a6b1627f9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4fd1751bfe55800a24b9f258a06b14497368ef485361ffed0cfc391d1eb4b6cd'),
  ('cpiuris2025::4fdbea821c7819da08f01c577f03aab9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Diferenciação entre Comunidade e Sociedade', '## Diferenciação entre Comunidade e Sociedade

Comunidade: unidade harmônica entre membros; Sociedade: associação de membros com objetivos comuns, baseada na vontade e fins compartilhados.

### Conceitos
- **Comunidade**: Unidade harmônica entre membros
- **Sociedade**: Associação de membros com objetivos comuns, baseada na vontade e fins compartilhados

### Referências legais
- Art. X da Lei Y
- ...

### Jurisprudência
- RE 123456
- ...

