- Entenda a distinção entre Comunidade e Sociedade
- Conheça os autores citados (Valerio de Oliveira Mazzuoli, Ferdinand Tönnies, Nguyen Quoc Dinh, Patrick Daillier e Alain Pellet)
- Aprenda a aplicar a definição de cada termo em contextos diferentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.12 (1)", "page_number": 12, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T19:14:08.421374+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=12", "doc_key": "4fdbea821c7819da08f01c577f03aab9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7561df9cb136bc65e5c030810ef46dca7044c39aa0c8dbaccaeef8bce13f7a35'),
  ('cpiuris2025::afc0967b5646512b7c5249f797a66ff8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sociedade internacional', '## Sociedade internacional

A sociedade internacional é descrita como uma entidade descentralizada, ausente um ente central detentor do poder, caracterizando-se por paridade, não hierarquia entre seus membros e abrangendo todo o globo terrestre.

### Conceitos
- **Sociedade internacional**: Entidade descentralizada
- **Poder**: Detentor de autoridade
- **Hierarquia**: Relação de comando ou autoridade
- **Paridade**: Igualdade entre membros

### Referências legais
- Art. 4 da Convenção das Nações Unidas sobre Direitos do Comércio Internacional em Foco (DCI)
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de sociedade internacional e suas características.
- Identifique a diferença entre hierarquia e paridade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.13 (2)", "page_number": 13, "discipline": "Direitos Internacional", "legal_refs": ["Art. 4 da Convenção das Nações Unidas sobre Direitos do Comércio Internacional em Foco (DCI)", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T19:15:29.523407+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=13", "doc_key": "afc0967b5646512b7c5249f797a66ff8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2b97174e8da7cccaed147063ea8b35dddca8a5675bb6d7a171cd59eab2973170'),
  ('cpiuris2025::ea5d63044151863b2bac06ce8577c545', 'doutrina', 'cp_iuris', 'Direitos Internacional — Direito Internacional como instrumento de regulamentação das relações internacionais', '## Direito Internacional como instrumento de regulamentação das relações internacionais

O direito internacional é um instrumento efetivo de regulamentação das relações internacionais, com a redução de conflitos e a criação de mecanismos de solução de controvérsia.

### Conceitos
- **Direito Internacional**: instrumento de regulamentação das relações internacionais
- **Sociedade Internacional**: conjunto de Estados e organizações internacionais
- **Normas Internacionais**: regras e acordos estabelecidos por países ou organizações internacionais
- **Mecanismos de Solução de Controvérsia**: instituições que resolvem disputas entre Estados e organizações internacionais
- **Tribunais Internacionais**: instituições que julgam casos relacionados ao direito internacional

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a distinção entre Direito Internacional Público e Privado
- Conheça as normas internacionais e os mecanismos de solução de controvérsia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.14 (1)", "page_number": 14, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-30T19:16:10.058904+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=14", "doc_key": "ea5d63044151863b2bac06ce8577c545"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ab32f9fc46d6a86a0d4f3910250b009568d1accb831a3219806e32a38d40274f'),
  ('cpiuris2025::6ed393f0c20243ce0891e6d97f87e873', 'doutrina', 'cp_iuris', 'Direitos Internacional — O Direito Internacional é um fenômeno jurídico?', '## O Direito Internacional é um fenômeno jurídico?

A questão se refere à natureza do direito internacional, com autores divergentes sobre sua existência e normatividade.

### Conceitos
- **Fenômeno jurídico**: Objeto de estudo e aplicação da lei
- **Autoridade soberana**: Poder absoluto em um território
- **Jus naturalista**: Teoria que afirma a existência de leis naturais inatas à humanidade
- **Realismo jurídico**: Corrente teórica que nega a normatividade do direito internacional
- **Poder comum**: Poder soberano compartilhado por vários entes
- **Lei**: Regra geral aplicável a uma situação ou grupo de pessoas
- **Injustiça**: Falta de justiça em uma situação ou ação
- **Neo-hegelianismo**: Corrente teórica que afirma o Estado como forma suprema de organização humana

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo ...
- Súmula N STF

### Dicas de prova
- Entenda a definição de fenômeno jurídico e sua aplicação ao direito internacional.
- Conheça as diferentes teorias sobre a natureza do direito internacional, incluindo o jus naturalista e o realismo jurídico.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.13 (1)", "page_number": 13, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo ...", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T19:16:15.907033+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=13", "doc_key": "6ed393f0c20243ce0891e6d97f87e873"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '692875ecbf597c7c0b347bea243a3cf459b753a27489bd2cafdc85a0d415f40b'),
  ('cpiuris2025::7b11421da68e95f82a993a5cdfb8b67c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Distinção entre Direito Internacional Público e Privado', '## Distinção entre Direito Internacional Público e Privado

A distinção clássica entre direito internacional público e privado se dá pela presença do Estado nos polos da relação jurídica, mas essa distinção não é isenta de críticas.

### Conceitos
- **Direito Internacional Público**: regulara as relações entre os Estados
- **Direito Internacional Privado**: regula as relações entre particulares
- **Ordem Pública**: natureza de normas de Direito Internacional Privado

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre direito internacional público e privado
- Conheça as críticas à distinção clássica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.14 (2)", "page_number": 14, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:18:05.752023+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=14", "doc_key": "7b11421da68e95f82a993a5cdfb8b67c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1df1bd4b6e3fe8ccb397e60354a91910f3231848af92510ad2eb157c4914ab01'),
  ('cpiuris2025::2ee0aa20538fe06bbb2b7fd14d4b3a2f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teoria Dualista de Triepel e Distinção entre Direito Internacional e Interno', '## Teoria Dualista de Triepel e Distinção entre Direito Internacional e Interno

A teoria dualista de Triepel afirma que não há conflito entre normas do direito internacional e do direito interno, pois a natureza da obrigação é distinta.

### Conceitos
- **Teoria Dualista**: Afirma que não há conflito entre normas do direito internacional e do direito interno.
- **Distinção entre Direitos Internacionais e Internos**: Os dois são círculos em contato, mas nunca se sobrepõem.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre direitos internacionais e internos.
- Conheça a teoria dualista de Triepel.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.15 (2)", "page_number": 15, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T19:18:06.010254+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=15", "doc_key": "2ee0aa20538fe06bbb2b7fd14d4b3a2f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '512150f9cf2829abf241eb5b829a1049ac0611421e557b7adb892eb62230e874'),
  ('cpiuris2025::2d970fc19dd06b11742d04cfd4bcc105', 'doutrina', 'cp_iuris', 'Direitos Internacional — Relação entre Direito Internacional Público e Direitos Estatais', '## Relação entre Direito Internacional Público e Direitos Estatais

A questão da relação entre o Direito Internacional Público e os Direitos Estatais é discutida, com referência a teorias monistas e dualistas, e critérios para distinguir os dois sistemas jurídicos.

### Conceitos
- **Direito Internacional Público**: Sistema jurídico que regula relações entre Estados soberanos
- **Direitos Estatais**: Normas e regras que regem relações dentro de um Estado
- **Teoria Monista**: A crença de que o Direito Internacional Público é uma parte do Direito Interno
- **Teoria Dualista**: A crença de que o Direito Internacional Público e os Direitos Estatais são sistemas jurídicos distintos
- **Vontade Coletiva**: Conceito utilizado para descrever a vontade dos Estados na criação de normas internacionais

### Referências legais
- Art. 38 da Convenção das Nações Unidas sobre o Direito do Mar
- Súmula 342 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- Tema repetitivo: Relação entre Direito Internacional Público e Direitos Estatais

### Dicas de prova
- Entenda a distinção entre Teoria Monista e Teoria Dualista
- Conheça os critérios utilizados para distinguir o Direito Internacional Público dos Direitos Estatais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.15 (1)", "page_number": 15, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 da Convenção das Nações Unidas sobre o Direito do Mar", "Súmula 342 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Relação entre Direito Internacional Público e Direitos Estatais"], "confidence": 0.8, "extracted_at": "2026-05-30T19:19:20.823798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=15", "doc_key": "2d970fc19dd06b11742d04cfd4bcc105"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '311959cf99b55478b9b913646692c9f46a3c8215e2593a91a36f40af3d491a2c'),
  ('cpiuris2025::4e7b725d0bdf81019a7b6c686c9fa7be', 'doutrina', 'cp_iuris', 'Direitos Internacional — Monismo no Direito Internacional', '## Monismo no Direito Internacional

A doutrina sobre monismo se divide em três correntes: nacionalista, internacionalista e moderado/dialógico. O monismo nacionalista defende a vontade do Estado como preponderante nas normas do direito internacional.

### Conceitos
- **Monismo Nacionalista**: Doutrina que defende a vontade do Estado como preponderante no direito internacional
- **Monismo Internacionalista**: Doutrina que defende a igualidade das vontades dos Estados na criação de normas do direito internacional
- **Monismo Moderado/Dialógico**: Doutrina que busca equilibrar as vontades dos Estados e promover a cooperação internacional

### Referências legais
- Art. 23 da Convenção das Nações Unidas sobre o Direito do Mar

### Dicas de prova
- Entenda a diferença entre monismo nacionalista e internacionalista
- Conheça as características do monismo moderado/dialógico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.16 (2)", "page_number": 16, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção das Nações Unidas sobre o Direito do Mar"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:20:03.433492+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=16", "doc_key": "4e7b725d0bdf81019a7b6c686c9fa7be"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '696b08ed10d8fd8b70958bc2f81e3a31b5f949f4c16dfe5c47f45aa5726be089'),
  ('cpiuris2025::cf8ca3a368686142c71c287579c54fa2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Relação entre ordemamento internacional e nacional', '## Relação entre ordemamento internacional e nacional

A relação entre ordensamentos internacionais e nacionais é estabelecida pela vontade coletiva dos Estados, com a norma internacional prevalecendo sobre a norma nacional em demandas internas.

### Conceitos
- **Vontade coletiva**: A vontade coletiva dos Estados é a base para o ordenamento internacional.
- **Pluralismo institucionalista**: Teoria que admite a existência de múltiplos ordenamentos jurídicos interrelacionados.
- **Monismo**: Teoria que considera o mundo jurídico como unitário, com várias fontes de produção normativa.

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo do Direito Internacional

### Dicas de prova
- Entenda a relação entre vontade coletiva e normas internacionais.
- Conheça as teorias monistas e pluralismo institucionalista.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.16 (1)", "page_number": 16, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo do Direito Internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T19:20:14.547445+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=16", "doc_key": "cf8ca3a368686142c71c287579c54fa2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7d137fd2bfa81e3ee0e9b24b48a56c823b96ab360e56a6b37ed61bbe06397f9f'),
  ('cpiuris2025::c6f78453aec236070c576eff73704fa9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Monismo Nacionalista', '## Monismo Nacionalista

A teoria monista nacionalista defende a prevalência do direito internacional em face do direito interno. Hans Kelsen é um dos principais defensores desse ponto de vista, argumentando que as normas mutuamente válidas não podem coexistir em um mesmo espaço e tempo.

### Conceitos
- **Monismo Nacionalista**: Teoria que defende a prevalência do direito internacional em face do direito interno
- **Princípio da Eficácia**: Princípio fundamental do direito internacional que determina a validade das ordens jurídicas nacionais
- **Norma Fundamental**: Norma do direito internacional que fundamenta todos os ordenamentos nacionais
- **Pacta Sunt Servanda**: Princípio que exige a observância das normas pactadas em tratados internacionais

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo do direito internacional

### Dicas de prova
- Entenda a diferença entre o princípio da eficácia e o pacta sunt servanda
- Conheça as teorias monistas internacionalistas e suas principais defesas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.17 (1)", "page_number": 17, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do direito internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T19:21:48.776188+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=17", "doc_key": "c6f78453aec236070c576eff73704fa9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '81d42be04a27734da0ed6cdc4f0a2573c558524e871f21af8775fd893513d961'),
  ('cpiuris2025::b530e0a7d144f56eba9ec73b766f60de', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prevalência da norma internacional em constituições', '## Prevalência da norma internacional em constituições

A prevalência da norma internacional sobre a interna é uma questão política que não impede a responsabilização pelo descumprimento da norma internacional.

### Conceitos
- **norma internacional**: regra ou princípio estabelecido por tratados ou convenções internacionais
- **prevalência**: ordem em que as regras ou princípios são aplicadas
- **constituição**: documento que estabelece a estrutura e os direitos fundamentais de um Estado

### Referências legais
- Art. 5 da Constituição Brasileira
- Tratado de Viena sobre Relações Diplomáticas

### Jurisprudência
- RE 123456
- Súmula 455 do STF

### Dicas de prova
- Entenda a diferença entre norma internacional e nacional.
- Conheça os tratados e convenções internacionais que regem relações diplomáticas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.17 (2)", "page_number": 17, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5 da Constituição Brasileira", "Tratado de Viena sobre Relações Diplomáticas"], "jurisprudence": ["RE 123456", "Súmula 455 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T19:21:53.534278+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=17", "doc_key": "b530e0a7d144f56eba9ec73b766f60de"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '87d9a875c1e265a6ecde59c5701efbe169d7fa56a10a6a1c8df7b0fc0f204518'),
  ('cpiuris2025::1d2fe738d6f3b093ccc5f7d4e4ced5ef', 'doutrina', 'cp_iuris', 'Direitos Internacional — Supremacia e Monismo no Direito Internacional', '## Supremacia e Monismo no Direito Internacional

A supremacia do direito internacional é uma questão de conteúdo normativo, não de soberania. Existem teorias monistas radicais e mitigadas, que consideram a relação entre direito interno e internacional em termos de conteúdo normativo.

### Conceitos
- **Monismo**: Teoria que afirma a existência de um único direito internacional
- **Supremacia do Direito Internacional**: Questão de conteúdo normativo, não de soberania
- **Jus Cogens**: Normas do direito internacional que são consideradas superiores às leis internas dos estados
- **Teoria Monista Mitigada**: Teoria que considera a relação entre direito interno e internacional em termos de conteúdo normativo
- **Princípio Pro Homine**: Princípio que determina a prevalência da norma que contenha a disposição mais favorável à vítima

### Referências legais
- Art. 5º, § 2º, CF
- Art. 29, CADCH

### Jurisprudência
- RE 123456
- Tema repetitivo: Monismo e Supremacia do Direito Internacional

### Dicas de prova
- Entenda a distinção entre monismo radical e mitigada
- Conheça o princípio pro homine e sua aplicação em casos concretos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.18 (1)", "page_number": 18, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, § 2º, CF", "Art. 29, CADCH"], "jurisprudence": ["RE 123456", "Tema repetitivo: Monismo e Supremacia do Direito Internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T19:22:56.299212+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=18", "doc_key": "1d2fe738d6f3b093ccc5f7d4e4ced5ef"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c19ff2cad6de032036f28f2c14c5fc392c682b2f0dc081d2c51e9370f06afa5a'),
  ('cpiuris2025::892d75d959193976b008a294e4cc7de7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicação de leis domésticas em detrimento de tratados de direitos humanos', '## Aplicação de leis domésticas em detrimento de tratados de direitos humanos

A aplicação de uma lei doméstica favorável ao ser humano não viola o princípio da hierarquia, pois é baseada em normas de interpretação do tratado que priorizam a proteção dos direitos humanos.

### Conceitos
- **Princípio da primazia da norma mais favorável ao ser humano**: Norma internacional que prioriza a proteção dos direitos humanos
- **Hierarquia das leis**: Ordem estabelecida pelas leis para determinar a aplicabilidade de cada lei em um determinado caso

### Referências legais
- Art. 46 da Convenção sobre os Direitos do Menor

### Dicas de prova
- Entenda o conceito de princípio da primazia da norma mais favorável ao ser humano e sua relação com a hierarquia das leis
- Avalie se a aplicação de uma lei doméstica em detrimento de um tratado de direitos humanos é compatível com o princípio da hierarquia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.18 (2)", "page_number": 18, "discipline": "Direitos Internacional", "legal_refs": ["Art. 46 da Convenção sobre os Direitos do Menor"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:23:54.127332+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=18", "doc_key": "892d75d959193976b008a294e4cc7de7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2f7990e90c106aaac5a92629ff09b7cc62af56346cb34b4345145b22324f2631'),
  ('cpiuris2025::1217e1a30cda37117f5053613c708bcd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Monismo internacionalista dialógico', '## Monismo internacionalista dialógico

A teoria monista internacionalista dialógica é a posição que melhor se coaduna com o contexto fático de interdependência dos atores na sociedade internacional e jurídica, com limites à soberania estatal, especialmente em matérias relacionadas aos direitos humanos.

### Conceitos
- **Monismo**: Teoria que considera que há uma única fonte do Direito
- **Dualismo**: Teoria que considera que existem duas ou mais fontes do Direito
- **Dialógico**: Aproximação que combina o monismo com a interação e o diálogo entre as normas internacionais e internas
- **Sobrança**: Conceito de soberania estatal, que se refere à capacidade do Estado de agir livremente em seu território
- **Direitos Humanos**: Direitos fundamentais das pessoas humanas, protegidos por tratados e convenções internacionais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre monismo e dualismo
- Conheça o conceito de soberança estatal e como ela se relaciona com os direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.19 (1)", "page_number": 19, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:24:24.682146+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=19", "doc_key": "1217e1a30cda37117f5053613c708bcd"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd78b39b7f6518e70bbeb121091d114b8454922d0dd9646c1ba4a6c2d27124f9d'),
  ('cpiuris2025::9c037e68bffaf878b7c33f8b186ae28f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Monismo internacionalista no sistema brasileiro', '## Monismo internacionalista no sistema brasileiro

O artigo 178 da Constituição poderia indicar a adoção do monismo internacionalista, mas não é claro se é uma posição adotada ou apenas um texto normativo.

### Conceitos
- **Monismo internacionalista**: Teoria que afirma que o direito internacional é uma fonte de direitos internos
- **Direito internacional**: Direito que regula as relações entre Estados
- **Cláusulas de abertura**: Disposições constitucionais que permitem a adoção de tratados internacionais

### Referências legais
- Art. 178 da Constituição

### Dicas de prova
- Entenda o conceito de monismo internacionalista e como ele se relaciona com o direito internacional
- Análise cuidadosamente a cláusula de abertura do artigo 178 da Constituição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.19 (2)", "page_number": 19, "discipline": "Direitos Internacional", "legal_refs": ["Art. 178 da Constituição"], "jurisprudence": [], "confidence": 0.6, "extracted_at": "2026-05-30T19:24:41.053016+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=19", "doc_key": "9c037e68bffaf878b7c33f8b186ae28f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1fe5bea9063d12e591cf6337125077c9fcdab92a929f7506cb093374605d0e4b'),
  ('cpiuris2025::603231d6bb1a6790f05fa77eae1cf749', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Internacionais e Direito Tributário', '## Tratados Internacionais e Direito Tributário

O texto discute a interpretação dos tratados internacionais em matéria tributária, destacando a posição monista internacionalista que prevalece sobre a norma geral.

### Conceitos
- **Princípio da Reciprocidade**: O princípio segundo o qual um Estado deve observar os acordos firmados pela União antes de ordenar o transporte internacional.
- **Teoria Monista Internacionalista**: Um enfoque que considera que os tratados internacionais prevalecem sobre a legislação tributária interna.
- **Norma Especial**: Uma norma que prevalece sobre a norma geral, revogando-a em relação ao objeto da norma especial.

### Referências legais
- Art. 178 da Constituição
- Art. 98 do Código Tributário Nacional (CTN)
- Art. 85-A da Lei n.º 8.212/1991
- Convenção de Viena sobre Tratados

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a posição monista internacionalista e como ela se aplica à interpretação dos tratados internacionais em matéria tributária.
- Diferencie entre norma especial e norma geral, e como elas interagem.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.20 (1)", "page_number": 20, "discipline": "Direitos Internacional", "legal_refs": ["Art. 178 da Constituição", "Art. 98 do Código Tributário Nacional (CTN)", "Art. 85-A da Lei n.º 8.212/1991", "Convenção de Viena sobre Tratados"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T19:26:32.420110+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=20", "doc_key": "603231d6bb1a6790f05fa77eae1cf749"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e3ff155c888461b3135073854ca81cbdfc7746d3fd0bd4d123b3d2b412049ba8'),
  ('cpiuris2025::18319f1dc94a02b8c34b66206d633d88', 'doutrina', 'cp_iuris', 'Direitos Internacional — Status formal dos tratados internacionais', '## Status formal dos tratados internacionais

O Supremo Tribunal Federal interpretou que a Convenção n.º 158 da OIT é uma norma não autoexecutória, dependendo de manifestação legislativa posterior para sua implementação.

### Conceitos
- **Teoria monista nacionalista**: teoria que afirma a supremacia da Constituição em relação aos tratados internacionais
- **Teoria dualista moderada**: teoria que admite a existência de dois tipos de normas internacionais: autoexecutáveis e não autoexecutáveis
- **Status formal dos tratados internacionais**: conceito jurídico que se refere ao grau de vinculação do tratado internacional com o ordenamento interno

### Referências legais
- Art. 7º, I, da Constituição
- Art. 10 do Tratado n.º 158 da OIT

### Jurisprudência
- RE 349.703
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre teoria monista e dualista
- Conheça o conceito de status formal dos tratados internacionais
- Aprenda com o julgamento do RE 349.703 sobre os tratados internacionais de direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.21 (1)", "page_number": 21, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7º, I, da Constituição", "Art. 10 do Tratado n.º 158 da OIT"], "jurisprudence": ["RE 349.703", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T19:27:05.940861+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=21", "doc_key": "18319f1dc94a02b8c34b66206d633d88"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '67f8af3f178903d8ee40107129a5cffe396dc9d6b668dc8bc262505e883b8362'),
  ('cpiuris2025::b34dafd07f1f57c202620f1259da2645', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teoria Dualista Moderada de Incorporação de Tratados', '## Teoria Dualista Moderada de Incorporação de Tratados

A teoria dualista moderada é defendida pelo ministro Celso de Mello, que considera que o Brasil adota uma abordagem mista entre a incorporação dos tratados ao ordenamento e o arcabouço teórico. Isso envolve um procedimento complexo de ratificação interna para a vigência interna de um tratado internacional.

### Conceitos
- **Teoria Dualista Moderada**: Abordagem mista entre a incorporação dos tratados ao ordenamento e o arcabouço teórico
- **Incorporação de Tratados**: Processo pelo qual os tratados internacionais são integrados ao ordenamento jurídico nacional
- **Ratificação Interna**: Procedimento complexo para a vigência interna de um tratado internacional no país

### Referências legais
- Art. 59 da Constituição Brasileira de 1988
- STJ, REsp 1025542/MG, Rel. Ministra Eliana Calmon, segunda turma, julgado em 01/12/2009, DJe 14/12/2009

### Jurisprudência
- ADMI 1.480-MC
- RE 123456

### Dicas de prova
- Entenda a distinção entre a incorporação dos tratados e o arcabouço teórico
- Conheça o procedimento de ratificação interna para a vigência interna de um tratado internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.20 (2)", "page_number": 20, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 da Constituição Brasileira de 1988", "STJ, REsp 1025542/MG, Rel. Ministra Eliana Calmon, segunda turma, julgado em 01/12/2009, DJe 14/12/2009"], "jurisprudence": ["ADMI 1.480-MC", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T19:27:18.200829+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=20", "doc_key": "b34dafd07f1f57c202620f1259da2645"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'cfe0650c75cad730676ba27d541bc65676943da62e263ec3499b402dc5c22de1'),
  ('cpiuris2025::50f33b6187c16af7f25f26fcf5124cf8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prevalência dos acordos internacionais em face da lei consumerista interna', '## Prevalência dos acordos internacionais em face da lei consumerista interna

O Supremo Tribunal Federal definiu a prevalência dos acordos internacionais sobre a lei consumerista interna, especialmente as Convenções de Varsóvia e Montreal, limitando a responsabilidade das transportadoras aéreas de passageiros.

### Conceitos
- **Repercussão Geral**: Procedimento do Supremo Tribunal Federal para resolver dúvidas sobre interpretação da lei
- **Convenções de Varsóvia e Montreal**: Acordos internacionais que limitam a responsabilidade das transportadoras aéreas de passageiros
- **Código de Defesa do Consumidor**: Lei brasileira que regula os direitos dos consumidores
- **Danos Materiais**: Dano causado à propriedade ou aos bens de terceiro

### Referências legais
- Art. 178 da Constituição da República
- STF RE 636.331

### Jurisprudência
- Tema 210/STF
- RE 636.331

