  ('cpiuris2025::9d188c64083fcad65092d2cb98e81f92', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teorias do Direito Internacional', '## Teorias do Direito Internacional

A questão discute as teorias do direito internacional, destacando a distinção entre monismo moderado e dualismo moderado. O texto destaca a adoção do monismo moderado pelo Brasil e a importância de entender a forma como as teorias são aplicadas em questões objetivas.

### Conceitos
- **Monismo Moderado**: Teoria que considera que o direito internacional é uma fonte do direito interno brasileiro
- **Dualismo Moderado**: Teoria que considera que o direito internacional e o direito interno brasileiro são fontes separadas de direitos

### Referências legais
- Art. 109 da Constituição Federal
- Súmula 466 do STF

### Jurisprudência
- RE 1394401 RG
- ADI 1.480/MC

### Dicas de prova
- Entenda a distinção entre monismo moderado e dualismo moderado
- Aprenda a aplicar as teorias em questões objetivas
- Perguntas sobre proteção dos direitos humanos podem levar à adoção do monismo internacionalista mitigado/moderado/dialógico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.22 (1)", "page_number": 22, "discipline": "Direitos Internacional", "legal_refs": ["Art. 109 da Constituição Federal", "Súmula 466 do STF"], "jurisprudence": ["RE 1394401 RG", "ADI 1.480/MC"], "confidence": 0.8, "extracted_at": "2026-05-30T19:28:29.574275+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=22", "doc_key": "9d188c64083fcad65092d2cb98e81f92"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '197fd258d5aecc23e0a481d813ddd1eb36036cf66c5624921229dbc3ae123488'),
  ('cpiuris2025::cf1429c3747f1b6c243c38c99b945ef0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Dualismo e Monismo no Direito Internacional', '## Dualismo e Monismo no Direito Internacional

Resumo do texto sobre dualismo e monismo na teoria jurídica internacional.

### Conceitos
- **Dualismo**: Teoria que afirma a existência de dois sistemas jurídicos: interno e internacional
- **Monismo**: Teoria que afirma a existência de um sistema jurídico único, que abrange tanto o direito interno quanto o internacional
- **Efeitos da Ratificação**: Geração de efeitos no âmbito nacional de acordo com a corrente monista
- **Unidade do Ordenamento Jurídico**: Conceito que afirma a existência de uma única ordem jurídica que abrange tanto o direito interno quanto o internacional

### Referências legais
- Art. 59 da Constituição Federal

### Jurisprudência
- Súmula 455 do STF

### Dicas de prova
- Entenda a distinção entre dualismo e monismo na teoria jurídica internacional.
- Conheça as implicações da ratificação de tratados internacionais no âmbito nacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.22 (2)", "page_number": 22, "discipline": "Direitos Internacional", "legal_refs": ["Art. 59 da Constituição Federal"], "jurisprudence": ["Súmula 455 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T19:30:34.180310+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=22", "doc_key": "cf1429c3747f1b6c243c38c99b945ef0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b2c3e93c3a1c6d42224ff18ceea1e585452e60734c1fd45c3c4891d14cb25109'),
  ('cpiuris2025::3d3f4b633766293f0ad40b38f1422352', 'doutrina', 'cp_iuris', 'Direitos Internacional — Incorporação de tratados de direitos humanos à ordem jurídica interna', '## Incorporação de tratados de direitos humanos à ordem jurídica interna

Discute-se a aplicabilidade do direito internacional em relação à incorporação de tratados de direitos humanos na ordem jurídica interna, bem como a relação entre os ordenamentos jurídicos internos e internacionais.

### Conceitos
- **Dualismo**: Filosofia jurídica que considera o direito internacional como uma fonte de direitos humanos
- **Incorporação**: Processo pelo qual os tratados de direitos humanos são integrados à ordem jurídica interna
- **Ordem Jurídica Internacional**: Sistema de leis que regula as relações entre os Estados
- **Ordem Jurídica Interna**: Sistema de leis que regula a vida e o direito dentro de um Estado

### Referências legais
- Art. 5º da Constituição Brasileira
- Tratado Americano de Direitos Humanos

### Dicas de prova
- Entenda a distinção entre dualismo e monismo em relação à incorporação de tratados de direitos humanos
- Conheça as diferentes abordagens para a aplicabilidade do direito internacional na ordem jurídica interna', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.23 (2)", "page_number": 23, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º da Constituição Brasileira", "Tratado Americano de Direitos Humanos"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:30:56.149740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=23", "doc_key": "3d3f4b633766293f0ad40b38f1422352"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'bd842d0a18dc7b1d9fa668ad6f8b5adf3d18ba40c7e64e7641fac86e9e880252'),
  ('cpiuris2025::db6a434c22f5aa9c844bf202a39cd360', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conflitos Normativos entre Normas Internacionais e Nacionais', '## Conflitos Normativos entre Normas Internacionais e Nacionais

A análise de conflitos normativos envolve a aplicação de critérios para justificar a solução, considerando a supremacia da Constituição Federal e o princípio pro homine.

### Conceitos
- **Critério pré-estipulado**: não há critério pré-estipulado para análise de conflitos
- **Supremacia da Constituição Federal**: regra prevalece sobre norma prescrita no tratado internacional
- **Princípio pro homine**: prevalece a norma mais benéfica ao indivíduo
- **Lei posterior revoga lei anterior**: leis posteriores revogam leis anteriores com incompatibilidade
- **Hierarquia supraconstitucional**: prevalece a norma do tratado internacional de proteção de direitos humanos

### Referências legais
- Art. 5 da Constituição Federal
- Tratados Internacionais de Proteção de Direitos Humanos

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Análise crítica dos critérios para justificar a solução de conflitos normativos
- Consideração da supremacia da Constituição Federal e do princípio pro homine', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.23 (1)", "page_number": 23, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5 da Constituição Federal", "Tratados Internacionais de Proteção de Direitos Humanos"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T19:31:10.951552+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=23", "doc_key": "db6a434c22f5aa9c844bf202a39cd360"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a84d6ff6a93db63487d009ad8aa82c9b93c8ebd98736de7798880efb68e36fb6'),
  ('cpiuris2025::9cfdddaefe48b3c3d1b44db51d40ed41', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teorias Voluntaristas', '## Teorias Voluntaristas

As teorias voluntaristas defendem que as regras do direito internacional dependem da vontade dos Estados soberanos.

### Conceitos
- **Vontade humana**: afirmação fundamental de que as normas do Direito são produto da vontade humana
- **Positivismo**: definiem o Direito através dos institutos da ‘estadualidade e coercibilidade’
- **Soberania estatal**: princípio que os Estados são independentes e não dependem de uma vontade superior

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre voluntarismo jurídico e objetivismo
- Conheça as ideias de Hegel sobre o direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.24 (1)", "page_number": 24, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T19:32:31.957656+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=24", "doc_key": "9cfdddaefe48b3c3d1b44db51d40ed41"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd4bc2995e074d2a624fb16be9163a4c8197df1e3ff3c04b87e75fa31e1bdda2b'),
  ('cpiuris2025::b694f78c286f24dcfb7c1428374811c7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teoria da Autolimitação Estatal', '## Teoria da Autolimitação Estatal

O direito internacional se baseia na vontade dos Estados, que criam normas e sanções para seu descumprimento.

### Conceitos
- **Vontade dos Estados**: base do direito internacional
- **Autolimitação Estatal**: teoria que afirma que o Estado se obriga a si mesmo
- **Poder Absoluto**: argumento metafísico utilizado para justificar a autolimitação estatal

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- Caso (navio) S.S. Lótus, Corte Permanente de Justiça Internacional, 1927

### Dicas de prova
- Entenda a vontade dos Estados como base do direito internacional
- Identifique a teoria da autolimitação estatal e seu argumento metafísico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.24 (2)", "page_number": 24, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["Caso (navio) S.S. Lótus, Corte Permanente de Justiça Internacional, 1927"], "confidence": 0.8, "extracted_at": "2026-05-30T19:32:44.472222+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=24", "doc_key": "b694f78c286f24dcfb7c1428374811c7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd65755b087ae09de6dea7432b039995baa5400af6acc0d1d2932b6b27bcd264b'),
  ('cpiuris2025::dab136b431cf9af180ad8df6b35b99fe', 'doutrina', 'cp_iuris', 'Direitos Internacional — Pacta Sunt Servanda e Fundamentos do Direito Internacional', '## Pacta Sunt Servanda e Fundamentos do Direito Internacional

A norma pacta sunt servanda é a base do ordenamento internacional, fundamentada na vontade coletiva dos Estados. A teoria voluntarista busca justificar as normas internacionais nos ordenamentos nacionais ou no consentimento das nações.

### Conceitos
- **Pacta Sunt Servanda**: Princípio fundamental do direito internacional que exige respeito aos pactos concluídos pelos Estados
- **Vontade Coletiva**: Conceito que fundamenta o direito internacional, buscando justificar as normas internacionais na vontade coletiva dos Estados
- **Teoria Voluntarista**: Enfoque que busca justificar as normas internacionais nos ordenamentos nacionais ou no consentimento das nações

### Referências legais
- CPJI, Caso do SS. Lotus, Series A. nº 10, 1927
- Art. 62 da Convenção de Viena sobre Direitos do Comércio Internacional

### Dicas de prova
- Entenda a importância da pacta sunt servanda no direito internacional e como ela se relaciona com a vontade coletiva dos Estados.
- Análise crítica das teorias voluntaristas e suas justificativas para as normas internacionais
- Conheça o conceito de soberania estatal e sua relação com a legitimidade no direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.25 (1)", "page_number": 25, "discipline": "Direitos Internacional", "legal_refs": ["CPJI, Caso do SS. Lotus, Series A. nº 10, 1927", "Art. 62 da Convenção de Viena sobre Direitos do Comércio Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:33:53.797111+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=25", "doc_key": "dab136b431cf9af180ad8df6b35b99fe"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '14ac2e4bb143f33f3fbddc5a60dd5db397652aa76d06d39d17f682ad98003d48'),
  ('cpiuris2025::1c5492f04350ec11b5c7b80ae5e4d9b9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípio da Proeminência', '## Princípio da Proeminência

O princípio da proeminência é um princípio geral que estabelece que os Estados devem respeitar práticas comuns e aceitas pela maioria dos Estados, a menos que uma prática mais amplamente aceita melhore a legitimidade do Estado que não a aceita.

### Conceitos
- **Princípio da Proeminência**: princípio geral que estabelece a importância das práticas comuns e aceitas pela maioria dos Estados
- **Vontade Comum**: teoria baseada na ideia de que os Estados devem respeitar as práticas comuns e aceitas pela maioria dos Estados
- **Consentimento das Nações**: teoria que afirma que os Estados devem respeitar as práticas comuns e aceitas pela maioria dos Estados, a menos que uma prática mais amplamente aceita melhore a legitimidade do Estado

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Dicas de prova
- Entenda o conceito de proeminência e como ele se relaciona com a vontade comum e consentimento das nações.
- Análise cuidadosa do texto para identificar as fontes jurídicas que apoiam o princípio da proeminência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.25 (2)", "page_number": 25, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:35:04.224556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=25", "doc_key": "1c5492f04350ec11b5c7b80ae5e4d9b9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '52ca5145d38caffc786a958e9342097bb24381f5aa0a7575415f3ee2fbd6d88b'),
  ('cpiuris2025::ab533146d07b3477e2bf24af73d03dbb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teorias não voluntaristas do Direito Internacional', '## Teorias não voluntaristas do Direito Internacional

As teorias não voluntaristas buscam assentar o fundamento do Direito Internacional em princípios ou normas superiores aos ordenamentos nacionais, independentes da vontade dos Estados.

### Conceitos
- **teses normativistas**: Reconduzem o sistema de Direito Internacional à uma norma fundamental pressuposta
- **pacta sunt servanda**: Norma que obriga os Estados a cumprir as suas obrigações internacionais
- **teses solidaristas**: Fundamentam o direito internacional na solidariedade entre indivíduos e fatores sociológicos
- **consuetudo est servanda**: Norma que obriga os Estados a cumprir as suas obrigações internacionais de acordo com a prática constante dos Estados

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre teorias voluntaristas e não voluntaristas do Direito Internacional
- Conheça as principais teorias normativistas e solidaristas
- Aprenda a aplicar as normas de jus cogens no contexto do Direito Internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.26 (1)", "page_number": 26, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:35:04.880067+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=26", "doc_key": "ab533146d07b3477e2bf24af73d03dbb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a20be366ebc0680915af1e009b2894220691f82aef04d6db060bf14d77558231'),
  ('cpiuris2025::12637d1933a7e6570db1b4fe16127e43', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teorias do Direito Internacional', '## Teorias do Direito Internacional

Discute-se as teorias institucionalistas e jusnaturalistas sobre o Direito Internacional, destacando as diferenças entre elas.

### Conceitos
- **Institucionalismo**: teoria que considera o Direito Internacional como ordenamento da comunidade internacional
- **Jus Naturalista**: teoria que assenta-se em valores suprapositivos e critérios éticos de obrigatoriedade

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre institucionalismo e jusnaturalismo
- Conheça as teorias de Hugo Grócio', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.26 (2)", "page_number": 26, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T19:35:27.174474+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=26", "doc_key": "12637d1933a7e6570db1b4fe16127e43"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '46fb696487095361555317186b532d1077847e74c6214f293a34682526ce9d98'),
  ('cpiuris2025::1a0c7d5082ee6a06cb9f6ece0ffa9b6a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aspectos Introductórios', '## Aspectos Introductórios

Exemplo de prova com questões sobre direitos internacionais, com opções de resposta A, B, C, D e E.

### Conceitos
- **Prova de Direitos Internacionais**: Exame que avalia o conhecimento do candidato em direitos internacionais.
- **Questões de Direito Internacional**: Perguntas que testam a compreensão do candidato sobre regras e princípios internacionais.

### Referências legais
- Art. 21 da Convenção de Viena sobre Direitos do Comércio Internacional
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte ao candidato a identificar as opções corretas.
- Verifique se o candidato entendeu as regras internacionais aplicadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.28", "page_number": 28, "discipline": "Direitos Internacional", "legal_refs": ["Art. 21 da Convenção de Viena sobre Direitos do Comércio Internacional", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T19:36:53.168044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=28", "doc_key": "1a0c7d5082ee6a06cb9f6ece0ffa9b6a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '76d0053b42731876cd7eb816d9371be882f721fb6223d35d63efbc306b178b09'),
  ('cpiuris2025::5facd3e62bb4590fc45ce54e72dabf28', 'doutrina', 'cp_iuris', 'Direitos Internacional — Obrigatoriedade do Direito Internacional', '## Obrigatoriedade do Direito Internacional

A corrente voluntarista considera que a obrigatoriedade deve basear-se no consentimento dos cidadãos, enquanto a corrente objetivista defende que o consentimento perceptivo nasce da vontade dos Estados.

### Conceitos
- **Obrigatoriedade do Direito Internacional**: A questão de se o direito internacional é obrigatório ou não
- **Consentimento**: A aceitação voluntária por parte dos Estados
- **Vontade dos Estados**: A ideia de que os Estados devem agir de acordo com sua própria vontade

### Referências legais
- Art. 23 da Convenção de Viena sobre Direitos do Comércio Internacional
- ...

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a diferença entre consentimento e vontade dos Estados
- Conheça as correntes voluntarista e objetivista no direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.27 (2)", "page_number": 27, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Direitos do Comércio Internacional", "..."], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T19:37:00.071799+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=27", "doc_key": "5facd3e62bb4590fc45ce54e72dabf28"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5b31ed1d6458958ec6667a5f6e7b95c0a315f2856f6d8c34381ad23f51abe45a'),
  ('cpiuris2025::1d3df9cef6f0b7be7314b3f78aa881d1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teoria do Direito Internacional', '## Teoria do Direito Internacional

A teoria do direito internacional é discutida, com autores defendendo diferentes abordagens, como a teoria jusnaturalista, objetivista e voluntarista. A discussão enfatiza a necessidade de encontrar um fundamento para o direito internacional, mas também destaca as limitações e críticas às diferentes teorias.

### Conceitos
- **Teoria Jusnaturalista**: Abordagem que defende que o direito internacional é baseado em uma natureza razoável e sociável
- **Teoria Objetivista**: Abordagem que reconhece princípios jurídicos supremos à vontade dos Estados, mas também considera a realidade social
- **Teoria Voluntarista**: Abordagem que defende que o direito internacional é baseado nas escolhas e acordos dos Estados
- **Pacta Sunt Servanda**: Princípio que estabelece que os acordos feitos entre os Estados devem ser respeitados

### Referências legais
- Art. 23 da Convenção de Viena sobre Direito do Comércio Internacional
- Súmula 441 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre teoria jusnaturalista e objetivista.
- Conheça o princípio pacta sunt servanda e sua importância no direito internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.27 (1)", "page_number": 27, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Direito do Comércio Internacional", "Súmula 441 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T19:37:55.101170+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=27", "doc_key": "1d3df9cef6f0b7be7314b3f78aa881d1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '57c82b9a83e5fd7c2deb6a5d130a8e9c4cd430d52b414f17b52b67c0857c99ce'),
  ('cpiuris2025::d272991f701701a6bfc0451f93e0014d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aspectos Introductórios', '## Aspectos Introductórios

