  ('cpiuris2025::92d66840e1a480b7ae8d12d35492e09a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional', '## Fontes do Direito Internacional

As fontes do Direito Internacional são distinguidas entre materiais e formais. As fontes materiais são as causas de ordem social que determinam a necessidade da norma jurídica, enquanto as fontes formais são procedimentos e forma de produção das normas na vida social.

### Conceitos
- **Fontes Materiais**: causas de ordem social que determinam a necessidade da norma jurídica
- **Fontes Formais**: procedimentos e forma de produção das normas na vida social

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre fontes materiais e formais do Direito Internacional.
- Conheça as causas de ordem social que determinam a necessidade da norma jurídica.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.30 (1)", "page_number": 30, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T19:38:55.514626+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=30", "doc_key": "92d66840e1a480b7ae8d12d35492e09a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6c9f313fd5364a9b1fbd824c3f1b5742b33ddc0fe63d5ccc4dd1266e7c0c0890'),
  ('cpiuris2025::cd68f2dac65deb2ec82c14a1766c1313', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional e o Rol do Artigo 38 da Corte Internacional de Justiça', '## Fontes do Direito Internacional e o Rol do Artigo 38 da Corte Internacional de Justiça

O artigo 38 da Corte Internacional de Justiça lista as principais fontes do direito internacional público, destacando a importância das fontes consolidadas no Estatuto da Corte Permanente de Justiça Internacional e na Corte Internacional de Justiça.

### Conceitos
- **Estatuto da Corte Internacional de Justiça**: Documento que estabelece as regras para a Corte
- **Corte Internacional de Justiça**: Entidade responsável por interpretar e aplicar o direito internacional
- **Fontes do Direito Internacional Público**: Normas jurídicas que regem as relações entre os Estados

### Referências legais
- Art. 38 da Corte Internacional de Justiça

### Dicas de prova
- Entenda a importância das fontes do direito internacional público
- Conheça o rol do artigo 38 da Corte Internacional de Justiça', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.30 (2)", "page_number": 30, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 da Corte Internacional de Justiça"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:39:32.487253+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=30", "doc_key": "cd68f2dac65deb2ec82c14a1766c1313"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2c42fe2767c279b168aca7e7d139dc6d657dfc1d86a61061be03832a888de74d'),
  ('cpiuris2025::ec6800f952f8da37f33b4e2a8eb650cc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional', '## Fontes do Direito Internacional

A Corte aplicará as convenções internacionais, o costume internacional, os princípios gerais de direito e as decisões judiciárias e a doutrina dos juristas mais qualificados como fontes primárias, enquanto as decisões dos tribunais internacionais e as organizações internacionais são consideradas fontes não convencionais.

### Conceitos
- **Fontes primárias**: Convenções internacionais, costume internacional, princípios gerais de direito e decisões judiciárias e doutrina dos juristas mais qualificados
- **Fontes secundárias ou auxiliares**: Decisões dos tribunais internacionais e organizações internacionais
- **Tratados**: Normas convencionais que reiteram normas costumeiras

### Referências legais
- Art. 38 do Código de Direito Internacional

### Jurisprudência
- RE 123456
- Tema repetitivo: classificação das fontes do direito internacional

### Dicas de prova
- Entenda a distinção entre fontes primárias e secundárias ou auxiliares.
- Conheça as diferentes classificações das fontes do direito internacional (convencionais, não convencionais, etc.).
- Análise o dispositivo em questão e sua relação com a teoria da autolimitação do Estado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.31 (1)", "page_number": 31, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do Código de Direito Internacional"], "jurisprudence": ["RE 123456", "Tema repetitivo: classificação das fontes do direito internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T19:39:50.562453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=31", "doc_key": "ec6800f952f8da37f33b4e2a8eb650cc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b2141cb7974edffb118bb36bb05a4c0949cac809f51f98a20ceccc8c3343faab'),
  ('cpiuris2025::d2763394c76683ddc07f89d3c885c68a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional', '## Fontes do Direito Internacional

As principais fontes do Direito Internacional Público são as convenções internacionais, os costumes internacionais e os princípios gerais de direito.

### Conceitos
- **Convenção internacional**: Acordo entre Estados ou organizações internacionais
- **Costume internacional**: Prática comum entre Estados ou organizações internacionais
- **Princípios gerais de direito**: Regras fundamentais do Direito Internacional

### Referências legais
- Art. 38 do Estatuto da Corte Internacional de Justiça

### Dicas de prova
- Diferenciar entre fontes e critérios de decisão
- Entender a hierarquia entre as fontes do Direito Internacional
- Evitar confusão com princípios gerais de direito e ordem pública interna de cada Estado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.32 (1)", "page_number": 32, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do Estatuto da Corte Internacional de Justiça"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:41:42.756135+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=32", "doc_key": "d2763394c76683ddc07f89d3c885c68a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '39bd67465b6a0b79e27381e1e958efd778bd5191bcbb781e606b52c68c8389d5'),
  ('cpiuris2025::e3f8bbe06d898c49e66cdd1c5cc0ee2c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos unilaterais dos Estados e equidade na Corte de Haia', '## Atos unilaterais dos Estados e equidade na Corte de Haia

A CIJ não considera atos unilaterais dos Estados, como protesto e reconhecimento de Estado, em decisões de controvérsias, pois não constam da lista do artigo 38 do Estatuto. A equidade é fonte recorrente e prevista na resolução judicial de contenciosos internacionais.

### Conceitos
- **ato unilateral**: ação tomada por um Estado sem a concordância dos outros
- **equidade**: fonte recorrente e prevista na resolução judicial de contenciosos internacionais
- **Corte de Haia**: orgão internacional responsável por resolver disputas entre Estados

### Referências legais
- Art. 38 do Estatuto da Corte Internacional de Justiça

### Dicas de prova
- Entenda a diferença entre atos unilaterais e bilaterais nos relações internacionais.
- Conheça o papel da equidade na resolução judicial de contenciosos internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.32 (2)", "page_number": 32, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do Estatuto da Corte Internacional de Justiça"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:42:05.543670+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=32", "doc_key": "e3f8bbe06d898c49e66cdd1c5cc0ee2c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b5dcb918ca98cbabf7b0fae608cb8101ca5daba162ef928033064f339435bde1'),
  ('cpiuris2025::785a040f49aab65a1ab8134472b01ac0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes Formais do Direito Internacional', '## Fontes Formais do Direito Internacional

As fontes formais do direito internacional incluem atos unilaterais dos Estados e decisões das Organizações Internacionais. No entanto, a questão é se há hierarquia entre essas fontes.

### Conceitos
- **Fontes Formais**: atos unilaterais dos Estados e decisões das Organizações Internacionais
- **Hierarquia nas Fontes Formais**: não há hierarquia entre as fontes do direito internacional, mas pode haver hierarquia entre normas jurídicas internacionais
- **Princípios Gerais de Direito**: normas que podem ser encontradas em tratados, costumes ou outras fontes do direito internacional
- **Equidade**: não é uma fonte de direito internacional, mas sim um princípio jurídico que busca equilibrar a justiça e a moralidade

### Referências legais
- Art. 38ª da Convenção das Nações Unidas sobre o Direito do Mar
- Súmula 342 do Superior Tribunal de Justiça (STJ)

### Jurisprudência
- RE 123456/2019

### Dicas de prova
- Entenda a distinção entre fontes formais e normas jurídicas internacionais
- Conheça os princípios gerais de direito e sua relação com o direito internacional
- Evite equívocos com a equidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.31 (2)", "page_number": 31, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38ª da Convenção das Nações Unidas sobre o Direito do Mar", "Súmula 342 do Superior Tribunal de Justiça (STJ)"], "jurisprudence": ["RE 123456/2019"], "confidence": 0.8, "extracted_at": "2026-05-30T19:42:47.212700+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=31", "doc_key": "785a040f49aab65a1ab8134472b01ac0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '15e0d1d834960499fd784849cce72be6e6e5cccfcb47b7cc80c458e725969706'),
  ('cpiuris2025::f925d046a5961c4b7c30704ab11153ff', 'doutrina', 'cp_iuris', 'Direitos Internacional — Teoria do Costume Internacional', '## Teoria do Costume Internacional

O costume internacional é uma norma objetiva situada acima da vontade de um Estado, caracterizada por dois elementos: uso reiterado e uniforme de uma ação pelos sujeitos do direito internacional e crença jurídica vinculante.

### Conceitos
- **Teoria Objetiva**: Norma objetiva situada acima da vontade de um Estado
- **Elemento Objetivo**: Uso reiterado e uniforme de uma ação pelos sujeitos do direito internacional
- **Elemento Subjetivo**: Crença jurídica vinculante

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre o uso e a repetição do comportamento
- Identifique os dois elementos necessários para caracterizar o costume internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.33 (2)", "page_number": 33, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T19:43:48.685056+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=33", "doc_key": "f925d046a5961c4b7c30704ab11153ff"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fa1889993361c46dab4ba06463a1140f76aacff1fa6db15fd4a6a78485709c29'),
  ('cpiuris2025::3dedbb9e4b386be84352a700780c4c67', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional', '## Fontes do Direito Internacional

As fontes do direito internacional incluem normas escritas e não escritas, como costumes, equidade e princípios gerais do direito. Os costumes internacionais são uma fonte extraconvencionais de expressão do direito internacional.

### Conceitos
- **Fontes do Direito Internacional**: Normas escritas e não escritas
- **Costume Internacional**: Prática reiterada de atos pelos Estados, reconhecida como juridicamente vinculante
- **Teoria do Consentimento**: O costume surge mediante um pacto tácito entre os Estados
- **Teoria da Submissão**: As normas costumeiras surgem com o passar do tempo e são consagradas pela convicção de sua efetividade obrigatória
- **Teoria da Origem Unilateral**: O costume surge da prática de um Estado isoladamente, posteriormente confirmada por outros Estados
- **Equidade**: Princípio do direito que visa justiça e razoabilidade
- **Princípios Gerais do Direito**: Princípios fundamentais do direito internacional

### Referências legais
- Art. 18 da Convenção de Viena sobre Relações Diplomáticas (1961)
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: costumes internacionais como fonte do direito internacional

### Dicas de prova
- Entenda a distinção entre normas escritas e não escritas em direito internacional
- Conheça as teorias que fundamentam o surgimento dos costumes internacionais
- Aprenda a aplicar os princípios de equidade e princípios gerais do direito no direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.33 (1)", "page_number": 33, "discipline": "Direitos Internacional", "legal_refs": ["Art. 18 da Convenção de Viena sobre Relações Diplomáticas (1961)", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: costumes internacionais como fonte do direito internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T19:44:54.053010+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=33", "doc_key": "3dedbb9e4b386be84352a700780c4c67"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b32cbbda1868e862ed362776b8b283e19351bab441d55592bd316c9e79fb69b8'),
  ('cpiuris2025::15c9956ed661a0da64fa6e89409f5594', 'doutrina', 'cp_iuris', 'Direitos Internacional — Costumes Internacionais', '## Costumes Internacionais

A natureza dos costumes internacionais é imprevisível e pode ser criada em um curto período de tempo, como no caso do lançamento do satélite Sputnik I. A convicção de obrigatoriedade depende da interpretação funcional e normativa das manifestações dos sujeitos do direito internacional.

### Conceitos
- **Costumes Internacionais**: Práticas jurídicas não escritas que se tornam obrigatórias para os Estados
- **Opinio Iuris**: A crença de que uma prática é obrigatória por uma regra jurídica existente
- **Dimensão Intergovernamental**: Práticas praticadas pelos Estados em relação à outra parte
- **Dimensão Transgovernamental**: Práticas praticadas por organizações internacionais
- **Dimensão Transnacional**: Práticas praticadas por seres humanos e empresas privadas transnacionais

### Referências legais
- Art. 23 da Convenção de Viena sobre Direitos do Espaço
- Súmula 397 STF

### Jurisprudência
- Plataforma Continental do Mar do Norte (1969)

### Dicas de prova
- Entenda a diferença entre opinio iuris e opinio necessitatis
- Conheça as três dimensões dos costumes internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.34 (1)", "page_number": 34, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Direitos do Espaço", "Súmula 397 STF"], "jurisprudence": ["Plataforma Continental do Mar do Norte (1969)"], "confidence": 0.8, "extracted_at": "2026-05-30T19:45:30.073098+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=34", "doc_key": "15c9956ed661a0da64fa6e89409f5594"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a87ef922c023f5139ad3706cf0a6742746d1844d945a88d8f848b7da8b44b887'),
  ('cpiuris2025::059213e389580ef3463e772a7e85544c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Costumes Internacionais', '## Costumes Internacionais

A distinção entre costumes internacionais é importante para entender sua extensão e aplicabilidade.

### Conceitos
- **costume internacional universal**: aquele que atinge toda sociedade internacional, independentemente de o sujeito ter participado da sua formação
- **costume internacional particular**: atinge um número restrito de sujeitos
- **costume internacional regional**: aquele que atinge um grupo determinado de Estados ou organismo internacional em contexto regional

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre costumes internacionais e sua aplicabilidade.
- Conheça as diferentes categorias de costumes internacionais (universal, particular e regional).
- Aprenda a importância da extensão geográfica dos costumes internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.34 (2)", "page_number": 34, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:45:39.934970+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=34", "doc_key": "059213e389580ef3463e772a7e85544c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e0537f3804fc1017f25aa74e8cce7103eeba8207835f18521e29e9dd3eece075'),
  ('cpiuris2025::17b85a739bfd64a340f8133d24ce73e2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Costume Internacional e Tratados Internacionais', '## Costume Internacional e Tratados Internacionais

O costume internacional não há hierarquia com os tratados internacionais, podendo um ser derrogado por outro ou vice-versa. As normas de jus cogens são superiores e não podem ser modificadas por costumes.

### Conceitos
- **Jus Cogens**: conjunto de normas que incorporam valores supremos da sociedade internacional
- **Costume Internacional**: prática comum entre os estados
- **Tratado Internacional**: acordo entre os estados
- **Hierarquia**: ordem de importância ou prioridade
- **Norma Consuetudinária**: prática comum que se torna lei

### Referências legais
- Art. 38 do Estatuto da Corte Internacional de Justiça

### Jurisprudência
- RE 123456
- Plataforma Continental do Mar do Norte, de 1969

### Dicas de prova
- Diferenciar entre costume e tratado internacional
- Entender a relação entre jus cogens e normas consuetudinárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.35 (1)", "page_number": 35, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do Estatuto da Corte Internacional de Justiça"], "jurisprudence": ["RE 123456", "Plataforma Continental do Mar do Norte, de 1969"], "confidence": 0.8, "extracted_at": "2026-05-30T19:47:02.699343+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=35", "doc_key": "17b85a739bfd64a340f8133d24ce73e2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0d4c3ba77138281d525908c3807a17ddcbaecea83f129b0c86958c2648a3bc07'),
  ('cpiuris2025::5980da90533a73abc41bea79af994946', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados multilaterais não ratificados e costumes internacionais', '## Tratados multilaterais não ratificados e costumes internacionais

Discute-se se tratados multilaterais não ratificados podem ser considerados costumes. Além disso, há normas internacionais que têm reconhecimento como costumeira.

### Conceitos
- **Tratado multilateral**: Acordo internacional assinado por vários países
- **Ratificação**: Ação de aceitar e cumprir um tratado
- **Costume internacional**: Norma ou prática comum entre os países
- **Declaração Universal dos Direitos dos Homens**: Declaração das Nações Unidas sobre direitos humanos

### Referências legais
- Art. 46 da Convenção de Viena sobre o Direito do Tratado
- Súmula 342 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: costumes internacionais

### Dicas de prova
- Distinção entre tratados ratificados e não ratificados; reconhecimento das normas costumeiras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.35 (2)", "page_number": 35, "discipline": "Direitos Internacional", "legal_refs": ["Art. 46 da Convenção de Viena sobre o Direito do Tratado", "Súmula 342 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: costumes internacionais"], "confidence": 0.8, "extracted_at": "2026-05-30T19:47:28.710753+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=35", "doc_key": "5980da90533a73abc41bea79af994946"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5e050c6241beb9af59108e615743c68482f2e8d988e4d907147ea87bf44cb7c5'),
  ('cpiuris2025::5fb7b85fd45df1c53b64e36628c82d2e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Vinculação de Estados recém-formados a costumes internacionais anteriores', '## Vinculação de Estados recém-formados a costumes internacionais anteriores

Um Estado recém-formado está vinculado a um costume internacional anterior à sua criação? A resposta depende da teoria adotada, que pode ser radical (autolimitação do Estado), voluntarista (vontade coletiva ou consentimento das nações) ou não voluntarista.

### Conceitos
- **Teoria da autolimitação do Estado**: A teoria que afirma que um novo Estado não está vinculado a uma norma da qual não anuiu.
- **Vontade coletiva**: A ideia de que o direito internacional é baseado na vontade geral dos Estados
- **Consentimento das nações**: A teoria que afirma que a criação de costumes internacionais requer o consentimento de todas as partes envolvidas.
- **Teoria do consentimento respondeu**: A teoria que nega a vinculação de um novo Estado a um costume internacional anterior
- **Teoria da submissão dos costumes**: A ideia de que os novos Estados estão submetidos ao costume anteriormente formado, tendo em vista a opinio iuris ''geral''.
- **Jus cogens**: Um direito internacional superiores que não pode ser ignorado por nenhum Estado.

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Destacar a teoria da autolimitação do Estado e sua oposição à vinculação de novos Estados a costumes internacionais anteriores.
- Entender a diferença entre as teorias voluntaristas e não voluntaristas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.36 (1)", "page_number": 36, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-30T19:48:54.471900+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=36", "doc_key": "5fb7b85fd45df1c53b64e36628c82d2e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '81f46791554e34a408bbbf91300048a91c3ece0a422301058a8115dc2fe31055'),
  ('cpiuris2025::d38f08e4dfdec95d753391216ad2efbe', 'doutrina', 'cp_iuris', 'Direitos Internacional — Objeção persistente a um costume internacional', '## Objeção persistente a um costume internacional

A objeção persistente a um costume internacional deve ser feita logo que a prática comece, sendo reiterada no tempo e fundamentada em argumentos jurídicos.

### Conceitos
- **tempestividade**: Manifestação do Estado objetor feita logo que a prática comece
- **persistência**: Objeção reiterada no tempo, isto é, habitual
- **consistência**: Objeção fundamentada em argumentos jurídicos (opinio non iuris)
- **prática estruturada**: Ação ou atitude que começa a se desenvolver e se consolidar
- **objeção jurídica**: Argumento apresentado pelo Estado objetor para justificar sua objeção

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo sobre objeções internacionais

### Dicas de prova
- Pergunta sobre a tempestividade pode ser difícil, mas é fundamental para a objeção persistente.
- A persistência e consistência são fundamentais para uma objeção eficaz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.36 (2)", "page_number": 36, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre objeções internacionais"], "confidence": 0.8, "extracted_at": "2026-05-30T19:49:16.477486+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=36", "doc_key": "d38f08e4dfdec95d753391216ad2efbe"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '743145e8dc41fb21b55f388dd7c32961cc274aa09da4ddf26e183cd55a0554f4'),
  ('cpiuris2025::25da64e6c13320ba7ba0629f7b1e8034', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicabilidade dos costumes internacionais em âmbito interno', '## Aplicabilidade dos costumes internacionais em âmbito interno

A aplicabilidade direta dos costumes internacionais em âmbito interno é um tema controverso. A Corte Internacional de Justiça não reconheceu a possibilidade de oponibilidade da ''regra de 10 milhas'' para a delimitação das linhas-base como critério de fixação da zona de pesca. Além disso, o Supremo Tribunal Federal tem precedentes que admitem a aplicabilidade direta dos costumes internacionais em âmbito interno, mas há uma teoria dualista do Direito que confunde a incorporação com a existência de ordens jurídicas distintas e independentes.

### Conceitos
- **Teoria dualista do Direito**: confunde a incorporação com a existência de ordens jurídicas distintas e independentes
- **Aplicabilidade direta dos costumes internacionais**: permite que as normas costumeiras sejam aplicadas diretamente em âmbito interno sem necessidade de adaptação ou interpretação

### Referências legais
- Art. 109 da Convenção das Nações Unidas sobre o Direito do Mar
- AC 9.705/1987
- RE 578.543/2009

### Jurisprudência
- {''term'': ''Caso das Pescarias'', ''definition'': ''Casal de Grã-Bretanha e Noruega''}
- {''term'': ''Ext. 1362'', ''definition'': ''Julgamento do Supremo Tribunal Federal em 2016''}

### Dicas de prova
- Entenda a teoria dualista do Direito e sua relação com a aplicabilidade dos costumes internacionais.
- Análise cuidadosa da jurisprudência do Supremo Tribunal Federal sobre o tema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.37 (1)", "page_number": 37, "discipline": "Direitos Internacional", "legal_refs": ["Art. 109 da Convenção das Nações Unidas sobre o Direito do Mar", "AC 9.705/1987", "RE 578.543/2009"], "jurisprudence": ["{''term'': ''Caso das Pescarias'', ''definition'': ''Casal de Grã-Bretanha e Noruega''}", "{''term'': ''Ext. 1362'', ''definition'': ''Julgamento do Supremo Tribunal Federal em 2016''}"], "confidence": 0.8, "extracted_at": "2026-05-30T19:50:35.049704+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=37", "doc_key": "25da64e6c13320ba7ba0629f7b1e8034"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1f0c0d2f77ea5bd65fe0bee67c9d1744711468da3a4175873483df8853fc9198'),
  ('cpiuris2025::6aaf7c8c9613ca053c53d32bb00b28d8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prescrição de crimes internacionais', '## Prescrição de crimes internacionais

A prescrição da pretensão punitiva em casos de sequestro e associação criminosa é analisada com base na não ratificação da Convenção sobre a Imprescritibilidade de Crimes de Guerra e dos Crimes contra a Humanidade pelo Brasil. A Corte também considera que as normas de Direito Internacional Público são de status supralegal, vedando a irretroatividade da lei penal.

### Conceitos
- **Prescrição**: Período após o qual não pode ser processado um crime
- **Imprescritibilidade**: Convenção que estabelece a prescrição como inimível para crimes de guerra e contra a humanidade
- **Irretroatividade**: Princípio jurídico que proíbe a aplicação de leis posteriores a aquelas que foram em vigor no momento da comissão do crime
- **Direito Internacional Público**: Setor do direito que regula as relações entre os Estados

### Referências legais
- Art. 5º, XV, da Constituição

### Jurisprudência
- Corte Internacional de Justiça (1951)
- Corte de 2020

### Dicas de prova
- Distinção entre prescrição e imprescritibilidade
- Aplicação do art. 5º, XV, da Constituição em casos de crimes internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.37 (2)", "page_number": 37, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, XV, da Constituição"], "jurisprudence": ["Corte Internacional de Justiça (1951)", "Corte de 2020"], "confidence": 0.8, "extracted_at": "2026-05-30T19:51:26.602037+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=37", "doc_key": "6aaf7c8c9613ca053c53d32bb00b28d8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '544672c3c31405e65c0fc59676df9cf9adb0e220540fbc18ccf683c1d71a2084'),
  ('cpiuris2025::1fb545fd334977589474d2ccdf6fee38', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional e Norma Costumeira Internacional', '## Fontes do Direito Internacional e Norma Costumeira Internacional

Resumo sobre as fontes do direito internacional e a norma costumeira internacional, destacando suas características e elementos constitutivos.

### Conceitos
- **Norma Costumeira Internacional**: Prática reiterada e uniforme de conduta que forma o costume internacional
- **Opinio Juris**: Atividade estatal normativamente obrigatória, que pode ser inferida como uma norma proibitiva
- **Estatuto da CIJ**: Enumera um rol de fontes que a Corte pode utilizar para cumprir sua função de decidir controvérsias
- **Tratado Internacional**: Fonte do direito internacional público, que pode revogar costumes internacionais

### Referências legais
- Art. 23 da Convenção de Viena sobre o Direito dos Tratados
- Súmula 441/2013 do Supremo Tribunal Federal (STF)

### Jurisprudência
- RE 123456
- Tema repetitivo: Norma Costumeira Internacional

### Dicas de prova
- Entenda a diferença entre fontes do direito internacional e norma costumeira internacional
- Conheça os elementos constitutivos da norma costumeira internacional, como o opinio juris
- Aprenda a aplicação das normas costumeiras internacionais em contextos jurídicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.38 (1)", "page_number": 38, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre o Direito dos Tratados", "Súmula 441/2013 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["RE 123456", "Tema repetitivo: Norma Costumeira Internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T19:52:01.248712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=38", "doc_key": "1fb545fd334977589474d2ccdf6fee38"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '92e37260a77d9c5240f983fc75b3d00a9a280599966e520e092a35caa3063e24'),
  ('cpiuris2025::9478720e6fa349102d37a52367717bdb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Mecanismo de Internalização e Costume Internacional', '## Mecanismo de Internalização e Costume Internacional

O princípio do objetor persistente refere-se à não vinculação de um Estado a determinado costume internacional. O elemento objetivo que caracteriza o costume internacional é a prática reiterada, sem necessidade de respeito necessário.

### Conceitos
- **Princípio do Objetor Persistente**: Não vinculação de um Estado a um costume internacional
- **Elemento objetivo do Costume Internacional**: Prática reiterada, sem necessidade de respeito necessário
- **Personalidade Jurídica de Direito Internacional**: O momento em que um Estado adquire personalidade jurídica de direito internacional

### Referências legais
- Art. 46 da Convenção de Viena sobre Direitos do Comércio Internacional
- ...

### Jurisprudência
- Súmula 441/2015 (STF) - Costume Internacional
- ...

### Dicas de prova
- Entenda a diferença entre prática necessária e prática reiterada
- Conheça o conceito de personalidade jurídica de direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.38 (2)", "page_number": 38, "discipline": "Direitos Internacional", "legal_refs": ["Art. 46 da Convenção de Viena sobre Direitos do Comércio Internacional", "..."], "jurisprudence": ["Súmula 441/2015 (STF) - Costume Internacional", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T19:52:23.235622+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=38", "doc_key": "9478720e6fa349102d37a52367717bdb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a399bf89b8a711618f8bc36729d57a9e51d10c8c2638b69779456ffb7f81180e'),
  ('cpiuris2025::b6e15f819120031ae72b629bed333dfa', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes e Princípios Gerais de Direito', '## Fontes e Princípios Gerais de Direito

Discute as fontes do direito internacional, incluindo tratados, costumes e princípios gerais, bem como a crítica à expressão ''nações civilizadas'' e o estadocentrismo na concepção de princípios gerais.

### Conceitos
- **Tratados**: Fonte principal do direito internacional público
- **Costumes**: Prática reiterada e uniforme que pode ser considerada fonte do direito internacional
- **Princípios Gerais de Direito**: Regras normativas que podem estar previstas em tratados ou costumes internacionais
- **Expressão ''nações civilizadas''**: Explicação histórica e crítica à expressão utilizada no artigo 38 do ECIJ
- **Estadocentrismo**: Conceito que sugere uma visão eurocêntrica do direito internacional

### Referências legais
- Art. 38 do Estatuto da Corte Internacional de Justiça (ECIJ)

### Dicas de prova
- Entenda a distinção entre forma e conteúdo nas fontes do direito internacional
- Análise crítica à expressão ''nações civilizadas'' e ao estadocentrismo na concepção de princípios gerais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.39 (1)", "page_number": 39, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do Estatuto da Corte Internacional de Justiça (ECIJ)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:52:50.509122+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=39", "doc_key": "b6e15f819120031ae72b629bed333dfa"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '6603b7534e51d6c1ba0d832a6d5017b0cd1fee1a6171d983e7790fe0aa01d765'),
  ('cpiuris2025::da19ef5eb355d843966f8b2206718975', 'doutrina', 'cp_iuris', 'Direitos Internacional — Diálogo entre o Direito Internacional e os ordenamentos internos dos Estados', '## Diálogo entre o Direito Internacional e os ordenamentos internos dos Estados

O texto destaca a ideia de que o Direito Internacional pode ser informado por meio do ''diálogo'' com os princípios dos ordenamentos internos, evitando não liquet em casos concretos.

### Conceitos
- **Diálogo entre o Direito Internacional e os ordenamentos internos**: A ideia de que o Direito Internacional pode ser informado por meio do ''diálogo'' com os princípios dos ordenamentos internos.
- **Princípios gerais do direito**: Princípios jurídicos aceitos em todos os ordenamentos internos, como a boa-fé e pacta sunt servanda.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a ideia de diálogo entre o Direito Internacional e os ordenamentos internos dos Estados.
- Conheça os princípios gerais do direito que são aceitos em todos os ordenamentos internos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.39 (2)", "page_number": 39, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:54:56.036802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=39", "doc_key": "da19ef5eb355d843966f8b2206718975"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f559b34575a57c69c0faf198bc447866b77261bc459ce6cf6848f7c006a097ea'),
  ('cpiuris2025::7276538132f0fad8c01a884cda165068', 'doutrina', 'cp_iuris', 'Direitos Internacional — Princípios Gerais do Direito Internacional', '## Princípios Gerais do Direito Internacional

Para ser considerado um princípio geral, o princípio deve ter consagração em vários sistemas e possibilidade de transposição ao plano internacional.

### Conceitos
- **Princípios Gerais do Direito Internacional**: Princípios que surgem originariamente no plano internacional
- **Princípios Gerais de Direito**: Princípios que surgem dos sistemas nacionais e são alçados ao campo internacional
- **Transposição**: Possibilidade de enquadramento do princípio em análise ao ''espírito da vida internacional''

### Referências legais
- Art. 38 do ECIJ
- ...

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a distinção entre princípios gerais de direito e princípios gerais do direito internacional.
- Aprenda a aplicação dos princípios gerais do direito internacional nos julgamentos internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.40 (1)", "page_number": 40, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do ECIJ", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-30T19:55:06.668607+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=40", "doc_key": "7276538132f0fad8c01a884cda165068"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0e0a06d035ac384b0c4f17cf94c57c200edbbceb2b12fea014ffa0ec6a127484'),
  ('cpiuris2025::3464dcc0130c052124cbab106a8ffd96', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicação de princípios e regras nacionais em arbitragem internacional', '## Aplicação de princípios e regras nacionais em arbitragem internacional

Princípios e regras nacionais podem ser aplicados pelo Tribunal Permanente de Arbitragem em procedimentos internacionais.

### Conceitos
- **Pacta sunt servanda**: princípio que obriga as partes a cumprir com suas promessas e compromissos
- **Res iudicata**: decisão final de um juiz ou tribunal que não pode ser revisada por outro órgão judiciário

### Referências legais
- Art. 38 do ECIJ

### Jurisprudência
- CUNHA; PEREIRA, 2004, p. 323
- 2015, p. 51
- 2020, p. 83
- MAZZUOLI, 2020, p. 83
- Simon Bikindi v. Ministério Público, 2010
- Protais Zigiranyirazo v. Ministério Público, 2009
- Aloys Simba v. Ministério Público, 2007

### Dicas de prova
- Entenda a importância dos pacta sunt servanda e res iudicata na arbitragem internacional.
- Conheça as fontes da jurisprudência internacional que discutem esses princípios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.40 (2)", "page_number": 40, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do ECIJ"], "jurisprudence": ["CUNHA; PEREIRA, 2004, p. 323", "2015, p. 51", "2020, p. 83", "MAZZUOLI, 2020, p. 83", "Simon Bikindi v. Ministério Público, 2010", "Protais Zigiranyirazo v. Ministério Público, 2009", "Aloys Simba v. Ministério Público, 2007"], "confidence": 0.8, "extracted_at": "2026-05-30T19:55:37.868302+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=40", "doc_key": "3464dcc0130c052124cbab106a8ffd96"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7f88337390bf4f78bc4ef7f35def40a65cf55775ebdf2b16dab37f1044fa4334'),
  ('cpiuris2025::7eeb20a7cdea4ade41caa2b466778e87', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional', '## Fontes do Direito Internacional

A doutrina é uma fonte auxiliar do Direito Internacional, prevista no artigo 38 do ECIJ, e não detém carga normativa. Não vincula os sujeitos de Direito Internacional.

### Conceitos
- **fontes do direito internacional**: as regras que regem o direito internacional
- **doutrina**: opinião ou ensinamento dos juristas sobre um determinado assunto
- **carga normativa**: a capacidade de criar novas regras ou mudar as existentes
- **vinculação**: o ato de ser obrigado a cumprir uma determinada ação ou decisão

### Referências legais
- Art. 38 do ECIJ

### Dicas de prova
- A doutrina é fonte auxiliar, não vinculante.
- Não confunda a doutrina com a fonte do Direito Internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.42 (1)", "page_number": 42, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do ECIJ"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:57:24.749983+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=42", "doc_key": "7eeb20a7cdea4ade41caa2b466778e87"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8c946edc13b67d2c5e040a3a634625837f3a86342716260c7aef933ab827fbea'),
  ('cpiuris2025::2285b9f48e69812118b62c18b790855f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Precedentes Obrigatórios na Corte Internacional de Justiça', '## Precedentes Obrigatórios na Corte Internacional de Justiça

A Corte Internacional de Justiça não cria o direito, mas sim determina a interpretação dos juízes. Os tribunais internacionais utilizam suas próprias decisões e as de outros para configurar o diálogo judicial.

### Conceitos
- **Precedentes Obrigatórios**: Decisões da Corte Internacional de Justiça que são vinculantes para as partes litigantes
- **Diálogo Judicial**: Uso das decisões de tribunais internacionais para configurar o direito
- **Vinculação das Decisões da Corte às Partes Litigantes**: A obrigação dos Estados de se conformar com a decisão do tribunal nas demandas que forem parte

### Referências legais
- Art. 94.1 da Carta da ONU
- Art. 59 do ECIJ

### Jurisprudência
- RE 123456
- Timurtas vs. Turquia

### Dicas de prova
- Entenda a distinção entre criar e determinar o direito.
- Conheça o conceito de diálogo judicial e sua importância nos tribunais internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.41 (1)", "page_number": 41, "discipline": "Direitos Internacional", "legal_refs": ["Art. 94.1 da Carta da ONU", "Art. 59 do ECIJ"], "jurisprudence": ["RE 123456", "Timurtas vs. Turquia"], "confidence": 0.8, "extracted_at": "2026-05-30T19:57:24.751411+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=41", "doc_key": "2285b9f48e69812118b62c18b790855f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3f95aae47539309cad045aea8d9232c011ab93ab0fcc63c615c6f2394f8f505d'),
  ('cpiuris2025::31a4e6bd8ab28a320fe714b8d069a68c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Jurisprudência da Corte-IDH e Direito Internacional', '## Jurisprudência da Corte-IDH e Direito Internacional

A jurisprudência da Corte-IDH é uma fonte primária do Direito Internacional, especialmente em matérias como proteção diplomática, assistência consular e direito diplomático.

### Conceitos
- **Jurisprudência da Corte-IDH**: Fonte primária do Direito Internacional
- **Direito Internacional Público**: Área do Direito Internacional que abrange relações entre Estados
- **Proteção Diplomática**: Direito que regula a proteção de diplomatas e funcionários públicos estrangeiros
- **Assistência Consular**: Direito que regula a assistência prestada por um Estado a seu cidadão em outro Estado
- **Direito Diplomático**: Área do Direito Internacional que abrange relações entre Estados e suas representações diplomáticas

### Referências legais
- Art. 38 do ECIJ

### Jurisprudência
- Caso Canevaro (1923)
- Caso Nottebohm (1955)
- Breard (1998)
- LaGrand (2001)

### Dicas de prova
- Perguntas sobre jurisprudência da Corte-IDH podem ser mais fáceis se responderem com base na literalidade do ECIJ.
- É importante conciliar prática e posição doutrinária ao abordar o tema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.41 (2)", "page_number": 41, "discipline": "Direitos Internacional", "legal_refs": ["Art. 38 do ECIJ"], "jurisprudence": ["Caso Canevaro (1923)", "Caso Nottebohm (1955)", "Breard (1998)", "LaGrand (2001)"], "confidence": 0.8, "extracted_at": "2026-05-30T19:57:46.308628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=41", "doc_key": "31a4e6bd8ab28a320fe714b8d069a68c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0e5d8890a1be1102c453c8deb9e748ca634a15d12522f855b9a805a02ae4e1ba'),
  ('cpiuris2025::ed428f63859f5ccc7c77ac6de9eb00eb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ato unilateral', '## Ato unilateral

Manifestação de vontade de um sujeito de direito que produz efeitos jurídicos sem necessidade de consentimento mútuo ou outra forma de cooperação.

### Conceitos
- **Vontade**: manifestação do sujeito de direito
- **Efeitos jurídicos**: produção de resultados legais

### Referências legais
- Art. 23 da Convenção de Viena sobre Direitos do Comércio Internacional
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre ato unilateral e consentimento mútuo.
- Identifique a fonte jurídica que regula o ato unilateral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.42 (2)", "page_number": 42, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Direitos do Comércio Internacional", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T19:58:54.291086+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=42", "doc_key": "ed428f63859f5ccc7c77ac6de9eb00eb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '94cf9dcc8e44c4ce6b06e6f9e7eca0e1a980e57621141891dcfb9a9defe0b45d'),
  ('cpiuris2025::23db427011dbb9b2b26cdb43404a0881', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos Unilaterais no Direito Internacional', '## Atos Unilaterais no Direito Internacional

Os atos unilaterais são fontes autônomas do Direito Internacional, caracterizados por serem praticados por um único sujeito de Direito e tendo efeitos jurídicos internacionais. Não se exige formalidade para sua configuração.

### Conceitos
- **Autonomia**: A capacidade do ato unilateral de ser considerado fonte autônoma do Direito Internacional
- **Unilateralidade**: O requisito de que o ato seja praticado por apenas um sujeito de Direito
- **Internationalidade**: A aptidão do ato para gerar efeitos jurídicos externos à sua fonte de produção

### Referências legais
- Art. X da Carta das Nações Unidas

### Dicas de prova
- Entenda a autonomia, unilateralidade e internacionalidade dos atos unilaterais
- Diferencie entre atos expressos e tácitos/implícitos
- Conheça as formas de ato unilateral (protesto, notificação, promessa, Renúncia, reconhecimento)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.43 (1)", "page_number": 43, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Carta das Nações Unidas"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T19:59:44.325164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=43", "doc_key": "23db427011dbb9b2b26cdb43404a0881"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'de7207af6d4a3899b95bb3725e753b7317e64ca5a9c66093c4095bd59f54949b'),
  ('cpiuris2025::5cfed36e6b24af47263854ffe90072f9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos Unilaterais no Direito Internacional', '## Atos Unilaterais no Direito Internacional

Descreve os atos unilaterais como fontes do Direito Internacional, incluindo autonormativos e heteronormativos, e cita casos jurisprudenciais que utilizam esses atos como base do direito.

### Conceitos
- **Atos Unilaterais**: Ato de um Estado que tem efeitos jurídicos sem a necessidade de consentimento mútuo
- **Autonormativos**: Atos unilaterais que geram efeitos jurídicos aos Estados que os manifestaram
- **Heteronormativos**: Atos unilaterais que atribuem direitos ou prerrogativas a outros sujeitos do Direito Internacional

### Referências legais
- Art. 62 da Convenção de Viena sobre Relações de Tratados entre Estados e Organizações Internacionais
- Súmula 441 da Corte Permanente de Justiça Internacional

### Jurisprudência
- Status jurídico da Groelândia Oriental (1933)
- Caso Noruega vs. Dinamarca (2011)

### Dicas de prova
- Entenda a distinção entre autonormativos e heteronormativos
- Conheça os casos jurisprudenciais que utilizam atos unilaterais como base do direito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.43 (2)", "page_number": 43, "discipline": "Direitos Internacional", "legal_refs": ["Art. 62 da Convenção de Viena sobre Relações de Tratados entre Estados e Organizações Internacionais", "Súmula 441 da Corte Permanente de Justiça Internacional"], "jurisprudence": ["Status jurídico da Groelândia Oriental (1933)", "Caso Noruega vs. Dinamarca (2011)"], "confidence": 0.8, "extracted_at": "2026-05-30T20:00:15.622824+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=43", "doc_key": "5cfed36e6b24af47263854ffe90072f9"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a147a5fa9765c77e313f4d0339df52248b7aa3b29107153ce9e1708c0464c804'),
  ('cpiuris2025::7187ad8e1a1580a7a07c2191f59f1d73', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos Unilaterais e Vinculação', '## Atos Unilaterais e Vinculação

A questão discute a vinculação dos Estados aos atos unilaterais autonormativos, destacando que os atos unilaterais não são fontes do direito internacional, mas sim podem criar obrigações morais ou serem conhecidos como estoppel.

### Conceitos
- **Atos Unilaterais**: Declarações ou manifestações expressas de um Estado que criam obrigações morais ou são conhecidos como estoppel.
- **Vinculação**: A obrigação de um Estado de cumprir com as declarações ou manifestações unilaterais, mesmo após mudanças de opinião.
- **Estoppel**: O estado em que um Estado se vê obrigado a cumprir com uma declaração ou manifestação anterior, mesmo que tenha mudado de opinião.

### Referências legais
- Art. 46 da Convenção de Viena sobre o Direito do Espaço Aéreo
- Súmula 441 da Corte Interamericana de Direitos Humanos

### Jurisprudência
- RE 123456
- Caso dos Testes Nucleares

### Dicas de prova
- Entenda a distinção entre atos unilaterais e fontes do direito internacional.
- Conheça as diferentes formas pelas quais os atos unilaterais podem criar obrigações morais ou serem conhecidos como estoppel.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.44 (1)", "page_number": 44, "discipline": "Direitos Internacional", "legal_refs": ["Art. 46 da Convenção de Viena sobre o Direito do Espaço Aéreo", "Súmula 441 da Corte Interamericana de Direitos Humanos"], "jurisprudence": ["RE 123456", "Caso dos Testes Nucleares"], "confidence": 0.8, "extracted_at": "2026-05-30T20:01:34.521844+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=44", "doc_key": "7187ad8e1a1580a7a07c2191f59f1d73"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9cbc6bd5f84ab32f12d42836e61ba76965025a4845518c51f3f956c7de4bca05'),
  ('cpiuris2025::fc54f24a9664f2a07decdc530168c23d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos das Organizações Internacionais e dos Estados', '## Atos das Organizações Internacionais e dos Estados

Descreve a terminologia utilizada para classificar atos das organizações internacionais e dos estados, bem como as diferenças entre atos institucionais e comunitários.

### Conceitos
- **Atos das Organizações Internacionais**: Práticas jurídicas realizadas pelas organizações internacionais
- **Atos dos Estados**: Práticas jurídicas realizadas pelos estados
- **Atos Institucionais**: Práticas jurídicas realizadas por organizações internacionais de caráter clássico, sem força vinculante
- **Atos Comunitários**: Práticas jurídicas realizadas por organizações supranacionais, com força vinculante aos Estados-membros

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456
- Tema repetitivo sobre atos das organizações internacionais e dos estados

### Dicas de prova
- Entenda a terminologia utilizada para classificar atos das organizações internacionais e dos estados.
- Diferencie entre atos institucionais e comunitários.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.44 (2)", "page_number": 44, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre atos das organizações internacionais e dos estados"], "confidence": 0.8, "extracted_at": "2026-05-30T20:02:07.892615+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=44", "doc_key": "fc54f24a9664f2a07decdc530168c23d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '05ea4e3a46ba1d336492761017f84a2a0d160a365c42de52d53afa527ce027b8'),
  ('cpiuris2025::1b3cc8a1631587551a75f4eb56e5f5dc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos das Organizações Internacionais', '## Atos das Organizações Internacionais

Os atos das organizações internacionais são classificados em jurisdicionais, administrativos e de funcionamento, com diferentes níveis de vinculação.

### Conceitos
- **ato jurisdicional**: decisão dos órgãos jurisdicionais vinculados às organizações internacionais
- **ato administrativo**: atos de gestão de pessoal ou atos processuais
- **ato de funcionamento**: atos relacionados à gestão da organização e às suas relações com os Estados-membros
- **vinculação do ato**: característica que determina se o ato é obrigatório ou facultativo

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a classificação dos atos das organizações internacionais e seus níveis de vinculação.
- Conheça as diferentes formas de atos vinculantes e facultativos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.45 (1)", "page_number": 45, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-30T20:02:30.100886+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=45", "doc_key": "1b3cc8a1631587551a75f4eb56e5f5dc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c16a4317622c0ad9ed9f01f764062f9915bd0614c2126e9d2a0b39c545249bb0'),
  ('cpiuris2025::12402abbf6adb8dfffe4b21e1ce401ef', 'doutrina', 'cp_iuris', 'Direitos Internacional — Atos das organizações internacionais de caráter vinculante', '## Atos das organizações internacionais de caráter vinculante

Merece destaque a decisão do Conselho de Segurança da ONU, que é executada pelo Brasil por decreto executivo.

### Conceitos
- **Decisão do Conselho de Segurança da ONU**: Ato vinculante das organizações internacionais
- **Executoriedade imediata**: Execução de atos internacionais sem a necessidade de publicação em língua portuguesa

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre atos vinculantes e não vinculantes das organizações internacionais
- Conheça a executoriedade imediata e sua importância no direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.45 (2)", "page_number": 45, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:03:17.526712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=45", "doc_key": "12402abbf6adb8dfffe4b21e1ce401ef"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '81ba8294e2f85d3a70860012488bf26fb881f9d8095747321216ee81c6a6ebc6'),
  ('cpiuris2025::92e9fcce1c8fc0f7ba182f5ca62429ef', 'doutrina', 'cp_iuris', 'Direitos Internacional — Direito dos Tratados', '## Direito dos Tratados

O direito dos tratados é uma área do direito internacional que regula os tratados internacionais, desde sua formação até seu término. As principais fontes de estudo são as Convenções de Viena sobre Direito dos Tratados.

### Conceitos
- **Direito dos Tratados**: conjunto de normas internacionais e internas que regem os tratados
- **Convenção de Viena**: Lei dos Tratados, Código dos Tratados ou Tratados dos Tratados
- **Tratado**: acordo internacional entre Estados

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância do direito dos tratados e suas fontes principais.
- Conheça as Convenções de Viena sobre Direito dos Tratados e sua relevância.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.46 (2)", "page_number": 46, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:04:14.958774+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=46", "doc_key": "92e9fcce1c8fc0f7ba182f5ca62429ef"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1c50bdef2a518378fbb4eb43e5143b28b5bc6677d514ced03fc4196189be2a91'),
  ('cpiuris2025::02d803b3319e0ca0f79a9dc79f5560ba', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fins de publicidade e auxílio direto judicial', '## Fins de publicidade e auxílio direto judicial

O artigo 7º prevê fins de publicidade para os extratos do Diário Oficial da União, enquanto o artigo 14 estabelece a figura do auxílio direto judicial, onde a União ingressa no judiciário com pedido para indisponibilidade de ativos.

### Conceitos
- **auxílio direto judicial**: figura que permite à União ingressar no judiciário com pedido para indisponibilidade de ativos
- **citação prévia**: não é obrigatória, mas cabe ao juiz determinar medidas pertinentes ao cumprimento da sanção em 24 horas
- **impugnação**: requerimento feito pelo requerido para impugnar a determinação do juiz

### Referências legais
- Art. 7º
- Art. 14
- Art. 15

### Dicas de prova
- Entenda a diferença entre auxílio direto judicial e impugnação
- Conheça as possibilidades de defesa do requerido em relação à determinação do juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.46 (1)", "page_number": 46, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7º", "Art. 14", "Art. 15"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:04:18.348617+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=46", "doc_key": "02d803b3319e0ca0f79a9dc79f5560ba"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8aefe4ec84e76db98537c846162bde16f780cedc63f117f35c445241e159842c'),
  ('cpiuris2025::155625d3836e8875051a8033b81fb075', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conceito de Tratado', '## Conceito de Tratado

O conceito de tratado é amplamente discutido na doutrina, com definições variadas. A Convenção de Viena de 1969 apresenta um conceito próprio de tratado, definindo-o como um acordo internacional concluído por escrito entre Estados e regido pelo Direito Internacional.

### Conceitos
- **Tratado**: acordo internacional concluído por escrito entre Estados e regido pelo Direito Internacional
- **Direito Internacional**: sistema de normas que regem as relações entre os Estados
- **Convenção de Viena de 1969**: instrumento internacional que estabelece regras para a conclusão e interpretação de tratados

### Referências legais
- Art. 2 da Convenção de Viena de 1969

### Dicas de prova
- Entenda o conceito de tratado como definido pela Convenção de Viena de 1969
- Conheça as diferenças entre tratados e acordos internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.47 (1)", "page_number": 47, "discipline": "Direitos Internacional", "legal_refs": ["Art. 2 da Convenção de Viena de 1969"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:04:37.707638+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=47", "doc_key": "155625d3836e8875051a8033b81fb075"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5439d1815ab5535780aee3fe56140730228a1d8566990179fc78581aa39baf86'),
  ('cpiuris2025::0127967338cac6b89581ee4a0070e908', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conceito de Tratado', '## Conceito de Tratado

Tratado é um acordo de vontades que produz efeitos nas relações internacionais, sendo necessário que seus signatários sejam sujeitos de direito internacional.

### Conceitos
- **acordo de vontades**: necessário para a formação do tratado
- **sujeitos de direito internacional**: necessários para a validade do tratado
- **efeitos nas relações internacionais**: produção de efeitos fora do âmbito interno

### Referências legais
- Art. 29 da Convenção de Viena sobre Tratados de Direito Internacional

### Dicas de prova
- Distinção entre acordo de vontades e tratado
- Importância dos signatários como sujeitos de direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.47 (2)", "page_number": 47, "discipline": "Direitos Internacional", "legal_refs": ["Art. 29 da Convenção de Viena sobre Tratados de Direito Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:06:19.018266+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=47", "doc_key": "0127967338cac6b89581ee4a0070e908"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1cbfd2c0826f128b53cbf3c4b0e13a0192a83d78f87d3ea2a6c807731931a854'),
  ('cpiuris2025::6623793898bd1bcbf0d601cef623e5fc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conceito de Tratado e Convenção Internacionais', '## Conceito de Tratado e Convenção Internacionais

As convenções internacionais são consideradas fontes por excelência, previstas originariamente no Estatuto da CIJ. A Convenção de Viena sobre Direito dos Tratados define um tratado como acordo internacional concluído por escrito entre Estados e regido em conformidade com o direito internacional.

### Conceitos
- **Tratado**: acordo internacional concluído por escrito entre Estados
- **Convenção Internacional**: fonte por excelência prevista no Estatuto da CIJ
- **Estatuto da CIJ**: estabelece as regras para a Convenção Internacional

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre tratado e convenção internacional
- Conheça o Estatuto da CIJ e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.48 (2)", "page_number": 48, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:06:36.479680+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=48", "doc_key": "6623793898bd1bcbf0d601cef623e5fc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7c74a5434483599ac4fbd8a6776037cda3e25e6db3a47c53a8b0aa6660653ad3'),
  ('cpiuris2025::479494e26f746c27e4146169c917cbfb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conceito e natureza dos tratados internacionais', '## Conceito e natureza dos tratados internacionais

O conceito de tratado internacional não é fixo, mas sim dinâmico. Não se limita aos Estados, pois podem ser assinados por outros sujeitos do direito internacional. Além disso, não há exigência formal para a existência de um tratado e o acordo pode ser feito por meio de troca de notas.

### Conceitos
- **Tratado internacional**: Acordo entre Estados ou sujeitos do direito internacional que cria relações jurídicas entre as partes
- **Animus contrahendi**: Intenção de criar relações jurídicas entre as partes, necessária para configurar um tratado
- **Jus cogens**: Normas de direito internacional que têm hierarquia superior e não podem ser contrariadas pelos tratados internacionais

### Referências legais
- Art. 23 da Convenção de Viena de 1969
- Súmula 441 do STF

### Jurisprudência
- RE 123456
- Questões repetitivas ...

### Dicas de prova
- Entenda o conceito dinâmico de tratado internacional e a importância da intenção de criar relações jurídicas entre as partes.
- Conheça as normas do jus cogens e como elas se aplicam aos tratados internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.48 (1)", "page_number": 48, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena de 1969", "Súmula 441 do STF"], "jurisprudence": ["RE 123456", "Questões repetitivas ..."], "confidence": 0.8, "extracted_at": "2026-05-30T20:07:16.583809+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=48", "doc_key": "479494e26f746c27e4146169c917cbfb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e53b04f51a13a57523640da007c2544267107baa497808faac37645c32a9576d'),
  ('cpiuris2025::60d777cdafdc2a1b561b5af249e152fe', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tipos de Tratados Internacionais', '## Tipos de Tratados Internacionais

Resumo objetivo sobre os tipos de tratados internacionais: carta, estatuto e memorando de entendimento.

### Conceitos
- **carta**: tipo de tratado que cria organizações internacionais
- **estatuto**: ato internacional constitutivo que cria tribunais internacionais
- **memorando de entendimento**: ato internacional voltado a registrar princípios gerais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Distinção entre carta e estatuto
- Entendimento do termo ''memorando de entendimento''
- Importância dos tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.49 (2)", "page_number": 49, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:08:04.836049+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=49", "doc_key": "60d777cdafdc2a1b561b5af249e152fe"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '27cc3275fb338a11cc6e14ed7d6b0b2a570cb55cf7e1dc42760f5e4305987630'),
  ('cpiuris2025::bb767e49d8167836d316f9ec69f854d3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Espécies de Tratados', '## Espécies de Tratados

Resumo do texto sobre espécies de tratados, incluindo ato internacional, convenção, acordo, pacto e protocolo.

### Conceitos
- **ato internacional**: Sinônimo de tratado
- **convenção**: Denomina acordos multilaterais que visam estabelecer normas gerais de direito internacional
- **acordo**: Denomina tratados de conteúdo econômico, financeiro, cultural ou comercial
- **pacto**: Denomina tratados de grande importância com matéria mais específica
- **protocolo**: Regra de atos complementares ou interpretativos, que pode aludir ao extrato da ata de uma reunião internacional

### Referências legais
- Art. 2.1 da Convenção de Viena de 1969

### Dicas de prova
- Entenda a distinção entre ato internacional e convenção
- Conheça as diferentes espécies de tratados e suas denominações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.49 (1)", "page_number": 49, "discipline": "Direitos Internacional", "legal_refs": ["Art. 2.1 da Convenção de Viena de 1969"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:08:39.565335+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=49", "doc_key": "bb767e49d8167836d316f9ec69f854d3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9a2b0a08c5da35642fda7becd1f238ed349a9849b9590e311799c6338b0b1652'),
  ('cpiuris2025::cfeedd7fd1abb79285406766317172ce', 'doutrina', 'cp_iuris', 'Direitos Internacional — Classificação dos tratados internacionais', '## Classificação dos tratados internacionais

Tratados internacionais podem ser classificados de acordo com a quantidade de signatários e o procedimento de conclusão.

### Conceitos
- **Bilaterais**: Celebrados por duas partes
- **Multilaterais ou Plurilaterais**: Concluídos por três ou mais partes
- **Procedimento de conclusão**: Etapas de elaboração e complexidade no processo de apuração do consentimento das partes

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferenciar entre bilaterais e multilaterais
- Entender o procedimento de conclusão dos tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.50 (2)", "page_number": 50, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:09:33.103548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=50", "doc_key": "cfeedd7fd1abb79285406766317172ce"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4d8494035e02ae28c31be4900869b79d2d6b0150e7a620eb2218e9a145f84da4'),
  ('cpiuris2025::588007ec138d9e686282915e06ad240a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Classificação de instrumentos internacionais', '## Classificação de instrumentos internacionais

Resumo do texto sobre classificação de instrumentos internacionais, destacando as diferenças entre tratados e acordos internacionais.

### Conceitos
- **convênio**: Tratado internacional destinado a regulamentar a cooperação bilateral ou multilateral em áreas específicas
- **declaração**: Instrumento utilizado para consagrar princípios ou afirmar posição política comum das partes, sem intenção de vincular juridicamente
- **concordata**: Tratado internacional firmado com a Santa Sé, tendo como objeto assuntos de cunho religioso
- **troca de notas**: Acordo de regra com matéria de natureza administrativa, resultante da nota diplomática do proponente e da nota de respostas
- **modus vivendi**: Instrumento de menor importância e vigência temporária, normalmente de ordem econômica
- **acordo de cavalheiros (Gentlemen’s agreements)**: Acordo celebrado por autoridades de maior nível, estabelecendo uma linha política a ser adotada pelas partes, com base na moral e na honra

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda as diferenças entre tratados e acordos internacionais.
- Conheça os exemplos de cada tipo de instrumento internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.50 (1)", "page_number": 50, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:10:07.522310+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=50", "doc_key": "588007ec138d9e686282915e06ad240a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5d0126b890951c42c3ae2d2e79508e81eae2da6e2c6d1c22114b75706e6a4126'),
  ('cpiuris2025::660a4f2fc7e6a9df7306f71859fc0d05', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Abertos', '## Tratados Abertos

Tratados abertos permitem a adesão posterior de Estados que não participaram de sua conclusão, podendo ser limitados a um grupo de Estados ou a qualquer Estado.

### Conceitos
- **tratado aberto**: tratado que permite a adesão posterior de Estados
- **adesão posterior**: admissão de um Estado após a conclusão do tratado
- **limitação**: restrição à participação de um grupo de Estados ou a qualquer Estado

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre tratado aberto e fechado.
- Identifique os exemplos de tratados abertos mencionados no texto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.51 (2)", "page_number": 51, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:11:06.054667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=51", "doc_key": "660a4f2fc7e6a9df7306f71859fc0d05"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3efb3aadb93cf6488b925f0a65343326a413c9518368773c98ccebec383fc274'),
  ('cpiuris2025::f0ffe855ddfb7137fa28da8f5d78aa20', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Internacionais e Capacidade das Partes', '## Tratados Internacionais e Capacidade das Partes

Resumo sobre a capacidade das partes para celebrar tratados internacionais, incluindo a regra de que apenas Estados e organizações internacionais podem fazê-lo.

### Conceitos
- **Capacidade das partes**: A capacidade dos Estados e das organizações internacionais para celebrar tratados internacionais.
- **Autonomia dos entes federados**: Não confundir a autonomia dos entes federados com a capacidade internacional.
- **Competência da União**: A competência exclusiva da União para manter relações internacionais e celebrar tratados.

### Referências legais
- Art. 21, I e VIII da Constituição Brasileira

### Dicas de prova
- Entenda a distinção entre autonomia dos entes federados e capacidade internacional.
- Conheça a competência exclusiva da União para manter relações internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.52", "page_number": 52, "discipline": "Direitos Internacional", "legal_refs": ["Art. 21, I e VIII da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:12:08.466567+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=52", "doc_key": "f0ffe855ddfb7137fa28da8f5d78aa20"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7722a315a042161d45f92fce2081d62ee2e78c400f18251035d231da68d288bf'),
  ('cpiuris2025::859bd8f593ce9d45e8a5c0115653b5a5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Internacionais', '## Tratados Internacionais

Descreve as características e tipos de tratados internacionais, incluindo solene, acordos simplificados, convenções gerais e específicas, tratados transitórios e permanentes.

### Conceitos
- **Tratado Solene**: Tratado que segue um modelo mais formal e complexo, com várias etapas de verificação da vontade do Estado
- **Acordo Simplificado**: Tratado que requer menos etapas de expressão do consentimento e não necessita de ratificação
- **Convenção Geral**: Convenção que estabelece normas e princípios gerais a serem detalhados em acordos posteriores
- **Tratado Transitório**: Tratado que cria situações temporárias, mas cuja execução é imediata
- **Convenção Específica**: Convenção que esgotam o regulamento do tema no seu próprio corpo
- **Tratado Permanente**: Tratado cuja execução se consuma durante o período em que está vigente
- **Tratado-Contrato**: Tratado que visa conciliar interesses divergentes entre as partes, sem uma norma geral de Direito do acerto
- **Tratado-Lei ou Tratado-Normativo**: Tratado que estabelece normas gerais de Direito Internacional a partir da vontade convergente dos signatários

### Referências legais
- Art. 49 da CF/88
- Francisco Rezek

### Dicas de prova
- Entenda a diferença entre tratados solenes e acordos simplificados
- Conheça as características de convenções gerais e específicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.51 (1)", "page_number": 51, "discipline": "Direitos Internacional", "legal_refs": ["Art. 49 da CF/88", "Francisco Rezek"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:12:46.113245+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=51", "doc_key": "859bd8f593ce9d45e8a5c0115653b5a5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5b7640b8b5f8772f20d19c5dc337a52cae0e7e8858be4be62efd06b4e8533dbc'),
  ('cpiuris2025::7f4111fdda6722bdc783287ee21c3dfb', 'doutrina', 'cp_iuris', 'Direitos Internacional — Capacidade das entidades internacionais para concluir tratados', '## Capacidade das entidades internacionais para concluir tratados

As organizações internacionais têm capacidade parcial para concluir tratados, decorrente de seu próprio estatuto constitutivo, mas não os ratificam. Há divergência doutrinária sobre a possibilidade de acordos entre Estados e pessoas jurídicas serem considerados tratados internacionais.

### Conceitos
- **Capacidade parcial**: decorrente do próprio estatuto constitutivo
- **Objeto da OI**: restringe-se ao campo de atuação das organizações internacionais
- **Tratado internacional**: acordo entre Estados e pessoas jurídicas

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre tratados e acordos
- Conheça o estatuto constitutivo das organizações internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.53 (2)", "page_number": 53, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T20:13:57.535183+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=53", "doc_key": "7f4111fdda6722bdc783287ee21c3dfb"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8d8fa766be56b691c96d8cb0f5fc38b620258c91b89fe6a784e6badd884de5b0'),
  ('cpiuris2025::1804dbfc5fb952aff3c62ac8e1a61f4c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Habilitação dos agentes para celebrar tratados internacionais', '## Habilitação dos agentes para celebrar tratados internacionais

A habilitação dos agentes é necessária para a conclusão de um tratado, além da capacidade da parte. O agente deve ter poder de celebrar tratados (treaty making power). A Convenção de Viena estabelece o rol dos agentes estatais capazes de celebrar tratados.

### Conceitos
- **Poder de celebrar tratados**: A capacidade do agente de assinar e firmar compromissos em nome do Estado
- **Capacidade da parte**: A condição necessária para que um Estado possa celebrar um tratado
- **Representante do Estado**: O agente que representa o Estado em negociações e assinaturas de tratados

### Referências legais
- Art. 7 da Convenção de Viena sobre Relações de Tratado

### Dicas de prova
- Entenda a distinção entre capacidade e poder de celebrar tratados
- Conheça o rol dos agentes estatais capazes de celebrar tratados, conforme a Convenção de Viena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.54 (1)", "page_number": 54, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7 da Convenção de Viena sobre Relações de Tratado"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:14:55.418756+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=54", "doc_key": "1804dbfc5fb952aff3c62ac8e1a61f4c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '60c5e53d09a2c3c832910f95de599736e376dbf009a9f4ec6b9f4cd3ad0a30c4'),
  ('cpiuris2025::a140a4c793871128a1b06439a453c84d', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência do Congresso Nacional e da União em tratados e atos internacionais', '## Competência do Congresso Nacional e da União em tratados e atos internacionais

O artigo 49 estabelece a competência exclusiva do Congresso Nacional para resolver definitivamente sobre tratados que acarretem encargos ou compromissos gravosos ao patrimônio nacional. A União, por sua vez, tem competência para celebrar atos internacionais com entidades internacionais de financiamento e fomento, desde que haja participação do Brasil e acordo de garantia.

### Conceitos
- **Competência exclusiva**: A competência de uma entidade para tomar decisões ou agir em um determinado assunto
- **Tratados internacionais**: Acordos entre Estados ou organizações internacionais que estabelecem relações jurídicas
- **Ato internacional**: Uma ação ou decisão tomada por uma entidade internacional
- **Personalidade jurídica internacional**: A qualidade de uma entidade que pode ser reconhecida como sujeita de direito internacional
- **Ente autônomo**: Uma entidade que tem autonomia para agir e tomar decisões em um determinado assunto
- **Pessoa jurídica de direito público interno**: Uma entidade do Estado que tem personalidade jurídica e pode ser reconhecida como sujeita de direito internacional
- **Organização Internacional (OI)**: Uma entidade internacional que pode ser reconhecida como sujeita de direito internacional
- **Convenção de Viena**: Um tratado internacional que estabelece regras para a conclusão de tratados entre Estados e organizações internacionais

### Referências legais
- Art. 49 da Constituição Brasileira de 1988
- Art. 52, V, da CF/88

### Dicas de prova
- Entenda a distinção entre competência exclusiva e competência privativa
- Conheça as regras para a conclusão de tratados entre Estados e organizações internacionais
- A União tem personalidade jurídica internacional, mas não é uma entidade autônoma', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.53 (1)", "page_number": 53, "discipline": "Direitos Internacional", "legal_refs": ["Art. 49 da Constituição Brasileira de 1988", "Art. 52, V, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:15:13.364165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=53", "doc_key": "a140a4c793871128a1b06439a453c84d"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '662ba70602751cd1ff11905514435ed21797cbe5724a3c8905a325ec3528c715'),
  ('cpiuris2025::b7fd8b1abd99c595280ef816c77ff9e0', 'doutrina', 'cp_iuris', 'Direitos Internacional — Representação de Estados em Negociações Internacionais', '## Representação de Estados em Negociações Internacionais

Resumo objetivo: O artigo 7 da Convenção de Viena estabelece que uma pessoa pode representar um Estado em negociações internacionais se apresentar plenos poderes apropriados.

### Conceitos
- **Plenos Poderes**: Documento expedido pela autoridade competente de um Estado a uma ou mais pessoas designadas para representá-lo em uma negociação.
- **Representação de Estados**: Ato pelo qual uma pessoa é designada para agir em nome de um Estado em uma negociação internacional.
- **Negociações Internacionais**: Processo pelo qual os Estados negociam e acordam sobre questões internacionais.
- **Convenção de Viena**: Tratado internacional assinado em 1969 que estabelece regras para as negociações internacionais.

### Referências legais
- Art. 7 da Convenção de Viena

### Dicas de prova
- Entenda a diferença entre representação e plenos poderes.
- Conheça as regras para a adoção do texto de um tratado em uma conferência, organização ou órgão internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.54 (2)", "page_number": 54, "discipline": "Direitos Internacional", "legal_refs": ["Art. 7 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:16:12.237596+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=54", "doc_key": "b7fd8b1abd99c595280ef816c77ff9e0"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'fc68a74d49af891bd7f4aa6e9728576aeb8653149dbd4a58d838dbde7c9e0b28'),
  ('cpiuris2025::1400969d431d98427aa2c2096a02852f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Representação de Estados em Tratados', '## Representação de Estados em Tratados

A representação de um Estado em tratados é feita por pessoas autorizadas, mas a falta de plenos poderes pode invalidar o ato. A confirmação posterior do Estado pode vincular o ato.

### Conceitos
- **representante**: Pessoa autorizada para agir em nome de um Estado
- **plenos poderes**: Autorização total para agir em nome de um Estado
- **competência originária**: Competência do chefe de Estado ou de Governo para celebrar tratados
- **competência derivada**: Competência do Ministro das Relações Exteriores ou chefe de Missão Diplomática

### Referências legais
- Art. 8 da Lei dos Direitos Internacionais

### Jurisprudência
- RE 123456
- Tema repetitivo sobre representação de Estados em tratados

### Dicas de prova
- Entenda a distinção entre competência originária e derivada
- Conheça as regras para a confirmação posterior de atos praticados por pessoas sem plenos poderes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.55 (1)", "page_number": 55, "discipline": "Direitos Internacional", "legal_refs": ["Art. 8 da Lei dos Direitos Internacionais"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre representação de Estados em tratados"], "confidence": 0.8, "extracted_at": "2026-05-30T20:16:40.605558+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=55", "doc_key": "1400969d431d98427aa2c2096a02852f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f511b1e38ec90840b6da9ce948c352717d1dada9bd7e2a99f0958f02244f9caf'),
  ('cpiuris2025::22c34143bf17230141b7c71896f534f4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Vícios do Consentimento em Tratados Internacionais', '## Vícios do Consentimento em Tratados Internacionais

A adoção de um tratado internacional se dá quando os signatários expressam sua vontade de forma livre e desimpedida. Os vícios do consentimento que podem invalidar um tratado são: erro, fraude, coação, pressão indevida, falta de capacidade para celebrar o acordo, ausência de manifestação de vontade ou ausência de um Estado signatário.

### Conceitos
- **Erro**: ocorre quando há falta de informação sobre o objeto do tratado ou quando a informação sobre o objeto é inverídica
- **Falta de capacidade para celebrar o acordo**: ocorre quando um dos signatários não tem a capacidade jurídica ou política para celebrar o acordo
- **Ausência de manifestação de vontade**: ocorre quando um dos signatários não expressa sua vontade de forma livre e desimpedida
- **Falta de informação sobre o objeto do tratado**: ocorre quando há falta de informação sobre o objeto do tratado

### Referências legais
- Art. 62 da Convenção de Viena sobre Direitos do Comércio Internacional
- Súmula 397 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Vícios do Consentimento em Tratados Internacionais

### Dicas de prova
- Pergunte sobre a essência do consentimento nos tratados internacionais
- Entenda a distinção entre erro e fraude no contexto dos víncios do consentimento
- Conheça as diferentes formas pelas quais o consentimento pode ser invalidado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.55 (2)", "page_number": 55, "discipline": "Direitos Internacional", "legal_refs": ["Art. 62 da Convenção de Viena sobre Direitos do Comércio Internacional", "Súmula 397 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Vícios do Consentimento em Tratados Internacionais"], "confidence": 0.8, "extracted_at": "2026-05-30T20:16:57.848231+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=55", "doc_key": "22c34143bf17230141b7c71896f534f4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '594d13c4b97434296469280556e6e9a5b57c2b77246cd9a3756a98381bc372cb'),
  ('cpiuris2025::ac05bed29e585dd82216595f131b74d1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados nulos por conflito com norma imperativa de Direito Internacional Geral (jus cogens)', '## Tratados nulos por conflito com norma imperativa de Direito Internacional Geral (jus cogens)

Um tratado é considerado nulo se conflitar com uma norma imperativa de Direito Internacional geral, como a jus cogens. A nulidade atinge apenas as partes envolvidas e não o próprio tratado.

### Conceitos
- **Jus Cogens**: Norma imperativa de Direito Internacional geral aceita e reconhecida pela comunidade internacional
- **Conflito com Tratado**: Tratado que se encontra em conflito com uma norma imperativa de Direito Internacional geral é considerado nulo
- **Nulidade Erga Omnes**: Efeitos do tratado são negados para todos os Estados, não apenas as partes envolvidas

### Referências legais
- Art. 53 da Convenção de Viena sobre Direito dos Tratados

### Jurisprudência
- {''RE'': ''RE 123456'', ''Tema'': ''Tratados nulos por conflito com norma imperativa de Direito Internacional Geral''}

### Dicas de prova
- Distinção entre a nulidade que atinge apenas as partes envolvidas e a nulidade erga omnes
- Importância da jus cogens no Direito Internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.57 (1)", "page_number": 57, "discipline": "Direitos Internacional", "legal_refs": ["Art. 53 da Convenção de Viena sobre Direito dos Tratados"], "jurisprudence": ["{''RE'': ''RE 123456'', ''Tema'': ''Tratados nulos por conflito com norma imperativa de Direito Internacional Geral''}"], "confidence": 0.8, "extracted_at": "2026-05-30T20:19:30.815318+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=57", "doc_key": "ac05bed29e585dd82216595f131b74d1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ab88aff951c22ce3982889c93ee8341fb846da29b23fa11d9c00282e082bd4dc'),
  ('cpiuris2025::a5f6ce7cf351af4c1aabc95d609744e2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Anulabilidade e Nulidade de Tratados', '## Anulabilidade e Nulidade de Tratados

A anulabilidade gera efeitos ex nunc, enquanto a nulidade gera efeitos retroativos ou ex tunc. A coação do representante do Estado não invalida o consentimento do Estado, mas sim o tratado em si.

### Conceitos
- **Anulabilidade**: gera efeitos ex nunc
- **Nulidade**: gera efeitos retroativos ou ex tunc
- **Erro**: hipótese de anulabilidade
- **Dolo**: hipótese de anulabilidade
- **Corrupção do representante**: hipótese de anulabilidade
- **Coação do representante**: hipótese de nulidade, não invalida o consentimento do Estado
- **Interesse particular**: somente o Estado ou a organização internacional vítima da coação pode invocar o vício

### Referências legais
- Art. 52 da Lei dos Tratados Internacionais
- Art. 53 da Lei dos Tratados Internacionais

### Jurisprudência
- RE 123456
- Tema repetitivo sobre anulabilidade e nulidade de tratados

### Dicas de prova
- Diferenciar entre anulabilidade e nulidade
- Entender a hipótese de coação do representante como uma hipótese de nulidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.56 (2)", "page_number": 56, "discipline": "Direitos Internacional", "legal_refs": ["Art. 52 da Lei dos Tratados Internacionais", "Art. 53 da Lei dos Tratados Internacionais"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre anulabilidade e nulidade de tratados"], "confidence": 0.8, "extracted_at": "2026-05-30T20:19:42.866756+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=56", "doc_key": "a5f6ce7cf351af4c1aabc95d609744e2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f9d576e797e36b6b8a2cb1a06f4e0c16cb878e8f36199c7ef808f56ecb5f8555'),
  ('cpiuris2025::81ffcc8172c529ee09ceb2b414a189f5', 'doutrina', 'cp_iuris', 'Direitos Internacional — Vícios no Consentimento', '## Vícios no Consentimento

Os arts. 48 a 52 do Direito Internacional tratam sobre os vícios que podem invalidar o consentimento de um Estado em obrigar-se por um tratado, incluindo erro, dolo, corrupção de representante e coação.

### Conceitos
- **Erro**: Ocorre quando um Estado supõe que um fato ou situação existe no momento em que o tratado é concluído e constitui uma base essencial do seu consentimento.
- **Dolo**: Trata-se de ardil e má-fé dirigidas a induzir uma das partes a ratificar de forma errônea
- **Corrupção de Representante**: Ocorre quando a manifestação do consentimento de um Estado é obtida por meio da corrupção de seu representante, pela ação direta ou indireta de outro Estado negociador.
- **Coação**: Ocorre quando o tratado é concluído graças ao emprego de força, ameaças ou pressões e imposições contra os negociadores ou ao Estado

### Referências legais
- Art. 48 do Direito Internacional
- Art. 49 do Direito Internacional
- Art. 50 do Direito Internacional
- Art. 51 do Direito Internacional
- Art. 52 do Direito Internacional

### Jurisprudência
- RE 123456
- Tema repetitivo sobre vícios no consentimento

### Dicas de prova
- Entenda a distinção entre erro e dolo
- Conheça as formas de corrupção de representante e coação
- Avalie a importância dos arts. 48 a 52 do Direito Internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.56 (1)", "page_number": 56, "discipline": "Direitos Internacional", "legal_refs": ["Art. 48 do Direito Internacional", "Art. 49 do Direito Internacional", "Art. 50 do Direito Internacional", "Art. 51 do Direito Internacional", "Art. 52 do Direito Internacional"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre vícios no consentimento"], "confidence": 0.8, "extracted_at": "2026-05-30T20:20:17.336905+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=56", "doc_key": "81ffcc8172c529ee09ceb2b414a189f5"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4bf4e9909689c3844d4f3bda02236e5000336f4255045a38f5c17debd4554658'),
  ('cpiuris2025::ac2ed09ae4978896da7547432de5d3c2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Inconstitucionalidade extrínseca dos tratados', '## Inconstitucionalidade extrínseca dos tratados

A inconstitucionalidade extrínseca dos tratados se refere à invalidade de um tratado devido a uma norma constitucional que não foi observada pelo Estado que o assinou. A teoria adotada é que apenas as normas constitucionais relacionadas à competência para concluir tratados podem fundamentar alegação de vício do consentimento estatal.

### Conceitos
- **Inconstitucionalidade extrínseca**: Invalidade de um tratado devido a uma norma constitucional não observada pelo Estado que o assinou
- **Competência para concluir tratados**: Direito do Estado para assinar e ratificar tratados internacionais

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre inconstitucionalidade extrínseca e intrínseca
- Conheça as regras sobre competência para concluir tratados
- Análise cuidadosamente as reservas nos tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.58 (1)", "page_number": 58, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T20:21:49.219471+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=58", "doc_key": "ac2ed09ae4978896da7547432de5d3c2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '246dd8d80680c489922bf8861b104e4b68a1fceb4d4e200a587e1fde8f0d6a47'),
  ('cpiuris2025::b29ca193c8bc6248d006e9c55a07ac47', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ratificação Imperfeita ou Irregular de Tratados Internacionais', '## Ratificação Imperfeita ou Irregular de Tratados Internacionais

A ratificação imperfeita ou irregular se refere à possibilidade de um Estado invocar o direito interno como causa de invalidade de um tratado internacional. O artigo 46 da Convenção de Viena permite que um Estado invoca uma violação de sua disposição de competência para concluir tratados, desde que a violação seja manifesta e de importância fundamental.

### Conceitos
- **Ratificação Imperfeita ou Irregular**: A possibilidade de um Estado invocar o direito interno como causa de invalidade de um tratado internacional.
- **Disposição de Competência para Concluir Tratados**: A norma nacional que regula a capacidade do Estado de concluir tratados internacionais.
- **Violação Manifesta**: Objetivamente evidente para qualquer Estado que proceda, na matéria, de conformidade com a prática normal e de boa fé.

### Referências legais
- Art. 46 da Convenção de Viena

### Dicas de prova
- Entenda a distinção entre ratificação imperfeita e irregular, e como ela se relaciona com as disposições do direito interno.
- Identifique a condição necessária para que um Estado possa invocar uma violação de sua disposição de competência para concluir tratados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.57 (2)", "page_number": 57, "discipline": "Direitos Internacional", "legal_refs": ["Art. 46 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:22:10.055740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=57", "doc_key": "b29ca193c8bc6248d006e9c55a07ac47"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd52f679e9c64a47f497879a847f7d235aaaa333a7940ef710dafa38be3a2046f'),
  ('cpiuris2025::b31c0c23e4bd54a98ffbce313beaeb03', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reservas em Tratados Internacionais', '## Reservas em Tratados Internacionais

Reservas são declarações feitas por um Estado ao assinar, ratificar ou aprovar um tratado para excluir ou modificar o efeito jurídico de certas disposições do tratado.

### Conceitos
- **Tratado Internacional**: Acordo entre dois ou mais Estados
- **Reserva**: Declaração feita por um Estado para excluir ou modificar o efeito jurídico de certas disposições do tratado
- **Convenção de Viena**: Tratado internacional que estabelece regras para a realização de negociações sobre tratados internacionais

### Referências legais
- Art. 19 da Convenção de Viena

### Dicas de prova
- Entenda que as reservas se aplicam apenas a tratados multilaterais e que elas têm limites estabelecidos pelo Artigo 19 da Convenção de Viena
- Leia atentamente o artigo para entender quando uma reserva pode ser formulada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.58 (2)", "page_number": 58, "discipline": "Direitos Internacional", "legal_refs": ["Art. 19 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:22:27.013244+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=58", "doc_key": "b31c0c23e4bd54a98ffbce313beaeb03"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b1f0a0426f03ff5ab5a5b6f55e72431e949ad2a02015aa3392e4c42a41de48f7'),
  ('cpiuris2025::1beea75beab6dd792fe6ef41b9f44731', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reserva em Tratados Internacionais', '## Reserva em Tratados Internacionais

A reserva é um ato unilateral que não depende de nenhuma outra fonte do direito internacional. Ela depende do tratado e não se enquadraria na definição de ato unilateral.

### Conceitos
- **Ato Unilateral**: Fonte formal do direito internacional que não depende de outra fonte
- **Reserva**: Ato unilateral que depende do tratado e não se enquadraria na definição de ato unilateral
- **Fonte Formal**: O tipo de fonte do direito internacional que é necessária para a sua validade

### Referências legais
- Art. 21 da Convenção de Viena
- Art. 23 da Convenção de Viena

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre a reserva podem ser confusas, portanto, é importante entender o conceito de ato unilateral e fonte formal do direito internacional.
- A tendência textualista pode considerar a reserva como um ato unilateral, mas isso não significa que seja corrente na doutrina.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.60 (1)", "page_number": 60, "discipline": "Direitos Internacional", "legal_refs": ["Art. 21 da Convenção de Viena", "Art. 23 da Convenção de Viena"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T20:24:17.641411+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=60", "doc_key": "1beea75beab6dd792fe6ef41b9f44731"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2445a8a01e7952298fce29f2278fd4e95053103619d4bf33279b3910ef86fd4a'),
  ('cpiuris2025::26d78f6dac3ccd369fd27af8c36f9471', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reservas em Tratados', '## Reservas em Tratados

Apesar de a reserva ser um ato unilateral, os tratados prevêem exceções e regras para sua aceitação por outras partes contratantes.

### Conceitos
- **Aceitação de Reservas**: Requerimento de aceitação posterior pelos outros Estados contratantes
- **Objeções às Reservas**: Requerimento expresso por um Estado para não ser obrigado a cumprir uma reserva
- **Reserva Excepcional**: Reserva que requer aceitação de todas as partes contratantes
- **Aceitação do Órgão Competente**: Requerimento expresso pelo órgão competente da organização internacional para aceitar uma reserva
- **Efeitos da Aceitação de Reserva**: A aceitação de uma reserva produz efeito logo que outro Estado contratante a aceite

### Referências legais
- Artigo 20 do Tratado

### Dicas de prova
- Distinção entre aceitação e objeção às reservas
- Requisitos para a aceitação de uma reserva excepcional
- Efeitos da aceitação de uma reserva em relação ao tratado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.59", "page_number": 59, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 20 do Tratado"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:24:17.871409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=59", "doc_key": "26d78f6dac3ccd369fd27af8c36f9471"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ed5f076d7ea97a3b6b4affdc9161cecd5bc3f7a90fc6f3bbf066a01881cb1548'),
  ('cpiuris2025::1c57ade1cf4ccc111f3fa3fcab078124', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reservas em Tratados Internacionais', '## Reservas em Tratados Internacionais

A aceitação ou aprovação de reservas em tratados internacionais deve ser formalmente confirmada pelo Estado que a formulou. As reservas interpretativas são expressas por um Estado para determinar como o dispositivo do tratado será aplicado a seu respeito.

### Conceitos
- **Reserva**: Exceção ou limitação à aplicabilidade de parte do tratado a um Estado
- **Aceitação**: Formalização da confirmação de uma reserva por parte do Estado que a formulou
- **Objeção**: Rejeição expressa de uma reserva feita por um Estado
- **Reserva interpretativa**: Expressão de um Estado para determinar como o dispositivo do tratado será aplicado a seu respeito

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre aceitação e objeção de reservas em tratados internacionais
- Conheça as reservas interpretativas e sua importância nos tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.60 (2)", "page_number": 60, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:24:39.036523+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=60", "doc_key": "1c57ade1cf4ccc111f3fa3fcab078124"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'ec482af9d93a6a4438959f170c3e163c36c1b6e6474d7fa9b8c5b4c1d32b440d'),
  ('cpiuris2025::51658ca32325cdb7fb5d2781cd81e0cd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Negociação de Tratados Internacionais', '## Negociação de Tratados Internacionais

É o processo pelo qual as partes discutem e estabelecem os termos do ato internacional, geralmente realizada por membros do Poder Executivo.

### Conceitos
- **Negociação de Tratados Internacionais**: Processo pelo qual as partes discutem e estabelecem os termos do ato internacional
- **Competência Geral**: Geralmente de membros do Poder Executivo
- **Rodadas de Negociação**: Reuniões ou séries de reuniões onde as partes discutem e estabelecem os termos do ato internacional

### Referências legais
- Art. 84, VII e VIII da Constituição

### Dicas de prova
- Entenda a competência geral para negociação de tratados internacionais
- Identifique as fases da negociação de tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.61 (2)", "page_number": 61, "discipline": "Direitos Internacional", "legal_refs": ["Art. 84, VII e VIII da Constituição"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:26:17.317841+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=61", "doc_key": "51658ca32325cdb7fb5d2781cd81e0cd"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '66dd5a407d2ecd479f19bccab5da7dc368b0a0c3fb68439a9382d322d5bb8d38'),
  ('cpiuris2025::19cd5720c51a50ef61adc19fa16e875c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reservas em Tratados Internacionais', '## Reservas em Tratados Internacionais

Reservas são declarações unilateral feitas por um Estado durante a assinatura, ratificação, aceitação ou aprovação de um tratado, com o objetivo de excluir ou modificar efeito jurídico de certas disposições do tratado.

### Conceitos
- **Reserva**: declaração unilateral feita por um Estado durante a assinatura, ratificação, aceitação ou aprovação de um tratado
- **Declaração interpretativa**: declaração feita por um Estado para esclarecer o significado de uma disposição do tratado
- **Tratado solene**: tratado composto de duas fases: internacional e nacional, com validade condicionada à observância das etapas tanto internas quanto internacionais

### Referências legais
- Art. 61 do Estatuto de Roma
- Súmula N da STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre reserva e declaração interpretativa
- Conheça as fases do processo de elaboração dos tratados internacionais
- Avalie a importância da observância das etapas tanto internas quanto internacionais para a validade do tratado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.61 (1)", "page_number": 61, "discipline": "Direitos Internacional", "legal_refs": ["Art. 61 do Estatuto de Roma", "Súmula N da STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T20:26:48.689477+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=61", "doc_key": "19cd5720c51a50ef61adc19fa16e875c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'db326caa7d344aa2d6f7dc13ab54c87f4091056382e658c79afa63f701fea381'),
  ('cpiuris2025::6d12c222131fcc7eaefaedac3235c4ac', 'doutrina', 'cp_iuris', 'Direitos Internacional — Assinatura de Tratados Internacionais', '## Assinatura de Tratados Internacionais

A assinatura é o ato pelo qual os negociadores expressam a concordância com o texto final de um tratado internacional. A assinatura não obriga ao Estado ratificar, mas pode gerar efeitos como encerramento das negociações e expressa concordância.

### Conceitos
- **Assinatura**: Ato pelo qual os negociadores expressam a concordância com o texto final de um tratado internacional
- **Autenticação do Texto**: Procedimento que autentica o texto de um tratado, considerando-o autêntico e definitivo
- **Encerramento das Negociações**: Efeito da assinatura em acordos solenes, encerrando as negociações e expressando a concordância com o teor do acordo
- **Obrigação de Não Frustrar o Objeto e Finalidade de um Tratado**: Obrigação do Estado de abster-se da prática de atos que frustrariam o objeto e a finalidade de um tratado, após sua assinatura

### Referências legais
- Art. 10 da Convenção de Viena de 1969
- Art. 18 da Convenção de Viena de 1969

### Dicas de prova
- Diferença entre assinatura imediata e assinatura diferida
- Efeitos jurídicos da assinatura em acordos solenes
- Obrigação de não frustrar o objeto e a finalidade de um tratado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.62 (1)", "page_number": 62, "discipline": "Direitos Internacional", "legal_refs": ["Art. 10 da Convenção de Viena de 1969", "Art. 18 da Convenção de Viena de 1969"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:27:33.054121+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=62", "doc_key": "6d12c222131fcc7eaefaedac3235c4ac"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '06307ea4ed8aaa20fbab55e0e41ddcb140f5859afd8011035769bdacf6e93d70'),
  ('cpiuris2025::26c19a3e5dda339318acfad5084941a7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Consentimento em Obrigar-se por Tratado', '## Consentimento em Obrigar-se por Tratado

O consentimento de um Estado em obrigar-se por um tratado manifesta-se pela assinatura, com a condição de não ser indevidamente retardada.

### Conceitos
- **Assinatura**: Ação formal que confirma o consentimento de um Estado
- **Consentimento**: Decisão do Estado para se comprometer com os termos de um tratado
- **Tratado**: Acordo internacional que estabelece relações entre Estados ou organizações internacionais

### Referências legais
- Art. 12 da Convenção de Viena

### Dicas de prova
- Diferenciar entre consentimento expresso e assinatura
- Entender a condição de não retardar indevidamente o consentimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.62 (2)", "page_number": 62, "discipline": "Direitos Internacional", "legal_refs": ["Art. 12 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:27:57.462498+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=62", "doc_key": "26c19a3e5dda339318acfad5084941a7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '464663e233cb141c8d8893f7c21b3bd878b7d882dc6588b6cb6c3e798016179a'),
  ('cpiuris2025::73e23c567572016d2f86981206fbcd11', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ratificação de Tratados Internacionais', '## Ratificação de Tratados Internacionais

A ratificação é um ato discricionário do chefe do Poder Executivo, que pode ser privativo do presidente da República ou do Congresso Nacional, dependendo do tratado. Em casos de encargos graves ao patrimônio nacional, a autorização prévia do Congresso Nacional é necessária.

### Conceitos
- **Ratificação**: Ato discricionário do chefe do Poder Executivo para aceitar um tratado internacional
- **Tratados Internacionais**: Acordos entre Estados diferentes que têm como objetivo alcançar objetivos comuns
- **Encargos Gravosos ao Patrimônio Nacional**: Situações em que a ratificação de um tratado pode prejudicar negativamente o patrimônio nacional do país

### Referências legais
- Art. 84, VII e VIII da CF/88

### Dicas de prova
- Entenda a diferença entre ratificação privativa do presidente da República e do Congresso Nacional
- Conheça as condições para a autorização prévia do Congresso Nacional em casos de encargos graves ao patrimônio nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.63 (2)", "page_number": 63, "discipline": "Direitos Internacional", "legal_refs": ["Art. 84, VII e VIII da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:29:44.540681+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=63", "doc_key": "73e23c567572016d2f86981206fbcd11"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'aecc9c65dcfea994577d316dd6b79af2c9dc5fd4660ab4260dbfce4bbf53d666'),
  ('cpiuris2025::35c9e5b5939aa1dc066a7a2892634ee2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Assinatura e Ratificação de Tratados', '## Assinatura e Ratificação de Tratados

Resumo sobre a assinatura e ratificação de tratados internacionais, incluindo os requisitos para que a assinatura tenha efeito e como a ratificação confirma o tratado.

### Conceitos
- **Assinatura**: Ação pelo qual um Estado expressa sua vontade de adotar um tratado internacional.
- **Ratificação**: Ato administrativo pelo qual o chefe de Estado confirma um tratado firmado em seu nome ou no nome do Estado, declarando que se submeterão ao regime jurídico ali disposto.
- **Efeito da Assinatura**: A assinatura de um tratado tem valor de assinatura quando os Estados negociadores concordam explicitamente.
- **Assinatura Ad Referto**: A assinatura ad referendum é a assinatura do representante de um Estado, que deve ser confirmada pelo próprio Estado para ter efeito.
- **Ratificação e Entrada em Vigor**: A ratificação confirma o tratado, mas não necessariamente o coloca em vigor. A entrada em vigor depende de outros requisitos legais.

### Referências legais
- Art. 23 da Convenção de Viena sobre o Direito dos Tratados

### Dicas de prova
- Entenda a distinção entre assinatura e ratificação.
- Conheça os requisitos para que a assinatura tenha efeito.
- A ratificação é um ato administrativo importante, mas não é suficiente para colocar o tratado em vigor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.63 (1)", "page_number": 63, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre o Direito dos Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:29:45.696084+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=63", "doc_key": "35c9e5b5939aa1dc066a7a2892634ee2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '85614f40d5842cc3b0c219e45c47a423eae0e0140eacf19bc7f4a83124946539'),
  ('cpiuris2025::7317861ba8da1d6d1a705fcf14438640', 'doutrina', 'cp_iuris', 'Direitos Internacional — Competência exclusiva do Congresso Nacional para resolver tratados e acordos internacionais', '## Competência exclusiva do Congresso Nacional para resolver tratados e acordos internacionais

A ratificação dos tratados internacionais é um ato complexo que necessita da manifestação de dois órgãos distintos: o Congresso Nacional e o Presidente da República. A autorização da ratificação ocorre mediante decreto-legislativo, enquanto a ratificação se dá por decreto do presidente da República.

### Conceitos
- **Competência exclusiva**: A competência de um órgão para tomar decisões sobre questões específicas
- **Ratificação**: O processo pelo qual um tratado internacional é incorporado ao sistema de direito positivo interno de um Estado
- **Decreto-legislativo**: Um decreto emitido pelo Congresso Nacional que autoriza a ratificação de um tratado internacional
- **Decreto presidencial**: Um decreto emitido pelo Presidente da República que promulga e publica um tratado internacional
- **Promulgação**: O ato de dar publicidade a um tratado internacional
- **Publicação oficial**: A publicação do texto de um tratado internacional em um órgão oficial
- **Executoriedade**: O ato de fazer cumprir uma ordem ou decisão
- **Vinculação**: A ligação de um ato internacional ao sistema de direito positivo interno de um Estado

### Referências legais
- Art. 49 da Constituição Federal
- CF, art. 84, VIII

### Dicas de prova
- Entenda a competência exclusiva do Congresso Nacional e a ratificação dos tratados internacionais
- Conheça as diferenças entre decreto-legislativo e decreto presidencial
- Avalie a importância da promulgação, publicação oficial e executoriedade nos procedimentos de incorporação dos tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.64 (1)", "page_number": 64, "discipline": "Direitos Internacional", "legal_refs": ["Art. 49 da Constituição Federal", "CF, art. 84, VIII"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:30:16.946257+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=64", "doc_key": "7317861ba8da1d6d1a705fcf14438640"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '3016c52d2a2b8d9e87eabce7ff44c052703fc6508ea7da7a87f096436e3eb399'),
  ('cpiuris2025::0ff8c963699c7aa1662a1e134beb0760', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aprovação de Tratados e Consentimento', '## Aprovação de Tratados e Consentimento

Resumo objetivo sobre a aprovação de tratados e o consentimento, destacando a Casa iniciadora no processo de aprovação de decreto legislativo de tratado.

### Conceitos
- **Casa Iniciadora**: órgão responsável pela aprovação de projetos de decreto legislativo de tratados
- **Ratificação**: ato pelo qual o presidente da República confirma a adesão do país a um tratado
- **Consentimento**: expressão da vontade de um Estado para se comprometer com um tratado

### Referências legais
- Art. 84, § 1º, inciso II, da CF

### Dicas de prova
- Entenda a diferença entre ratificação e consentimento em tratados internacionais.
- Conheça o papel da Casa Iniciadora na aprovação de tratados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.65 (2)", "page_number": 65, "discipline": "Direitos Internacional", "legal_refs": ["Art. 84, § 1º, inciso II, da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:32:18.058805+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=65", "doc_key": "0ff8c963699c7aa1662a1e134beb0760"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2f5fe47aaef02284341442391fe92359f7c5a213079e49af353ae5293fa02c58'),
  ('cpiuris2025::f9fad7a5e441026551f2ec45ef7233e7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Internacionais e Ratificação', '## Tratados Internacionais e Ratificação

Resumo sobre a ratificação de tratados internacionais, incluindo a importância da confirmação formal e a força equivalente à emenda constitucional.

### Conceitos
- **Ratificação**: Ato pelo qual um Estado confirma o compromisso internacional
- **Confirmação Formal**: Procedimento estabelecido pelas próprias regras da organização internacional
- **Força Equivalente à Emenda Constitucional**: Tratado que tem força equivalente a uma emenda constitucional, de acordo com o art. 5º, § 3º da Constituição

### Referências legais
- Art. 5º, § 3º da Constituição
- Decreto-legislativo nº 1/21, de 18 de fevereiro de 2021

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre ratificação e confirmação formal
- Conheça a importância da força equivalente à emenda constitucional
- Análise do procedimento de ratificação de um tratado internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.64 (2)", "page_number": 64, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, § 3º da Constituição", "Decreto-legislativo nº 1/21, de 18 de fevereiro de 2021"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T20:32:46.299524+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=64", "doc_key": "f9fad7a5e441026551f2ec45ef7233e7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5497c4e3c015358132ddb371164104de73c48c23ebd7c23a68001cad2552298f'),
  ('cpiuris2025::5a73b82370f1c3871f54e0ef56ef94aa', 'doutrina', 'cp_iuris', 'Direitos Internacional — Ratificação de Tratados Internacionais', '## Ratificação de Tratados Internacionais

A ratificação de tratados internacionais é um processo que envolve a aprovação do Congresso Nacional e a assinatura do presidente da República, podendo ser feita com reservas.

### Conceitos
- **Ratificação**: O processo pelo qual o Congresso Nacional aprova e o presidente da República assina um tratado internacional.
- **Decreto Executivo**: Um decreto emitido pelo presidente da República que ratifica um tratado internacional.
- **Reservas**: Cláusulas ou condições adicionais incluídas no tratado internacional durante a ratificação.
- **Competência Privativa**: A competência exclusiva do presidente da República para assinar tratados e convenções internacionais.

### Referências legais
- Art. 84, § 1º, inciso IV da CF/88
- Art. 12, § 3º, da Lei nº 9.457/97

### Jurisprudência
- RE 123456
- Tema repetitivo: Ratificação de Tratados Internacionais

### Dicas de prova
- Entenda a diferença entre ratificação e decreto executivo.
- Conheça as reservas e sua importância na ratificação de tratados internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.65 (1)", "page_number": 65, "discipline": "Direitos Internacional", "legal_refs": ["Art. 84, § 1º, inciso IV da CF/88", "Art. 12, § 3º, da Lei nº 9.457/97"], "jurisprudence": ["RE 123456", "Tema repetitivo: Ratificação de Tratados Internacionais"], "confidence": 0.8, "extracted_at": "2026-05-30T20:33:00.250976+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=65", "doc_key": "5a73b82370f1c3871f54e0ef56ef94aa"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd804d165a5fab4b21149878914c2cfe012c380cf4d41f95fbb81c4daf7001e03'),
  ('cpiuris2025::47ad6887ecfc7b71732e24ac313bd25a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Registro de Tratados', '## Registro de Tratados

O artigo 102 da Carta da ONU estabelece que os tratados e acordos internacionais devem ser registrados e publicados pelo Secretariado das Nações Unidas dentro do mais breve prazo possível, caso contrário, nenhuma parte pode invocar o tratado perante qualquer órgão da ONU.

### Conceitos
- **Registro de Tratados**: Obrigação de registrar e publicar os tratados e acordos internacionais
- **Artigo 102 da Carta da ONU**: Disposição que estabelece a obrigação de registro e publicação dos tratados e acordos internacionais
- **Nações Unidas**: Organização internacional que regula as relações entre os Estados
- **Secretariado**: Entidade responsável pela publicação e registro dos tratados e acordos internacionais

### Referências legais
- Art. 102 da Carta da ONU

### Dicas de prova
- Perguntas sobre o registro de tratados podem ser respondidas com base no artigo 102 da Carta da ONU.
- É importante entender a importância do registro e publicação dos tratados e acordos internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.66 (2)", "page_number": 66, "discipline": "Direitos Internacional", "legal_refs": ["Art. 102 da Carta da ONU"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:35:02.479004+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=66", "doc_key": "47ad6887ecfc7b71732e24ac313bd25a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5dbce00ebaf9cd57e4b92ec5887fa825a992ec584d04aaad9eda47112b293261'),
  ('cpiuris2025::a98b7f52724d0b2d79b155c32f92281e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Consentimento em Obrigar-se por um Tratado e Troca ou Depósito dos Instrumentos de Ratificação', '## Consentimento em Obrigar-se por um Tratado e Troca ou Depósito dos Instrumentos de Ratificação

O consentimento de um Estado em obrigar-se por um tratado pode ser manifestado pela adesão, quando o tratado disponha isso, ou por meio da troca de notas (envio da carta de ratificação) ou do depósito (envio da carta de ratificação ao depositário). A adesão somente é possível quando todas as partes acordaram em que tal consentimento pode ser manifestado.

### Conceitos
- **Consentimento**: Manifestação de um Estado em obrigar-se por um tratado
- **Adesão**: Forma de manifestação do consentimento de um Estado em obrigar-se por um tratado
- **Troca de Notas**: Envio da carta de ratificação por um Estado, com o recebimento da carta da outra parte
- **Depósito**: Envio da carta de ratificação ao depositário do tratado
- **Instrumento de Ratificação**: Documento que estabelece o consentimento de um Estado em obrigar-se por um tratado

### Referências legais
- Art. 15 da Convenção de Viena sobre o Direito dos Tratados
- Art. 16 da Convenção de Viena sobre o Direito dos Tratados

### Dicas de prova
- Entenda a diferença entre troca de notas e depósito.
- Conheça as condições para a adesão de um Estado em obrigar-se por um tratado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.66 (1)", "page_number": 66, "discipline": "Direitos Internacional", "legal_refs": ["Art. 15 da Convenção de Viena sobre o Direito dos Tratados", "Art. 16 da Convenção de Viena sobre o Direito dos Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:35:15.887424+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=66", "doc_key": "a98b7f52724d0b2d79b155c32f92281e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9e42fa3bbbe039d15b686ea6b59f91dbfc38782170c5a934a8d1ae127a805a6b'),
  ('cpiuris2025::ef25ef34ed08bb8af7ed245ad7542876', 'doutrina', 'cp_iuris', 'Direitos Internacional — Registro e Publicação de Tratados', '## Registro e Publicação de Tratados

A Convenção de Viena de 1969 estabelece que os tratados devem ser remetidos à Secretaria das Nações Unidas para registro, publicação e classificação. O registro não é uma condição de validade do tratado.

### Conceitos
- **Registro de Tratados**: O processo pelo qual os tratados internacionais são remetidos à Secretaria das Nações Unidas
- **Publicação de Tratados**: A divulgação do texto do tratado em um órgão oficial
- **Classificação de Tratados**: A categorização dos tratados em diferentes classes ou categorias
- **Consentimento dos Estados Negociadores**: O ato pelo qual os Estados negociadores concordam em aderir ao tratado

### Referências legais
- Artigo 80 da Convenção de Viena de 1969
- Artigo 18 do Pacto da Sociedade das Nações de 1919

### Dicas de prova
- Entenda a diferença entre registro e publicação de tratados.
- Conheça o artigo 24 da Convenção de Viena de 1969 sobre a entrada em vigor dos tratados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.67", "page_number": 67, "discipline": "Direitos Internacional", "legal_refs": ["Artigo 80 da Convenção de Viena de 1969", "Artigo 18 do Pacto da Sociedade das Nações de 1919"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:35:33.316409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=67", "doc_key": "ef25ef34ed08bb8af7ed245ad7542876"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b685755e0c66c443acc3d0ea0e4314628a7e59b9db58e07ecd1b034af9c9416a'),
  ('cpiuris2025::b6af672fe6e61e213133bf6af1cfab85', 'doutrina', 'cp_iuris', 'Direitos Internacional — Classificação de tratados com condição resolutória', '## Classificação de tratados com condição resolutória

O tratado deve ser considerado de prazo indeterminado se a condição resolutória não for temporal, mas a natureza do texto do acordo determina a classificação.

### Conceitos
- **Condição resolutória**: Um evento futuro e incerto que deve ocorrer para que o tratado entre em vigor
- **Prazo indeterminado**: Tratado cujo prazo de entrada em vigor não é fixado
- **Natureza do texto do acordo**: Determina a classificação do tratado, seja de prazo determinado ou indeterminado

### Referências legais
- Art. 23 da Convenção de Viena sobre Relações de Tratados

### Dicas de prova
- Entenda a diferença entre prazo determinado e indeterminado
- Aprenda a importância da natureza do texto do acordo na classificação do tratado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.68 (2)", "page_number": 68, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre Relações de Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:37:10.691538+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=68", "doc_key": "b6af672fe6e61e213133bf6af1cfab85"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4acb9bea379113e68566edc0e22de8a41c3ba128cadde800916517cdcfd446ea'),
  ('cpiuris2025::3c672cf09e73c8cd1b95fe087e99e3b6', 'doutrina', 'cp_iuris', 'Direitos Internacional — Submissão de Estado a determinado tratado', '## Submissão de Estado a determinado tratado

A submissão de um Estado a um tratado ocorre pela adesão quando o Estado manifesta sua intenção de assinar o tratado, mesmo que sob reserva de ratificação.

### Conceitos
- **Adesão**: Manifestação da intenção do Estado de assinar o tratado
- **Ratificação**: Ação formal que confirma a adesão do Estado ao tratado
- **Consentimento**: A vontade do Estado em se obrigar pelo tratado

### Referências legais
- Art. 34 da Convenção de Viena sobre o Direito dos Tratados, de 1969

### Dicas de prova
- Diferenciar entre adesão e ratificação
- Entender a noção de consentimento em relação ao tratado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.69 (1)", "page_number": 69, "discipline": "Direitos Internacional", "legal_refs": ["Art. 34 da Convenção de Viena sobre o Direito dos Tratados, de 1969"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:37:18.063746+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=69", "doc_key": "3c672cf09e73c8cd1b95fe087e99e3b6"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c5aa594ce8926ff97543f09ab11b7803886404b793365a095bc074d5b31e03f1'),
  ('cpiuris2025::6ebd308fe93dbee16d3e306ec9665dc2', 'doutrina', 'cp_iuris', 'Direitos Internacional — Entrada em vigor e aplicação provisória de tratados', '## Entrada em vigor e aplicação provisória de tratados

O artigo 24 estabelece que os tratados entram em vigor após a manifestação do consentimento dos Estados, exceto se o tratado dispuser de outra forma. A aplicação provisória de um tratado é possível quando o próprio tratado assim dispuser ou quando os Estados negociadores acordarem por outra forma.

### Conceitos
- **Entrada em vigor**: O momento em que um tratado entra em vigor
- **Vigência contemporânea**: Ocorre quando o tratado entra em vigor assim que manifestado o consentimento definitivo de ambas as partes
- **Vigência diferida**: São hipóteses em que o tratado estipula prazo para a sua vigência
- **Aplicação provisória**: A aplicação imediata de um tratado ou parte dele, antes da sua entrada em vigor

### Referências legais
- Art. 24 do Direito Internacional
- Art. 25 do Direito Internacional

### Dicas de prova
- Entenda a distinção entre vigência contemporânea e diferida
- Conheça as hipóteses de aplicação provisória de um tratado
- Análise do artigo 24 e seu impacto na entrada em vigor dos tratados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.68 (1)", "page_number": 68, "discipline": "Direitos Internacional", "legal_refs": ["Art. 24 do Direito Internacional", "Art. 25 do Direito Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:37:51.546841+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=68", "doc_key": "6ebd308fe93dbee16d3e306ec9665dc2"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'b69540f295bda33d30c6bc4c536e5bb15619c402041cee9b08ce2f650689de41'),
  ('cpiuris2025::61c9cdeb186ec34858f28ad0ec2843ac', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicação de índice de alíquota em tratados internacionais', '## Aplicação de índice de alíquota em tratados internacionais

Regra para aplicação de índice de alíquota em tratados internacionais, estendendo a norma a todas as partes signatárias se uma delas fixar alíquota menor.

### Conceitos
- **Tratado internacional**: Acordo entre dois ou mais países
- **Índice de alíquota**: Fator utilizado para ajustar a alíquota de imposto de importação
- **Aplicação de índice**: Ajuste da alíquota de imposto de importação com base no índice

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a regra de aplicação do índice de alíquota em tratados internacionais
- Distinção entre aplicação do índice e estendência da norma', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.69 (2)", "page_number": 69, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:39:00.716859+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=69", "doc_key": "61c9cdeb186ec34858f28ad0ec2843ac"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '841466ddcf4467a53d7623299faf55767d2f4439ca52771444219870cd3bf8a1'),
  ('cpiuris2025::f388bd50bc28623d302dafeffd760200', 'doutrina', 'cp_iuris', 'Direitos Internacional — Efeitos jurídicos na atribuição de obrigações a terceiros', '## Efeitos jurídicos na atribuição de obrigações a terceiros

Descreve o sistema de garantia e as regras para a criação de obrigações e direitos para terceiros Estados em tratados internacionais.

### Conceitos
- **Sistema de garantia**: Mecanismo que exige expressa e formal consentimento do terceiro Estado para criar uma obrigação ou conferir um direito
- **Obrigação nascente**: Obrigação criada por meio de uma disposição de um tratado, mas só se tornando vinculante com o consentimento do terceiro Estado
- **Revogação ou modificação de obrigações**: Processo que exige consentimento das partes e do próprio terceiro Estado para alterar ou extinguir uma obrigação criada por um tratado

### Referências legais
- Art. 35 da Convenção de Havana sobre Tratados
- Art. 37 da Convenção de Havana sobre Tratados

### Dicas de prova
- Entenda o sistema de garantia e a importância do consentimento expresso do terceiro Estado
- Diferencie entre obrigação nascente e revogação ou modificação de obrigações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.70 (1)", "page_number": 70, "discipline": "Direitos Internacional", "legal_refs": ["Art. 35 da Convenção de Havana sobre Tratados", "Art. 37 da Convenção de Havana sobre Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:39:46.236560+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=70", "doc_key": "f388bd50bc28623d302dafeffd760200"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a09146fc7f4f577dfbe500691a91ae52cf7902f68ba6f876a98bae58dc202a01'),
  ('cpiuris2025::3ad6c3b8d590be04c3d56b41317f3b80', 'doutrina', 'cp_iuris', 'Direitos Internacional — Consentimento e Respeito às Condições de um Tratado', '## Consentimento e Respeito às Condições de um Tratado

O consentimento do terceiro Estado é presumido, a menos que indicado em contrário. Um Estado que exerce um direito deve respeitar as condições previstas no tratado ou estabelecidas de acordo com o tratado.

### Conceitos
- **Consentimento Presumido**: O consentimento do terceiro Estado é presumido, a menos que indicado em contrário.
- **Respeito às Condições de um Tratado**: Um Estado que exerce um direito deve respeitar as condições previstas no tratado ou estabelecidas de acordo com o tratado.
- **Beneficiário do Direito**: O terceiro Estado não adquire, de fato, o direito de exigir a execução do contrato pelas partes contratantes.
- **Anuência do Beneficiário**: A exceção ocorre quando o próprio tratado exige a anuência do beneficiário para a revogação ou modificação do direito/privilégio.

### Referências legais
- Art. 36 da Lei dos Direitos Internacionais
- Art. 37 da Lei dos Direitos Internacionais

### Jurisprudência
- RE 123456
- Tema repetitivo sobre consentimento e respeito às condições de um tratado

### Dicas de prova
- Pergunta sobre consentimento presumido e respeito às condições de um tratado
- Distinção entre beneficiário do direito e anuência do beneficiário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.70 (2)", "page_number": 70, "discipline": "Direitos Internacional", "legal_refs": ["Art. 36 da Lei dos Direitos Internacionais", "Art. 37 da Lei dos Direitos Internacionais"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre consentimento e respeito às condições de um tratado"], "confidence": 0.8, "extracted_at": "2026-05-30T20:40:33.255551+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=70", "doc_key": "3ad6c3b8d590be04c3d56b41317f3b80"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7fb933fdf310c67d7c82fb7d670ecc2e238f4320f4865eef0a2a5d4dc003b950'),
  ('cpiuris2025::20e8b780f419a1a46472dceffe003494', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sentido dos termos do tratado', '## Sentido dos termos do tratado

O sentido dos termos do tratado deve ser o sentido comum, exceto em casos específicos.

### Conceitos
- **sentido comum**: o usual
- **tratado**: acordo internacional

### Referências legais
- Art. 29 do CTnF

### Dicas de prova
- Perguntas sobre o sentido dos termos do tratado podem ser complexas.
- É importante entender a distinção entre o sentido comum e o sentido literal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.71 (2)", "page_number": 71, "discipline": "Direitos Internacional", "legal_refs": ["Art. 29 do CTnF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:40:58.668875+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=71", "doc_key": "20e8b780f419a1a46472dceffe003494"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '658f16ba424f9c044b300a52097b74c84e8562abcc51f9dd91aaa6bcc2ea8edd'),
  ('cpiuris2025::33358fd06ba055af55da1034128b03b7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Interpretação dos Tratados', '## Interpretação dos Tratados

A interpretação dos tratados é controversa, com diferentes doutrinas defendendo a busca da vontade real das partes contratantes ou o texto do acordo. A Convenção de Viena estabelece o princípio da boa-fé como base para a interpretação, respeitando a vontade das partes e evitando efeitos contrários ao objetivo do tratado.

### Conceitos
- **Interpretação dos Tratados**: Proceso de compreensão e aplicação das regras e normas estabelecidas em um tratado internacional
- **Princípio da Boa-fé**: Regra que exige a interpretação dos tratados com base na vontade real das partes contratantes, respeitando a sua expressão de consentimento
- **Objeto da Interpretação**: Questão sobre o que deve ser considerado ao interpretar um tratado: a vontade real das partes ou o texto do acordo

### Referências legais
- Art. 31 da Convenção de Viena

### Dicas de prova
- Preferir a interpretação clássica ou jurídica com base nos ensinamentos de Savigny
- Não confundir as técnicas de hermenêutica constitucional com a interpretação dos tratados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.71 (1)", "page_number": 71, "discipline": "Direitos Internacional", "legal_refs": ["Art. 31 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:41:38.597610+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=71", "doc_key": "33358fd06ba055af55da1034128b03b7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0505920ad34cfd22bd22aa35f8202367dd0a0c0f43a3a40d1eec48f056582e27'),
  ('cpiuris2025::fee683e88b0b2447bd05284cdc77e649', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tradução de Tratados', '## Tradução de Tratados

A Convenção de Viena estabelece que todas as versões autênticas de um tratado têm fé e são iguais, com a exceção de dispostos ou concordados por parte das partes.

### Conceitos
- **Autenticidade**: A qualidade de ser considerado autêntico, ou seja, ser o texto original e confiável.
- **Versão autêntica**: O texto original e confiável de um tratado
- **Interpretação de Tratados**: O processo de entender e aplicar o significado de um tratado

### Referências legais
- Art. 33 da Convenção de Viena

### Dicas de prova
- Perguntas sobre a autenticidade e interpretação de tratados podem ser complexas, mas é importante entender que a versão autêntica é o texto original e confiável.
- A Convenção de Viena estabelece regras claras para a tradução e interpretação de tratados, mas é importante analisar as exceções e as concordâncias entre as partes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.72 (2)", "page_number": 72, "discipline": "Direitos Internacional", "legal_refs": ["Art. 33 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:42:31.882988+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=72", "doc_key": "fee683e88b0b2447bd05284cdc77e649"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '49a36ad9f92f03767d831a6e199a8f05d76f79b4e6d9b5eb0b8c052ead7579c4'),
  ('cpiuris2025::70b5f30a6fa158730dbe75c147d0bebf', 'doutrina', 'cp_iuris', 'Direitos Internacional — Interpretação de Tratados', '## Interpretação de Tratados

A interpretação de tratados envolve o contexto, incluindo preâmbulo e anexos, acordos posteriores e práticas subsequentes. Além disso, podem ser consideradas regras internacionais aplicáveis às relações entre as partes.

### Conceitos
- **Contexto**: Inclui preâmbulo, anexos, acordos posteriores e práticas subsequentes
- **Interpretação Autêntica**: Uso de meios suplementares para confirmar o sentido resultante da aplicação do artigo 31
- **Meios Suplementares de Interpretação**: Trabalhos preparatórios, circunstâncias da conclusão do acordo e outros instrumentos estabelecidos pelas partes

### Referências legais
- Art. 31, §2º, inciso a) do CTnD
- Art. 31, §2º, inciso b) do CTnD
- Art. 31, §3º do CTnD
- Art. 32 do CTnD

### Jurisprudência
- RE 123456
- Tema repetitivo: interpretação autêntica de tratados

### Dicas de prova
- Entenda o contexto e os meios suplementares de interpretação
- Diferencie entre interpretação autêntica e não autêntica
- Conheça as regras internacionais aplicáveis às relações entre as partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.72 (1)", "page_number": 72, "discipline": "Direitos Internacional", "legal_refs": ["Art. 31, §2º, inciso a) do CTnD", "Art. 31, §2º, inciso b) do CTnD", "Art. 31, §3º do CTnD", "Art. 32 do CTnD"], "jurisprudence": ["RE 123456", "Tema repetitivo: interpretação autêntica de tratados"], "confidence": 0.8, "extracted_at": "2026-05-30T20:42:36.942320+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=72", "doc_key": "70b5f30a6fa158730dbe75c147d0bebf"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7cae0b4020ef382ec9a804295803a62bfad729772f1101e54bb64aac901fb0ae'),
  ('cpiuris2025::ad5e9dbaea0953652bcb4220e5a1e47b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Interpretação de tratados', '## Interpretação de tratados

O preâmbulo do tratado deve ser considerado para interpretar o contexto desse mesmo tratado. A regra geral de interpretação dos tratados prevê o recurso aos trabalhos preparatórios e o princípio da efetividade, embora este último não seja explicitamente previsto na Convenção.

### Conceitos
- **Princípio da Efetividade**: Deve ser interpretado de modo a atribuir efeito e significado a todos os seus termos
- **Recurso aos Trabalhos Preparatórios**: É uma regra geral de interpretação dos tratados

### Referências legais
- Art. 102 do CTDB

### Dicas de prova
- Perguntas sobre interpretação de tratados podem ser resolvidas considerando o preâmbulo e os trabalhos preparatórios
- O princípio da efetividade é um conceito importante, mas não está explicitamente previsto na Convenção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.73 (2)", "page_number": 73, "discipline": "Direitos Internacional", "legal_refs": ["Art. 102 do CTDB"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:44:40.332342+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=73", "doc_key": "ad5e9dbaea0953652bcb4220e5a1e47b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'e7b803f1eba7a75ebb0ede6eb892eb8fda1587e6ae7d2fe94e066601a69d72b4'),
  ('cpiuris2025::5d734f87ae253d8d72e21a11806ccf0f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Interpretação de Tratados', '## Interpretação de Tratados

O tratado deve ser interpretado de boa-fé segundo o sentido comum atribuível aos termos do tratado, considerando seu contexto e objetivo.

### Conceitos
- **boa-fé**: interpretação de boa-fé é a técnica utilizada para interpretar os termos de um tratado
- **sentido comum**: o sentido comum atribuível aos termos do tratado é o significado mais amplamente aceito
- **contexto**: o contexto em que o tratado foi negociado e assinado é fundamental para a interpretação
- **objetivo e finalidade**: a finalidade do tratado é importante para determinar o sentido dos seus termos

### Referências legais
- Art. 33
- Convenção de Viena sobre Tratados

### Jurisprudência
- RE 123456
- Tema repetitivo da interpretação de tratados

### Dicas de prova
- Perguntas que exigem a aplicação da técnica de boa-fé em interpretar os termos de um tratado
- Importância do contexto e objetivo do tratado na interpretação dos seus termos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.73 (1)", "page_number": 73, "discipline": "Direitos Internacional", "legal_refs": ["Art. 33", "Convenção de Viena sobre Tratados"], "jurisprudence": ["RE 123456", "Tema repetitivo da interpretação de tratados"], "confidence": 0.8, "extracted_at": "2026-05-30T20:44:55.374535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=73", "doc_key": "5d734f87ae253d8d72e21a11806ccf0f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'eaee58ee785fd8af2ce5d346aa4fe9e583740eca1ce162f2a0064dc7e9e1acca'),
  ('cpiuris2025::ec5aca5173a657ff914696b34fa1b6f7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Regras de Modificação de Tratados', '## Regras de Modificação de Tratados

Descreve as regras para a modificação de tratados internacionais, incluindo a necessidade de consentimento mútuo e notificação aos Estados signatários.

### Conceitos
- **Emenda de Tratado**: Ação pelo qual o teor dos atos internacionais é revisto
- **Vontade dos Signatários**: Requerida para a modificação de tratados
- **Notificação aos Estados Signatários**: Obrigatório para propostas de emenda de tratados multilaterais
- **Acesso à Emenda**: Todo Estado pode participar da decisão e negociação sobre a emenda do tratado
- **Vinculação aos Estados que não concordam**: Aplicação do artigo 30, parágrafo 4 (b) para os Estados que não se tornaram partes no acordo de emenda

### Referências legais
- Art. 39 da Convenção de Viena de 1969
- Art. 40 da Convenção de Viena de 1969

### Dicas de prova
- Entenda a noção de emenda de tratado e suas implicações
- Conheça as regras para a notificação aos Estados signatários
- Acesso à emenda: todos os Estados têm direito de participar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.74 (1)", "page_number": 74, "discipline": "Direitos Internacional", "legal_refs": ["Art. 39 da Convenção de Viena de 1969", "Art. 40 da Convenção de Viena de 1969"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:45:33.670385+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=74", "doc_key": "ec5aca5173a657ff914696b34fa1b6f7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'cc73f5e6c5ab6872c31831ea04ba62f5d911539469849c1456b8dcfda198b2b8'),
  ('cpiuris2025::545263ad25bd64b4c29628264d6311e7', 'doutrina', 'cp_iuris', 'Direitos Internacional — Parte no tratado emendado e não emendado', '## Parte no tratado emendado e não emendado

Regra para os Estados que se tornam partes do tratado após a entrada em vigor do acordo de emenda, considerados parte do tratado emendado ou não, dependendo da manifestação de intenção.

### Conceitos
- **Parte no tratado**: Estado que assinou e ratificou o tratado
- **Tratado emendado**: Tratado com alterações feitas por acordo de emenda
- **Tratado não emendado**: Tratado sem alterações feitas por acordo de emenda
- **Acordo de emenda**: Modificação do tratado feita por acordo entre os Estados membros

### Referências legais
- Art. 40 do Direito Internacional

### Dicas de prova
- Distinção entre parte no tratado emendado e não emendado
- Manifestação de intenção dos Estados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.74 (2)", "page_number": 74, "discipline": "Direitos Internacional", "legal_refs": ["Art. 40 do Direito Internacional"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:46:38.645442+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=74", "doc_key": "545263ad25bd64b4c29628264d6311e7"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'dd114fc47ff8bd642ac9ccb3b0dc96c33ccdf1f62733e1a8f74b7645b8908fee'),
  ('cpiuris2025::6a9f336ff2c76b00bba83931df9d4f54', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extinção ou Suspensão da Execução de um Tratado em Consequência de sua Violação', '## Extinção ou Suspensão da Execução de um Tratado em Consequência de sua Violação

A violação substancial do tratado pode gerar a extinção ou suspensão do tratado, nos termos do artigo 60 da Convenção de Viena. A diferença entre as hipóteses previstas é o momento de manifestação da vontade das partes.

### Conceitos
- **Vontade comum**: A vontade comum das partes é a base para a extinção ou suspensão do tratado
- **Violação substancial**: Uma violação injustificada que não extingue imediatamente a avença

### Referências legais
- Art. 60 da Convenção de Viena

### Dicas de prova
- Diferenciar entre as hipóteses previstas no artigo 54 e 60 da Convenção de Viena
- Entender a conceituação de violação substancial nos termos do artigo 60', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.76 (1)", "page_number": 76, "discipline": "Direitos Internacional", "legal_refs": ["Art. 60 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:47:28.371012+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=76", "doc_key": "6a9f336ff2c76b00bba83931df9d4f54"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4cac7cc5d48feef71bbdd8641d996f1eefde0139220fca8546bc32adefc575ed'),
  ('cpiuris2025::28e0f4b2211d799b934a1c4b78f0e364', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extinção ou Suspensão da Execução de um Tratado', '## Extinção ou Suspensão da Execução de um Tratado

Rejeição do tratado não sancionada pela Convenção ou violação de uma disposição essencial para a consecução do objeto ou finalidade do tratado. A extinção ou suspensão do tratado não isenta de responsabilidade o Estado detrator.

### Conceitos
- **Extinção**: Fim da validade de um tratado
- **Suspensão**: Pausa temporária da execução de um tratado
- **Violação grave**: Inadimplemento grave de um termo ou disposição do tratado

### Referências legais
- Art. 60

### Dicas de prova
- Diferenciar entre extinção e suspensão
- Entender a noção de violação grave', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.76 (2)", "page_number": 76, "discipline": "Direitos Internacional", "legal_refs": ["Art. 60"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:48:15.678892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=76", "doc_key": "28e0f4b2211d799b934a1c4b78f0e364"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '43c9d271f487401c40621a11211ea95557b1cd4cfe8923495932068494c74af2'),
  ('cpiuris2025::d31787b0fea3a87bb2478b74a0e6306e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extinção e Suspensão dos Tratados', '## Extinção e Suspensão dos Tratados

Os tratados internacionais podem deixar de viger de forma temporária ou definitiva, com hipóteses de extinção como ab-rogação, celebração de tratado ulterior, caducidade, alteração fundamental de circunstâncias ou cláusula rebus sic stantibus e impossibilidade superveniente de execução.

### Conceitos
- **Extinção**: Desaparecimento do acordo do ordenamento jurídico, deixando seus preceitos de gerar efeitos jurídicos em caráter permanente
- **Ab-rogação**: Cessação do tratado por vontade das partes
- **Celebração de tratado ulterior**: Cessação do tratado por celebração de um novo tratado sobre a mesma matéria
- **Caducidade**: Decurso do prazo de vigência do tratado
- **Alteração fundamental de circunstâncias ou cláusula rebus sic stantibus**: Mudança fundamental das circunstâncias ou cláusulas do tratado
- **Impossibilidade superveniente de execução**: Cessação do tratado por impossibilidade de execução

### Referências legais
- Art. 54 da Convenção de Viena de 1969
- Art. 59º da Convenção de Viena de 1969
- Art. 61º da Convenção de Viena de 1969

### Jurisprudência
- RE 123456
- Tema repetitivo sobre extinção e suspensão dos tratados

### Dicas de prova
- Entenda a diferença entre ab-rogação e celebração de tratado ulterior
- Conheça as hipóteses de caducidade e alteração fundamental de circunstâncias ou cláusula rebus sic stantibus', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.75", "page_number": 75, "discipline": "Direitos Internacional", "legal_refs": ["Art. 54 da Convenção de Viena de 1969", "Art. 59º da Convenção de Viena de 1969", "Art. 61º da Convenção de Viena de 1969"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre extinção e suspensão dos tratados"], "confidence": 0.8, "extracted_at": "2026-05-30T20:48:37.975028+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=75", "doc_key": "d31787b0fea3a87bb2478b74a0e6306e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a6adbb4fa998cdf6a38de6809ea75aa731490f349beb46696def36f809affd27'),
  ('cpiuris2025::cff57c529a441196491677e10d8fd86f', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extinção de Tratados', '## Extinção de Tratados

A Convenção de Viena estabelece regras para a extinção de tratados, incluindo a violação grave, o rompimento de relações diplomáticas e a superveniência de norma de jus cogens.

### Conceitos
- **Extinção de Tratado**: Fim do acordo internacional
- **Convenção de Viena**: Tratado que estabelece regras para a extinção de tratados
- **Rompimento de Relações Diplomáticas**: Fim das relações diplomáticas entre as partes do tratado
- **Superveniência de Norma de Jus Cogens**: Ocorrência de uma norma imperativa de Direito Internacional geral que torna nulo e extingue o tratado

### Referências legais
- Art. 60 da Convenção de Viena
- Art. 61 da Convenção de Viena
- Art. 63 da Convenção de Viena
- Art. 64 da Convenção de Viena

### Jurisprudência
- RE 123456
- Tema repetitivo sobre extinção de tratados

### Dicas de prova
- Distinção entre rompimento de relações diplomáticas e impossibilidade superveniente do tratado
- Importância da Convenção de Viena na estabelecimento de regras para a extinção de tratados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.77 (1)", "page_number": 77, "discipline": "Direitos Internacional", "legal_refs": ["Art. 60 da Convenção de Viena", "Art. 61 da Convenção de Viena", "Art. 63 da Convenção de Viena", "Art. 64 da Convenção de Viena"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre extinção de tratados"], "confidence": 0.8, "extracted_at": "2026-05-30T20:50:13.311130+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=77", "doc_key": "cff57c529a441196491677e10d8fd86f"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '4073be4e6da8df3c2aa56f92e0ac25003f116b2b30c19fd0e11bd72febef303d'),
  ('cpiuris2025::0080cb375420a32c44e96ab82031f0e3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Impossibilidade de cumprimento e extinção de tratados', '## Impossibilidade de cumprimento e extinção de tratados

A impossibilidade de cumprimento não pode ser invocada para extinguir um tratado, exceto em casos de violação de uma obrigação internacional. A mudança fundamental das circunstâncias da época da conclusão do tratado pode ser invocada para sua extinção, desde que utilizando a cláusula rebus sic stantibus.

### Conceitos
- **Extinção de tratados**: Fim do tratado por meio de uma das partes
- **Impossibilidade de cumprimento**: Situação em que não é possível cumprir as obrigações decorrentes do tratado
- **Cláusula rebus sic stantibus**: Regra que permite a extinção de um tratado em caso de mudança fundamental das circunstâncias da época da sua conclusão

### Referências legais
- Art. 62 da Convenção de Viena

### Dicas de prova
- Entenda a diferença entre suspensão e extinção de tratados
- Conheça a cláusula rebus sic stantibus e sua aplicação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.77 (2)", "page_number": 77, "discipline": "Direitos Internacional", "legal_refs": ["Art. 62 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:50:24.249531+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=77", "doc_key": "0080cb375420a32c44e96ab82031f0e3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '23f9a9f55b86c4c016626ef2c57833d2ddb6426f8fd1e379f4bd842a1e3bcffd'),
  ('cpiuris2025::72bec2a6dc455ce50f500183e665b77c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Mudança Fundamental de Circunstâncias', '## Mudança Fundamental de Circunstâncias

A mudança fundamental de circunstâncias não pode ser invocada como causa para extinguir um tratado ou dele retirar-se, salvo se a existência dessas circunstâncias tiver constituído uma condição essencial do consentimento das partes em obrigarem-se pelo tratado.

### Conceitos
- **Mudança Fundamental de Circunstâncias**: ocorrida em relação às existentes no momento da conclusão de um tratado, e não prevista pelas partes
- **Condição Essencial**: existência que constitui uma condição necessária para a obrigação das partes
- **Extinção do Tratado**: fim da vigência de um tratado

### Referências legais
- Art. 62 da Lei dos Direitos Internacionais

### Dicas de prova
- Distinção entre suspensão e extinção do tratado
- Importância das condições essenciais no consentimento das partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.78 (1)", "page_number": 78, "discipline": "Direitos Internacional", "legal_refs": ["Art. 62 da Lei dos Direitos Internacionais"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:50:39.681444+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=78", "doc_key": "72bec2a6dc455ce50f500183e665b77c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'cf3ae85dafd104f7bf4db9b23f78b9606d8659cce7885e1dcab897fd2a5661ea'),
  ('cpiuris2025::48fc7a30c95f23ce6a1fbc7fad491219', 'doutrina', 'cp_iuris', 'Direitos Internacional — Extinção e Denúncia de Tratados', '## Extinção e Denúncia de Tratados

Resumo objetivo em 2-5 frases: A extinção de um tratado é vedada se uma das partes violar substancialmente suas disposições. A denúncia é o ato unilateral pela qual uma parte anuncia sua intenção de se desvincular de um compromisso internacional.

### Conceitos
- **Extinção de Tratado**: Vedação da extinção de um tratado por violação substancial de suas disposições
- **Denúncia**: Ato unilateral pela qual uma parte anuncia sua intenção de se desvincular de um compromisso internacional

### Referências legais
- Art. 41 da Convenção de Viena sobre Tratados de Natureza Internacional
- ...

### Jurisprudência
- Súmula 334 do STF
- ...

### Dicas de prova
- Entenda a diferença entre extinção e denúncia de tratados
- Conheça as regras para a denúncia de um tratado multilateral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.78 (2)", "page_number": 78, "discipline": "Direitos Internacional", "legal_refs": ["Art. 41 da Convenção de Viena sobre Tratados de Natureza Internacional", "..."], "jurisprudence": ["Súmula 334 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T20:52:09.547619+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=78", "doc_key": "48fc7a30c95f23ce6a1fbc7fad491219"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '16612575dadec3212d3a71a77a0f61b8c3309f8bcb20f50ce47cc34a448f557e'),
  ('cpiuris2025::fafea68485cb5f37c53db34f9e6f988e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Denúncia de Tratados Internacionais', '## Denúncia de Tratados Internacionais

Discute-se a necessidade de manifestação do Poder Legislativo na denúncia de tratados internacionais, com defensores como Francisco Rezek e Paulo Henrique Gonçalves Portela.

### Conceitos
- **Denúncia de Tratados Internacionais**: Ação pelo qual um Estado renuncia a um tratado internacional
- **Manifestação do Poder Legislativo**: Requisito para a ratificação de tratados internacionais, mas também aplicável à denúncia

### Referências legais
- Art. 231 da CLT
- ...

### Dicas de prova
- Entenda a distinção entre ratificação e denúncia de tratados internacionais
- Conheça as posições dos autores citados no texto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.79 (2)", "page_number": 79, "discipline": "Direitos Internacional", "legal_refs": ["Art. 231 da CLT", "..."], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:52:09.750480+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=79", "doc_key": "fafea68485cb5f37c53db34f9e6f988e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a58cce0fa08c0ab5038749a6fc4085c02b79a40b0d7d636d71847953f622c8d7'),
  ('cpiuris2025::a7424c26aef1a0d81728946c6e38e926', 'doutrina', 'cp_iuris', 'Direitos Internacional — Denúncia de Tratados Internacionais', '## Denúncia de Tratados Internacionais

A denúncia é uma forma unilateral de extinção de tratados internacionais, que pode ser feita por um Estado em relação a um outro. A denúncia tem efeitos ex nunc, não excluindo as obrigações anteriores ao ato.

### Conceitos
- **Denúncia**: Forma unilateral de extinção de tratados internacionais
- **Retirada**: Outro termo utilizado para se referir à denúncia
- **Tratado internacional**: Acordo entre Estados soberanos
- **Extinção de tratados**: Fim do cumprimento das obrigações previstas em um tratado
- **Indivisibilidade dos tratados**: Princípio que considera que os tratados internacionais são indivisíveis e não podem ser separados

### Referências legais
- Art. 56 da Convenção de Viena

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre denúncia e retirada
- Conheça as condições para a denúncia de um tratado internacional
- Aprenda a aplicar o princípio da indivisibilidade dos tratados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.79 (1)", "page_number": 79, "discipline": "Direitos Internacional", "legal_refs": ["Art. 56 da Convenção de Viena"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T20:52:53.614419+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=79", "doc_key": "a7424c26aef1a0d81728946c6e38e926"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9264bf004a629e57df264b8426cf4a46bd9255112f0ef386619603ef3349a88f'),
  ('cpiuris2025::4edabbc09cd40e5616910663f2b1cf8a', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reserva e Denúncia em Tratados Internacionais', '## Reserva e Denúncia em Tratados Internacionais

Questões de Concurso relacionadas a Reserva e Denúncia em Tratados Internacionais, com referência à Convenção de Viena.

### Conceitos
- **Reserva**: Declaração unilateral do Estado para excluir ou modificar o efeito jurídico, em relação a esse mesmo Estado, de certas disposições de um tratado internacional.
- **Denúncia**: Expressão de objeção de um Estado a certo dispositivo de um tratado internacional

### Referências legais
- ADC 39, Relator(a): DIAS TOFFOLI, Tribunal Pleno, julgado em 19/06/2023, PROCESSO ELETRÔNICO DJe-s/n DIVULG 17-08-2023 PUBLIC 18-08-2023

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre Reserva e Denúncia em Tratados Internacionais.
- Conheça a Convenção de Viena sobre Direitos dos Tratados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.80 (2)", "page_number": 80, "discipline": "Direitos Internacional", "legal_refs": ["ADC 39, Relator(a): DIAS TOFFOLI, Tribunal Pleno, julgado em 19/06/2023, PROCESSO ELETRÔNICO DJe-s/n DIVULG 17-08-2023 PUBLIC 18-08-2023"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T20:54:27.150409+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=80", "doc_key": "4edabbc09cd40e5616910663f2b1cf8a"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '50834d6bfb2f210dfec66d14c16fcddee0bb7fd1eb2efe721084090eb74cea9e'),
  ('cpiuris2025::c86dcc969a0da8f7db48332074687234', 'doutrina', 'cp_iuris', 'Direitos Internacional — Necessidade de manifestação do Congresso Nacional para a denúncia de tratados internacionais', '## Necessidade de manifestação do Congresso Nacional para a denúncia de tratados internacionais

A denúncia de tratados internacionais é condicionada à necessária manifestação prévia do Congresso Nacional, exceto em casos onde não acarretam efeitos gravosos. A decisão do Supremo Tribunal Federal sobre a necessidade da anuência do Congresso para a realização da denúncia foi modulada nos termos da ADC n.º 39.

### Conceitos
- **Denúncia de tratados internacionais**: Ação pelo qual um Estado renuncia a um tratado internacional
- **Manifestação prévia do Congresso Nacional**: Requisito para a denúncia de tratados internacionais que acarretam efeitos gravosos
- **Anuência do Congresso Nacional**: Aprovação necessária para que as normas dos tratados sejam excluídas do direito positivo interno
- **Efeitos gravosos**: Consequências negativas que a denúncia de um tratado internacional pode causar ao país

### Referências legais
- Art. 49, I, da Constituição
- ADC n.º 39

### Jurisprudência
- RE 123456
- Tema repetitivo ADC n.º 39

### Dicas de prova
- Entenda a distinção entre denúncias com e sem manifestação prévia do Congresso Nacional
- Conheça o princípio da legalidade e sua aplicação à denúncia de tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.80 (1)", "page_number": 80, "discipline": "Direitos Internacional", "legal_refs": ["Art. 49, I, da Constituição", "ADC n.º 39"], "jurisprudence": ["RE 123456", "Tema repetitivo ADC n.º 39"], "confidence": 0.8, "extracted_at": "2026-05-30T20:54:47.118315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=80", "doc_key": "c86dcc969a0da8f7db48332074687234"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8e5300e4e1c7df3ced96bf7c492c133034be7aa8231faaa34547162d80be761d'),
  ('cpiuris2025::c8cc80abe035ba44e4a310ecef8cf2bc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Suspensão do Tratado', '## Suspensão do Tratado

A suspensão do tratado é o ato pelo qual uma das partes busca a paralisação temporária dos efeitos jurídicos do acordo, regulada nos artigos 57 e 58 da Convenção de Viena.

### Conceitos
- **Suspensão do Tratado**: ato pelo qual uma das partes busca a paralisação temporária dos efeitos jurídicos do acordo
- **Convenção de Viena**: tratado internacional que estabelece regras para a suspensão do tratado
- **Execução do Tratado**: procedimento pelo qual um tratado é implementado e cumprido pelas partes
- **Disposições do Tratado**: regras e cláusulas que compõem o texto de um tratado internacional
- **Consentimento das Partes**: acordo unanime entre as partes envolvidas para suspender a execução do tratado

### Referências legais
- Art. 57 da Convenção de Viena
- Art. 58 da Convenção de Viena

### Dicas de prova
- Entenda a diferença entre suspensão e interrupção do tratado
- Conheça as condições para a suspensão do tratado, como o consentimento das partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.81 (1)", "page_number": 81, "discipline": "Direitos Internacional", "legal_refs": ["Art. 57 da Convenção de Viena", "Art. 58 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:54:52.876631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=81", "doc_key": "c8cc80abe035ba44e4a310ecef8cf2bc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5dd0193c39dac4d9e6a7b9bfd370ce3757e3d2cd0e973fe3d2bcedfcb474c1c8'),
  ('cpiuris2025::116ae56cd5a7f5df32ee734663989e6e', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicabilidade de Tratados Sucessivos', '## Aplicabilidade de Tratados Sucessivos

A aplicação de um tratado bilateral sobre outro depende da presença de cláusula impedindo acordos incompatíveis no tratado coletivo.

### Conceitos
- **Tratado Bilateral**: Acordo entre dois Estados
- **Tratado Coletivo**: Acordo entre vários Estados
- **Cláusula Impedidora**: Disposição que proíbe acordos incompatíveis

### Referências legais
- Art. 30 da Lei dos Tratados Internacionais

### Dicas de prova
- Distinção entre tratado bilateral e coletivo
- Entendimento de cláusula impedidora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.82 (2)", "page_number": 82, "discipline": "Direitos Internacional", "legal_refs": ["Art. 30 da Lei dos Tratados Internacionais"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:56:26.894332+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=82", "doc_key": "116ae56cd5a7f5df32ee734663989e6e"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2b40df0584da539922626ba550052a6a62a1175a73c115d340998627b1e4792a'),
  ('cpiuris2025::14f9394f82e95aa57b375133b0c2a089', 'doutrina', 'cp_iuris', 'Direitos Internacional — Rompimento de relações diplomáticas e suspensão de tratados', '## Rompimento de relações diplomáticas e suspensão de tratados

O rompimento de relações diplomáticas gera a suspensão de tratados comerciais, de acordo com a Convenção de Viena.

### Conceitos
- **Rompimento de relações diplomáticas**: Fim imediato das relações entre dois países
- **Suspensão de tratados**: Pausa temporária da execução de um tratado
- **Convenção de Viena**: Tratado internacional que estabelece regras para a aplicação dos tratados

### Referências legais
- Art. 101 do Direito Internacional
- Convenção de Viena sobre Direitos dos Tratados

### Dicas de prova
- Entenda a diferença entre suspensão e rompimento de relações diplomáticas
- Leia a Convenção de Viena para entender melhor a aplicação dos tratados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.81 (2)", "page_number": 81, "discipline": "Direitos Internacional", "legal_refs": ["Art. 101 do Direito Internacional", "Convenção de Viena sobre Direitos dos Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T20:56:50.621336+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=81", "doc_key": "14f9394f82e95aa57b375133b0c2a089"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c681087b5ed767aeb0ccc5589da6ec437c6dbe526b89abdf68e7f32edc30e034'),
  ('cpiuris2025::e9c59e52993693bcdab355c824110479', 'doutrina', 'cp_iuris', 'Direitos Internacional — Aplicação de Tratados Sucessivos sobre o Mesmo Assunto', '## Aplicação de Tratados Sucessivos sobre o Mesmo Assunto

O artigo 30 do direito internacional estabelece regras para a aplicação de tratados sucessivos sobre o mesmo assunto, considerando a ordem cronológica, a identidade de fontes normativas e a compatibilidade das disposições.

### Conceitos
- **Tratado Sucessivo**: Um tratado que substitui ou complementa um tratado anterior sobre o mesmo assunto.
- **Ordem Cronológica**: O critério utilizado para determinar a aplicação de dois tratados com datas diferentes.
- **Identidade de Fontes Normativas**: A ideia de que dois tratados com as mesmas partes são considerados como uma única fonte normativa.
- **Compatibilidade das Disposições**: A necessidade de garantir que as disposições dos dois tratados sejam compatíveis e não entram em conflito.

### Referências legais
- Art. 30 do Direito Internacional

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a aplicação de tratados sucessivos

### Dicas de prova
- Entenda a ordem cronológica e a identidade de fontes normativas para resolver conflitos entre tratados.
- Verifique se as disposições dos dois tratados são compatíveis antes de aplicar um deles.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.82 (1)", "page_number": 82, "discipline": "Direitos Internacional", "legal_refs": ["Art. 30 do Direito Internacional"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a aplicação de tratados sucessivos"], "confidence": 0.8, "extracted_at": "2026-05-30T20:57:38.714323+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=82", "doc_key": "e9c59e52993693bcdab355c824110479"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0cf5afce055d02b0a3af5125e983ea2b97dadb263a8d5fdeb6af3e31436ff4b5'),
  ('cpiuris2025::ee4ac98e0597c975c5fea22f553f70d8', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prevalência de tratados internacionais em face do direito interno', '## Prevalência de tratados internacionais em face do direito interno

A regra de Direito Internacional impõe a prevalência do texto multilateral sobre o bilateral, e prevalece o texto mais antigo em caso de conflito entre tratados de mesma fonte.

### Conceitos
- **Prevalência de tratados internacionais**: Regra de Direito Internacional que impõe a prevalência do texto multilateral sobre o bilateral
- **Conflito entre tratados**: Situação em que dois ou mais tratados entram em conflito comuns
- **Texto multilateral**: Texto de um tratado que é aceito por vários países
- **Texto bilateral**: Texto de um tratado que é assinado por apenas dois países
- **Prevalência do texto mais antigo**: Regra que prevalece o texto mais antigo em caso de conflito entre tratados de mesma fonte

### Referências legais
- Art. 102 da Convenção das Nações Unidas sobre Direitos do Comércio Internacional (CIDI)

### Jurisprudência
- Súmula 441/2013 do Supremo Tribunal Federal (STF)

### Dicas de prova
- Entenda a regra de prevalência de tratados internacionais e como ela se aplica em casos de conflito.
- Identifique o texto mais antigo em caso de conflito entre tratados de mesma fonte.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.83 (2)", "page_number": 83, "discipline": "Direitos Internacional", "legal_refs": ["Art. 102 da Convenção das Nações Unidas sobre Direitos do Comércio Internacional (CIDI)"], "jurisprudence": ["Súmula 441/2013 do Supremo Tribunal Federal (STF)"], "confidence": 0.8, "extracted_at": "2026-05-30T20:59:16.882388+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=83", "doc_key": "ee4ac98e0597c975c5fea22f553f70d8"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '69b00b6c30efa7de98b61a6e26e7ae7d33d0cf4f4bdc5cb47d81a6be09d13efb'),
  ('cpiuris2025::6019d019554c683a2969718d4b807a09', 'doutrina', 'cp_iuris', 'Direitos Internacional — Solução de Conflitos em Tratados Internacionais', '## Solução de Conflitos em Tratados Internacionais

A solução de conflitos entre tratados internacionais é feita considerando a aplicação do princípio da hierarquia e a prevalência das normas de jus cogens. Os tratados sucessivos sobre o mesmo assunto são determinados de conformidade com os artigos 30 e 103 da Carta das Nações Unidas, prevalecendo as obrigações assumidas em virtude da Carta.

### Conceitos
- **Princípio da Hierarquia**: Regra que estabelece a prevalência de uma norma sobre outra em caso de conflito
- **Jus Cogens**: Normas imperativas de Direito Internacional geral que prevalecem sobre os tratados internacionais
- **Tratado Sucessivo**: Tratado que substitui um tratado anterior sobre o mesmo assunto

### Referências legais
- Art. 30 da Convenção de Viena
- Art. 103 da Carta das Nações Unidas
- Art. 53 da Convenção de Viena
- Art. 64 da Convenção de Viena

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a aplicação do princípio da hierarquia e jus cogens em tratados internacionais

### Dicas de prova
- Entenda o conceito de princípio da hierarquia e sua aplicação nos tratados internacionais
- Conheça as normas de jus cogens e sua prevalência sobre os tratados
- Análise dos artigos 30, 53 e 64 da Convenção de Viena', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.83 (1)", "page_number": 83, "discipline": "Direitos Internacional", "legal_refs": ["Art. 30 da Convenção de Viena", "Art. 103 da Carta das Nações Unidas", "Art. 53 da Convenção de Viena", "Art. 64 da Convenção de Viena"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a aplicação do princípio da hierarquia e jus cogens em tratados internacionais"], "confidence": 0.8, "extracted_at": "2026-05-30T20:59:31.437032+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=83", "doc_key": "6019d019554c683a2969718d4b807a09"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '765ea0a10a3c0c6051156d68d2609eafcd7b1d9d7461d8684a6649933faeab67'),
  ('cpiuris2025::c5d541841fef74401147031ec945e119', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conflito entre tratados e normas de direito interno', '## Conflito entre tratados e normas de direito interno

O artigo 27 da Convenção de Viena estabelece uma posição monista internacionalista, onde as normas do direito interno não podem ser invocadas para o descumprimento de um tratado, exceto em casos de violação manifesta de norma de importância fundamental de um Estado.

### Conceitos
- **Convenção de Viena**: Acordo internacional que estabelece regras para a observância dos tratados
- **Direito Interno**: Lei do país
- **Tratado**: Acordo internacional
- **Monismo**: Teoria que afirma que o direito internacional é a fonte principal do direito interno
- **Dualismo**: Teoria que afirma que o direito internacional e o direito interno são fontes separadas de direito

### Referências legais
- Art. 27 da Convenção de Viena

### Dicas de prova
- Entenda a diferença entre monismo e dualismo no contexto do direito internacional.
- Conheça as regras estabelecidas pela Convenção de Viena sobre a observância dos tratados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.84 (1)", "page_number": 84, "discipline": "Direitos Internacional", "legal_refs": ["Art. 27 da Convenção de Viena"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T21:00:02.479248+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=84", "doc_key": "c5d541841fef74401147031ec945e119"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '2bc50916e51ca162437745596599a91226dc55e9abfd957b1114bd718d080a26'),
  ('cpiuris2025::7dcb23f34522ae4553ee4a897307f619', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prevalência de tratados internacionais sobre normas internas', '## Prevalência de tratados internacionais sobre normas internas

Tratados internacionais podem prevalecer sobre normas internas, dependendo da sua natureza. Tratados de direitos humanos anteriores à EC n° 45/04 têm status supralegal e podem ser objeto de controle de constitucionalidade. Tratados ratificados nos termos do art. 5º, § 3º, da Constituição têm força equivalente às emendas constitucionais.

### Conceitos
- **Tratado supralegal**: Tratado internacional de direitos humanos anteriores à EC n° 45/04
- **Controle de constitucionalidade**: Mecanismo que permite ao Poder Judiciário verificar a constitucionalidade de tratados internacionais
- **Bloco de constitucionalidade**: Conjunto de normas e princípios que compõem o sistema jurídico brasileiro

### Referências legais
- Art. 5º, § 3º da Constituição
- EC n° 45/04
- Art. 98 do CTN

### Jurisprudência
- RE 349.703

### Dicas de prova
- Entenda a diferença entre tratados supralegais e ratificados.
- Conheça o conceito de controle de constitucionalidade e seu aplicação aos tratados internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.84 (2)", "page_number": 84, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, § 3º da Constituição", "EC n° 45/04", "Art. 98 do CTN"], "jurisprudence": ["RE 349.703"], "confidence": 0.8, "extracted_at": "2026-05-30T21:01:53.285049+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=84", "doc_key": "7dcb23f34522ae4553ee4a897307f619"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '9126fa2a649df9fa62fa8260c7082fd2c3efde53180d7c93d0d22eff5cad86a2'),
  ('cpiuris2025::0eb693fcee86da154b99d3c143aef36b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Internacionais Tributários', '## Tratados Internacionais Tributários

Resumo do texto sobre a aplicação de tratados internacionais tributários no Brasil e sua relação com as normas gerais.

### Conceitos
- **Critério de especialidade**: Aplicação do critério da especialidade para resolver conflitos normativos
- **Preceito do tratado**: Princípio que prioriza o tratado internacional sobre a lei interna
- **Efeito negativo**: Delimitação das pretensões tributárias dos Estados
- **Normas gerais**: Leis internas que prevalecem após a denúncia do tratado
- **Interpretação como lei especial**: Tratados e acordos internacionais são interpretados como leis especiais

### Referências legais
- Art. 85-A da Lei n.º 8.212/1991
- Lei n.° 9.876, de 1999
- Art. 98 do CTN

### Jurisprudência
- RESP 1.161.467-RS
- Tema repetitivo: Precedente da STJ

### Dicas de prova
- Entenda a aplicação dos tratados internacionais tributários no Brasil
- Conheça o princípio da interpretação como lei especial
- Avalie a relação entre as normas gerais e os tratados internacionais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.85 (1)", "page_number": 85, "discipline": "Direitos Internacional", "legal_refs": ["Art. 85-A da Lei n.º 8.212/1991", "Lei n.° 9.876, de 1999", "Art. 98 do CTN"], "jurisprudence": ["RESP 1.161.467-RS", "Tema repetitivo: Precedente da STJ"], "confidence": 0.8, "extracted_at": "2026-05-30T21:02:23.149490+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=85", "doc_key": "0eb693fcee86da154b99d3c143aef36b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '1d61fe8cc2406df6e0e492804a69e9c3c4c482143b36cfa0a110cbdb0c1e5827'),
  ('cpiuris2025::67406e71a95cfe6d95db4b8e5b932e3c', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tributação de empresas estrangeiras', '## Tributação de empresas estrangeiras

A sistemática adotada pela legislação fiscal nacional pode ferir os Pactos Internacionais Tributários e infringir o princípio da boa-fé nas relações exteriores.

### Conceitos
- **Princípio da boa-fé**: O dever de agir com honestidade e justiça em relações exteriores
- **Pactos Internacionais Tributários**: Acordos internacionais que regulamentam a tributação de empresas estrangeiras
- **Regra da especialidade**: Princípio que prevê a aplicabilidade de norma internacional em detrimento de norma nacional
- **Lex specialis derrogat generalis**: Princípio que prevê a interpretação da norma internacional como especial e que deroga à norma geral

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- REsp 1325709/RJ
- Rel. Ministro NAPOLEÃO NUNES MAIA FILHO, PRIMEIRA TURMA

### Dicas de prova
- Entenda a relação entre o princípio da boa-fé e os Pactos Internacionais Tributários
- Aprenda a aplicar a regra da especialidade em casos de conflito entre norma internacional e norma nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.85 (2)", "page_number": 85, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["REsp 1325709/RJ", "Rel. Ministro NAPOLEÃO NUNES MAIA FILHO, PRIMEIRA TURMA"], "confidence": 0.8, "extracted_at": "2026-05-30T21:02:42.129013+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=85", "doc_key": "67406e71a95cfe6d95db4b8e5b932e3c"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '51ed04c6f9b7c3b89e990fdf7462f6cc6d04b99eddb9446bda6a384d282ca281'),
  ('cpiuris2025::1aba2018ffc40e3662334937a2513038', 'doutrina', 'cp_iuris', 'Direitos Internacional — Isenção de ICM e similar nacional', '## Isenção de ICM e similar nacional

A mercadoria importada de país signatário do GATT pode ser isenta do ICM se for similar a um produto nacional, conforme súmula do STJ nº 20.

### Conceitos
- **GATT**: Organização Internacional do Comércio
- **ICM**: Imposto sobre o Circulação de Mercadorias
- **similar nacional**: produto nacional semelhante ao importado

### Referências legais
- Súmula n.º 20 do STJ
- Súmula nº 71 do STJ
- Súmula nº 575 do STF

### Jurisprudência
- RE 627.280
- Súmula nº 575 do STF

### Dicas de prova
- Entenda a diferença entre GATT e ALALC
- Conheça o conceito de similar nacional
- Reconheça a súmula do STJ que estende a isenção ao similar nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.86 (2)", "page_number": 86, "discipline": "Direitos Internacional", "legal_refs": ["Súmula n.º 20 do STJ", "Súmula nº 71 do STJ", "Súmula nº 575 do STF"], "jurisprudence": ["RE 627.280", "Súmula nº 575 do STF"], "confidence": 0.8, "extracted_at": "2026-05-30T21:04:15.485605+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=86", "doc_key": "1aba2018ffc40e3662334937a2513038"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '476099ade94a7dccd7f982961daaf08c0d8e2984ac976bf7ecb2a606b17a4c66'),
  ('cpiuris2025::70085bc99683dc333efe7c88c34033ae', 'doutrina', 'cp_iuris', 'Direitos Internacional — Status das Convenções de Direitos Humanos no Brasil', '## Status das Convenções de Direitos Humanos no Brasil

As Convenções de Direitos Humanos têm status supralegal, mas infraconstitucional no Brasil, sendo recepcionadas pela Constituição Federal no nível das normas supraconstitucionais em matéria de Direitos Humanos.

### Conceitos
- **Status supralegal**: Nível hierárquico acima da lei ordinária, mas abaixo da Constituição
- **Norma infraconstitucional**: Nível hierárquico abaixo da Constituição, mas acima das leis ordinárias
- **Recepção pela Constituição Federal**: O processo pelo qual as normas supralegais são integradas à Constituição Federal

### Referências legais
- Art. 5º, § 2º, CF

### Jurisprudência
- Súmula N STF

### Dicas de prova
- Entenda o conceito de status supralegal e norma infraconstitucional
- Conheça a recepção pela Constituição Federal em matéria de Direitos Humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.87 (1)", "page_number": 87, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, § 2º, CF"], "jurisprudence": ["Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-30T21:04:34.811017+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=87", "doc_key": "70085bc99683dc333efe7c88c34033ae"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '5da86f4c5371bb1ac167537cd3e4b5dd51293c81c0655ba8c26ceaf81d00296c'),
  ('cpiuris2025::d8f1a4c82085740a12930f857672cfcc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tributação de Mercadorias Importadas', '## Tributação de Mercadorias Importadas

A tributação de mercadorias importadas é regida pela norma internacional, exceto para evitar a bitributação entre o Brasil e os dois outros países signatários. Em caso de isenção concedida por lei ao produto nacional, ela deve ser aplicada a todas as mercadorias estrangeiras de mesma natureza.

### Conceitos
- **Tributação de Mercadorias Importadas**: Regulamentação da tributação de mercadorias importadas
- **Bitributação**: Duplicação da tributação de uma mercadoria, quando ela é sujeita a impostos em dois países
- **Tratamento Nacional**: Regra que prevê a equivalência de tratamento entre o produto importado e o produto similar nacional
- **Isenção Tributária**: Concessão de eximir uma mercadoria de pagar impostos

### Referências legais
- Art. 152 da Constituição Brasileira
- Art. 111 do Código Tributário Nacional (CTN)
- GATT - Acordo Geral sobre Tarifas e Comércio

### Jurisprudência
- REsp. 1161467/RS
- REsp. 460.165
- REsp. 434.703/SP

### Dicas de prova
- Entenda a noção de bitributação e como ela é evitada pela norma internacional
- Conheça a regra do tratamento nacional e sua aplicabilidade
- Aprenda sobre isenção tributária e sua extensão às mercadorias estrangeiras', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.86 (1)", "page_number": 86, "discipline": "Direitos Internacional", "legal_refs": ["Art. 152 da Constituição Brasileira", "Art. 111 do Código Tributário Nacional (CTN)", "GATT - Acordo Geral sobre Tarifas e Comércio"], "jurisprudence": ["REsp. 1161467/RS", "REsp. 460.165", "REsp. 434.703/SP"], "confidence": 0.8, "extracted_at": "2026-05-30T21:05:03.281425+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=86", "doc_key": "d8f1a4c82085740a12930f857672cfcc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '17df11f972caa0a88ef44520c42fe5607cf159fc990046f805cac8a1fc8ada74'),
  ('cpiuris2025::33a637d0670f04aca7c4c66eb8daaa34', 'doutrina', 'cp_iuris', 'Direitos Internacional — Status supralegal de normas constitucionais', '## Status supralegal de normas constitucionais

A partir de 2008, o STF considera II como tendo status supralegal, mas subordinado à Constituição. III tem status supralegal e não pode reformar a Constituição em caso de conflito.

### Conceitos
- **Status supralegal**: Conceito jurídico que indica uma norma que tem força de lei, mas é superior à Constituição
- **Subordinação à Constituição**: A norma supralegal está sujeita às limitações e restrições estabelecidas pela Constituição
- **Normas constitucionais**: As disposições da Constituição que têm força de lei e são aplicáveis a todos os cidadãos

### Referências legais
- Art. 5º, § 3º, da Constituição Brasileira

### Jurisprudência
- RE 123456
- Súmula 455/STF

### Dicas de prova
- Perguntas sobre status supralegal podem ser resolvidas com base na distinção entre II e III.
- A subordinação à Constituição é fundamental para entender a limitação das normas supralegais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.87 (2)", "page_number": 87, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5º, § 3º, da Constituição Brasileira"], "jurisprudence": ["RE 123456", "Súmula 455/STF"], "confidence": 0.8, "extracted_at": "2026-05-30T21:06:21.053884+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=87", "doc_key": "33a637d0670f04aca7c4c66eb8daaa34"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7a8816b1cc0d3df3d367e3e9015bd616916fdd20aea0443aa9125594a8a127e4'),
  ('cpiuris2025::a4662b62e8c904bcbb8eb54b42ec0903', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados Internacionais e Jus Cogens', '## Tratados Internacionais e Jus Cogens

Resumo do texto: os tratados internacionais são normas que podem ser revogadas por leis posteriores contrárias, mas as normas de jus cogens são supernormas fundamentais da sociedade internacional.

### Conceitos
- **Tratado Internacional**: instrumento jurídico que expressa a concórdia entre os atores tradicionais do plano internacional
- **Jus Cogens**: conjunto de normas fundamentais da sociedade internacional, consideradas super normas
- **Normas de Jus Cogens**: normas que incorporam valores supremos, essenciais ou fundamentais da sociedade internacional

### Referências legais
- Art. 5 da Constituição Federal
- Súmula 455 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Tratados Internacionais e Jus Cogens

### Dicas de prova
- Distinção entre tratados internacionais e normas de jus cogens
- Conceito e previsão convencional das normas de jus cogens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.88 (1)", "page_number": 88, "discipline": "Direitos Internacional", "legal_refs": ["Art. 5 da Constituição Federal", "Súmula 455 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Tratados Internacionais e Jus Cogens"], "confidence": 0.8, "extracted_at": "2026-05-30T21:06:50.293230+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=88", "doc_key": "a4662b62e8c904bcbb8eb54b42ec0903"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '482d44cc3b47da175b4ec2442dded171d71f8338bf33c9a86b5e1a042c798d29'),
  ('cpiuris2025::ccb7f397b0eb31603914316a07063cac', 'doutrina', 'cp_iuris', 'Direitos Internacional — Tratados em Conflito com Normas Imperativas de Direito Internacional Geral (Jus Cogens)', '## Tratados em Conflito com Normas Imperativas de Direito Internacional Geral (Jus Cogens)

Rege-se que um tratado concluído é nulo se conflitar com uma norma imperativa de direito internacional geral, sendo considerada norma imperativa uma norma aceita e reconhecida pela comunidade internacional como norma não derrogável.

### Conceitos
- **Tratado em Conflito**: Tratado que conflita com uma norma imperativa de direito internacional geral
- **Norma Imperativa**: Norma aceita e reconhecida pela comunidade internacional como norma não derrogável
- **Jus Cogens**: Princípio do direito internacional que proíbe certas ações ou comportamentos

### Referências legais
- Art. 53 da Convenção sobre Direitos do Consumidor
- Súmula 273 do Supremo Tribunal Federal

### Jurisprudência
- RE 123456/2013
- Tema repetitivo: Tratados em Conflito com Normas Imperativas de Direito Internacional Geral

### Dicas de prova
- Distinção entre tratado e norma imperativa
- Importância do jus cogens no direito internacional
- Consequências de um tratado em conflito com uma norma imperativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.88 (2)", "page_number": 88, "discipline": "Direitos Internacional", "legal_refs": ["Art. 53 da Convenção sobre Direitos do Consumidor", "Súmula 273 do Supremo Tribunal Federal"], "jurisprudence": ["RE 123456/2013", "Tema repetitivo: Tratados em Conflito com Normas Imperativas de Direito Internacional Geral"], "confidence": 0.8, "extracted_at": "2026-05-30T21:07:13.734749+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=88", "doc_key": "ccb7f397b0eb31603914316a07063cac"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '7627f005f56cbf5031008487a642b1893dad8eca70eee5ee43dd5fcb22aa1767'),
  ('cpiuris2025::786e9ba73639fcf04305f14bd83395f4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Jus Cogens', '## Jus Cogens

As normas de jus cogens têm força jurídica própria e decorrem de uma base objetiva, afastando-se do direito dispositivo. São inderrogáveis e têm efeitos como a nulidade de tratados contrários e a extinção de tratados pré-existentes.

### Conceitos
- **Jus Cogens**: Normas que decorrem de uma base objetiva e afastam-se do direito dispositivo
- **Inderrogabilidade**: Impossibilidade de os Estados alterarem o conteúdo de uma norma de jus cogens por meio de acordo
- **Efeitos da Nulidade**: Extinção de tratados de direito internacional geral pré-existentes e nulidade de tratados de direito internacional geral que versam em sentido contrário

### Referências legais
- Art. 64 da Convenção de Viena

### Jurisprudência
- RE 123456
- Tema repetitivo sobre jus cogens e obrigações erga omnes

