  ('cpiuris2025::6982bba9a78225d23586bcd949448acc', 'doutrina', 'cp_iuris', 'Direitos Internacional — Obrigação Erga Omnes e Jus Cogens', '## Obrigação Erga Omnes e Jus Cogens

As obrigações erga omnes são de natureza solidária, sendo titularidade da sociedade internacional, com tutela exercida por seus membros. O jus cogens é uma categoria específica dessas obrigações.

### Conceitos
- **Obrigação Erga Omnes**: obrigação de natureza solidária, titularidade da sociedade internacional
- **Jus Cogens**: categoria de obrigações erga omnes, de natureza obrigatória e inderrogável

### Referências legais
- Art. 62 do Estatuto do Direito Internacional
- ...

### Jurisprudência
- Barcelona Traction (1970)
- ...

### Dicas de prova
- Entenda a distinção entre obrigações erga omnes e jus cogens.
- Conheça o conceito de sociedade internacional e sua titularidade das obrigações erga omnes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.89 (2)", "page_number": 89, "discipline": "Direitos Internacional", "legal_refs": ["Art. 62 do Estatuto do Direito Internacional", "..."], "jurisprudence": ["Barcelona Traction (1970)", "..."], "confidence": 0.8, "extracted_at": "2026-05-30T21:09:21.867797+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=89", "doc_key": "6982bba9a78225d23586bcd949448acc"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '492f2b4413a5eccccf769dec93d624a4e90eb2238eb9ab377cfa4f51a3caf05c'),
  ('cpiuris2025::1c153e75f4c6164f7c81b93194a513e9', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento de Normas no Direito Internacional', '## Reconhecimento de Normas no Direito Internacional

As normas internacionais podem ser provenientes do direito convencional, costume internacional ou princípios gerais do direito internacional. O reconhecimento de uma norma não depende da sua fonte, mas sim da sua posição hierárquica.

### Conceitos
- **Fontes do Direito Internacional**: Direito convencional, costume internacional e princípios gerais do direito internacional
- **Reconhecimento de Normas**: Processo pelo qual uma norma é considerada imperativa e vinculante para os Estados
- **Posição Hierárquica**: A posição que uma fonte do direito internacional ocupa em relação às outras
- **Jus Cogens**: Normas imperativas e vinculantes que decorrem da lei interna

### Referências legais
- Art. 23 da Convenção de Viena sobre Direitos do Comércio Internacional
- Súmula 441 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Reconhecimento de Normas no Direito Internacional

### Dicas de prova
- Entenda a diferença entre texto e norma
- Conheça as fontes do direito internacional
