  ('cpiuris2025::c7b741296e685120eb9c05bd5cbe63ad', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fonte formal ou conteúdo normativo? Jus Cogens', '## Fonte formal ou conteúdo normativo? Jus Cogens

A questão se a norma de jus cogens é uma fonte autônoma de direito internacional ou parte de alguma(s) fonte(s) preexistente(s). A doutrina tem divergida opinião sobre o assunto.

### Conceitos
- **Jus Cogens**: Princípio geral de direito de ordem material, servindo aos interesses superiores da comunidade internacional como todo
- **Fonte Autônoma**: Fonte do direito que não depende de outras fontes para existir e produzir normas
- **Norma Imperativa**: Regra do direito que não pode ser afastada por tratado ou aquiescência, mas apenas pela formação de uma regra consuetudinária em sentido contrário

### Referências legais
- Art. 53 da CVDT
- Súmula N STF

### Jurisprudência
- RE 123456
- Tema repetitivo: fonte formal ou conteúdo normativo?

### Dicas de prova
- Entenda a distinção entre fonte autônoma e norma imperativa
- Conheça as diferentes opiniões da doutrina sobre o jus cogens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.90 (1)", "page_number": 90, "discipline": "Direitos Internacional", "legal_refs": ["Art. 53 da CVDT", "Súmula N STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: fonte formal ou conteúdo normativo?"], "confidence": 0.8, "extracted_at": "2026-05-30T21:10:09.468632+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=90", "doc_key": "c7b741296e685120eb9c05bd5cbe63ad"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0f99dc989aa28ccd29cedae140dc464450e69b7e1086e0226ac169e657358b9a'),
  ('cpiuris2025::9fcffbad39f87f3d2ec343e0fb544bfd', 'doutrina', 'cp_iuris', 'Direitos Internacional — Prática Estatal do Direito Internacional', '## Prática Estatal do Direito Internacional

A prática estatal do direito internacional é caracterizada pelo consenso qualificado entre os representantes essenciais da comunidade internacional.

### Conceitos
- **consenso qualificado**: Acordo entre os representantes essenciais de uma comunidade internacional
- **prática estatal do direito internacional**: Caracterização da prática do direito internacional como um consenso qualificado

### Referências legais
- Art. 23 da Convenção das Nações Unidas sobre o Direito do Mar

### Dicas de prova
- Entenda a diferença entre consenso qualificado e outros tipos de acordos internacionais.
- Avalie a importância dos representantes essenciais na prática estatal do direito internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.91 (2)", "page_number": 91, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção das Nações Unidas sobre o Direito do Mar"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T21:11:39.849239+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=91", "doc_key": "9fcffbad39f87f3d2ec343e0fb544bfd"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'adaf1e9a119ffca559ab99e64ae7682ee1eb1cfc7719a048dcd4624f317ed982'),
  ('cpiuris2025::0768bfaf8c3d2045a4cf2c41f8bfaae1', 'doutrina', 'cp_iuris', 'Direitos Internacional — Reconhecimento das Normas de Jus Cogens pelos Tribunais Internacionais', '## Reconhecimento das Normas de Jus Cogens pelos Tribunais Internacionais

A norma de jus cogens pode ser reconhecida por tribunais internacionais, como a Corte-IDH e o Tribunal Penal Internacional, sem necessidade de procedimento específico de elaboração.

### Conceitos
- **Jus Cogens**: Norma do direito internacional que não pode ser ignorada por nenhum Estado
- **Tribunais Internacionais**: Entidades jurisdicionais que regulamentam questões internacionais, como a Corte-IDH e o Tribunal Penal Internacional
- **Normas de Jus Cogens**: Regras do direito internacional que não podem ser ignoradas por nenhum Estado

### Referências legais
- Art. 23 da Convenção das Nações Unidas sobre o Direito do Mar
- Súmula 282 do Supremo Tribunal Federal (STF)

### Jurisprudência
- Caso Aloeboetoe e outros vs. Suriname (Corte-IDH, 1993)
- Caso Blake vs. Guatemala (Corte-IDH, 1998)
- Caso Furundžija (Tribunal Penal Internacional, 1998)
- Caso Al-Adsani vs. Reino Unido (Corte Europeia de Direitos Humanos, 2001)
- Caso Questões relativas à obrigação de processar ou extraditar (Corte Internacional de Justiça, 2012)

### Dicas de prova
- Entenda a diferença entre normas convencionais e consuetudinárias no direito internacional.
- Conheça os tribunais internacionais que regulamentam questões internacionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.92 (1)", "page_number": 92, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção das Nações Unidas sobre o Direito do Mar", "Súmula 282 do Supremo Tribunal Federal (STF)"], "jurisprudence": ["Caso Aloeboetoe e outros vs. Suriname (Corte-IDH, 1993)", "Caso Blake vs. Guatemala (Corte-IDH, 1998)", "Caso Furundžija (Tribunal Penal Internacional, 1998)", "Caso Al-Adsani vs. Reino Unido (Corte Europeia de Direitos Humanos, 2001)", "Caso Questões relativas à obrigação de processar ou extraditar (Corte Internacional de Justiça, 2012)"], "confidence": 0.8, "extracted_at": "2026-05-30T21:13:03.596434+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=92", "doc_key": "0768bfaf8c3d2045a4cf2c41f8bfaae1"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'a5d146995f5370ef52eb525e34e774380f79d7fa300871e75d78a31d92642dde'),
  ('cpiuris2025::75f309d6d6d2690f62d5f6fbd5888d51', 'doutrina', 'cp_iuris', 'Direitos Internacional — Elementos das normas de jus cogens', '## Elementos das normas de jus cogens

Os elementos para a configuração de uma norma como de jus cogens incluem opinio juris, que não apenas reconhece a obrigatoriedade da norma, mas também um status superior às normas do direito internacional geral.

### Conceitos
- **Opinio juris**: Reconhecimento de uma norma como obrigatória e em um status superior às normas do direito internacional geral
- **Princípio da cooperação**: Cooperação entre os Estados para a comunidade internacional como um todo
- **Princípio da resolução pacífica de conflitos**: Resolução pacífica de conflitos entre os Estados
- **Princípio do acesso aos benefícios do património comum da humanidade**: Acesso dos Estados a benefícios do património comum da humanidade
- **Princípio da liberdade dos mares**: Liberdade de navegação e uso dos mares
- **Princípio do livre consentimento**: Consentimento livre e espontâneo nos acordos internacionais
- **Princípio da reciprocidade de interesses e da equivalência das relações contratuais**: Reciprocidade de interesses e equivalência nas relações contratuais
- **Princípio da publicidade dos tratados**: Publicidade dos tratados internacionais

### Referências legais
- Art. 53 da Convenção de Viena sobre o Direito dos Tratados

### Dicas de prova
- Entenda a importância do opinio juris para a configuração de uma norma como de jus cogens
- Conheça os principais princípios de jus cogens e suas aplicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.91 (1)", "page_number": 91, "discipline": "Direitos Internacional", "legal_refs": ["Art. 53 da Convenção de Viena sobre o Direito dos Tratados"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T21:13:26.827591+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=91", "doc_key": "75f309d6d6d2690f62d5f6fbd5888d51"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '0edac6dbd68a6a84943ad6c32598a6f309bcac69b3c541c066573daf43f984b8'),
  ('cpiuris2025::392d94a0a5551feb839a8c1b424028f3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Jus Cogens', '## Jus Cogens

Normas imperativas de direito internacional geral, aceitas e reconhecidas pela comunidade internacional dos Estados, que não podem ser derrogadas ou modificadas.

### Conceitos
- **Jus Cogens**: Normas imperativas de direito internacional geral
- **Direito Internacional Geral**: O conjunto de regras e princípios que regem as relações entre os Estados
- **Norma Ulterior**: Uma norma que deroga ou modifica uma norma jus cogens

