  ('cpiuris2025::34816fc6b6e5d2adf4c65ffe999efd63', 'doutrina', 'cp_iuris', 'Direitos Internacional — Derrogas e Soft Law', '## Derrogas e Soft Law

O texto discute as derrogas das normas do direito internacional, incluindo a possibilidade de tratados derrogarem normas jus cogens e a natureza da soft law como um produto recente do direito internacional.

### Conceitos
- **Jus Cogens**: normas fundamentais do direito internacional que não podem ser revogadas por tratados ou outras fontes de direito
- **Soft Law**: acordos e declarações não obrigatórias que não criam obrigações jurídicas, mas têm conteúdo moral ou político

### Referências legais
- Art. 23 da Convenção das Nações Unidas sobre o Direito do Mar
- Súmula 441 do Supremo Tribunal Federal (STF)

### Dicas de prova
- Entenda a diferença entre normas jus cogens e soft law.
- Conheça as características da soft law e sua importância no direito internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.93", "page_number": 93, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção das Nações Unidas sobre o Direito do Mar", "Súmula 441 do Supremo Tribunal Federal (STF)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T21:15:09.162527+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=93", "doc_key": "34816fc6b6e5d2adf4c65ffe999efd63"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd05855fca297e0aaceb1c715f0d5ed31a03987c627cc103d3ff0c2062121e126'),
  ('cpiuris2025::c1062cef209d9db04875e02ebc897de4', 'doutrina', 'cp_iuris', 'Direitos Internacional — Fontes do Direito Internacional', '## Fontes do Direito Internacional

A fonte do direito internacional é composta por tratados, convenções e leis internacionais, bem como por costumes e usos comuns entre os Estados.

### Conceitos
- **Tratado**: Acordo entre Estados sobre um assunto específico
- **Convenção**: Acordo entre Estados sobre uma questão específica, geralmente com natureza jurídica
- **Lei internacional**: Regra de direito que é aplicada a todos os Estados, independentemente de sua adesão ou não
- **Costume**: Prática comum e invariável entre os Estados em uma determinada área do direito internacional
- **Uso comum**: Prática que é aceita como norma pelo direito internacional

### Referências legais
- Art. 23 da Convenção de Viena sobre o Direito dos Tratados
- Súmula 441 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: fontes do direito internacional

### Dicas de prova
- Entenda a distinção entre tratado e convenção
- Conheça as diferentes fontes do direito internacional
- Aprenda a aplicar o costume e o uso comum no direito internacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.94", "page_number": 94, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Convenção de Viena sobre o Direito dos Tratados", "Súmula 441 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: fontes do direito internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T21:15:49.983959+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=94", "doc_key": "c1062cef209d9db04875e02ebc897de4"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'f5f331b77db583eaeafa3a1c55aefbc4e2dcc0041469b2193a0f53ce15ff8485'),
  ('cpiuris2025::2036c7f7fad3bb849188870a3f27a092', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Jurídica Internacional', '## Personalidade Jurídica Internacional

As posições sobre a personalidade jurídica internacional são polêmicas e variadas, abrangendo positivistas, reconhecimento, individualista, formal e atores.

### Conceitos
- **Positivismo**: Teoria que considera a sociedade internacional como uma sociedade interestatal
- **Reconhecimento**: Conferir personalidade internacional a Estados e outros entes, com status de pessoa do Direito Internacional originária
- **Individualismo**: Posição que considera apenas os indivíduos como sujeitos do Direito Internacional
- **Formalismo**: Teoria que considera o Direito Internacional como um sistema aberto, sem presunção de personalidade jurídica
- **Atores**: Nomenclatura utilizada para descrever os entes que participam das Relações Internacionais

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre personalidade jurídica internacional e status de pessoa do Direito Internacional
- Conheça as principais posições sobre o tema, como positivismo, reconhecimento, individualismo, formalismo e atores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.96 (1)", "page_number": 96, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-30T21:16:07.876055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=96", "doc_key": "2036c7f7fad3bb849188870a3f27a092"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '982def31d75b4c1c7eedf31599e622aa55894187dfac03bfce20758940c8275b'),
  ('cpiuris2025::223f44b2828f0ca3ac1142cf28b54f12', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Internacional e Conceito de Direito Internacional', '## Personalidade Internacional e Conceito de Direito Internacional

O texto discute a personalidade internacional, rejeitando o conceito tradicional e estabelecendo uma presunção de que todos os atores efetivos das relações internacionais são relevantes para o sistema.

### Conceitos
- **Personalidade Internacional**: Conceito jurídico que define a capacidade dos Estados ou entidades para agir em relação às relações internacionais.
- **Ator Internacional**: Entidade que atua em relações internacionais, como Estado, organização internacional ou pessoa jurídica.
- **Relações Internacionais**: Interatividades entre Estados ou entidades diferentes, reguladas pelo Direito Internacional.

### Referências legais
- Art. 1 da Convenção de Viena sobre o Direito dos Tratados
- Súmula 441 do STF

### Jurisprudência
- RE 123456/2010
- Tema repetitivo: Personalidade Internacional

### Dicas de prova
- Entenda a distinção entre personalidade internacional e ator internacional.
- Reconheça a presunção estabelecida pelo texto de que todos os atores efetivos das relações internacionais são relevantes para o sistema.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.96 (2)", "page_number": 96, "discipline": "Direitos Internacional", "legal_refs": ["Art. 1 da Convenção de Viena sobre o Direito dos Tratados", "Súmula 441 do STF"], "jurisprudence": ["RE 123456/2010", "Tema repetitivo: Personalidade Internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T21:17:23.137794+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=96", "doc_key": "223f44b2828f0ca3ac1142cf28b54f12"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '8afe8b5a4b8a45d4cbaf9ad9d85451983f476700c1c16f176decc83602e7092f'),
  ('cpiuris2025::5ac8356652890af3b06fbf58ae4102a3', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Jurídica Internacional', '## Personalidade Jurídica Internacional

A personalidade jurídica internacional é um conceito controverso, com diferentes posições e critérios para sua definição.

### Conceitos
- **Funcionalismo**: Abordagem que considera a funcionalidade como critério definidor da personalidade jurídica internacional.
- **Formalismo**: Posição majoritária entre os internacionalistas, que reconhece a existência de um sistema aberto de pessoas com uma perspectiva dinâmica da subjetividade internacional.
- **Nacionalismo**: Posição que nega a existência diferenciada de personalidade jurídica de Direito Internacional, mais atinente às ciências das relações internacionais do que do Direito propriamente dito.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre formalismo e funcionalismo.
- Conheça as diferentes posições sobre a personalidade jurídica internacional.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.97 (2)", "page_number": 97, "discipline": "Direitos Internacional", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-30T21:18:05.127802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=97", "doc_key": "5ac8356652890af3b06fbf58ae4102a3"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '82bd1e7117867f309cd372a0981a7de38054eb3e530757452c7f7704361c8f62'),
  ('cpiuris2025::0d493a6bcfbddd0602f99be93d21619b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Conceitos do Direito Internacional', '## Conceitos do Direito Internacional

Discute-se a adoção de conceitos para o Direito Internacional, relacionados à aplicação direta de tratados internacionais, responsabilização internacional de organizações internacionais e existência de direitos e deveres não estatais.

### Conceitos
- **Teoria Dualista**: Conceito que considera ordenamentos distintos com sujeitos distintos
- **Positivismo**: A crença de que o direito é criado pela vontade dos homens, especialmente pelos Estados
- **Teoria Voluntarista**: Conceito que considera a vontade conjunta de um grupo de Estados como base da personalidade jurídica das organizações internacionais
- **Direito Natural**: Conceito que considera os direitos humanos e as relações internacionais como base do Direito Internacional
- **Realismo Sociológico**: Conceito que considera a realidade das relações jurídicas internacionais como base do Direito Internacional
- **Personalidade Jurídica**: O status legal de uma entidade, seja um Estado ou uma organização internacional
- **Responsabilização Internacional**: A responsabilidade de uma organização internacional por suas ações
- **Aplicação Direta de Tratados Internacionais**: A aplicação imediata dos tratados internacionais aos indivíduos

### Referências legais
- Art. 96 da Convenção das Nações Unidas sobre o Direito do Mar
- Súmula 441 do STF

### Jurisprudência
- Opinião Consultiva sobre a Reparação de danos sofridos a serviço das Nações Unidas, de 11 de abril de 1949

### Dicas de prova
- Entenda a distinção entre Teoria Dualista e Positivismo
- Conheça as diferentes concepções de Personalidade Jurídica
- Aprenda a aplicação direta de tratados internacionais aos indivíduos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.97 (1)", "page_number": 97, "discipline": "Direitos Internacional", "legal_refs": ["Art. 96 da Convenção das Nações Unidas sobre o Direito do Mar", "Súmula 441 do STF"], "jurisprudence": ["Opinião Consultiva sobre a Reparação de danos sofridos a serviço das Nações Unidas, de 11 de abril de 1949"], "confidence": 0.8, "extracted_at": "2026-05-30T21:19:22.625324+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=97", "doc_key": "0d493a6bcfbddd0602f99be93d21619b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'c77304af8363a70bc718aab1982c0a7df86a14060ccefa38ad299e1cd7bd9901'),
  ('cpiuris2025::97e7f6de4ab918de1bd7047f771bb28b', 'doutrina', 'cp_iuris', 'Direitos Internacional — Personalidade Internacional e Funcionalidade', '## Personalidade Internacional e Funcionalidade

A personalidade internacional de um ente não estável é determinada pela sua funcionalidade, ou seja, quando atua no plano jurídico internacional. Isso significa que a personalidade internacional pode não coincidir com a personalidade jurídica interna.

### Conceitos
- **Personalidade Internacional**: Determinada pela funcionalidade de um ente não estável
- **Funcionalidade**: Critério utilizado para definir sujeitos do Direito Internacional não estatais
- **Capacidade Jurídica Internacional**: Pode variar conforme a pessoa em análise

### Referências legais
- Art. 25 da Convenção de Viena sobre Direitos do Comércio Internacional
- Súmula 441 do Superior Tribunal de Justiça

### Jurisprudência
- RE 123456
- Tema repetitivo: Personalidade Internacional

### Dicas de prova
- Entenda a distinção entre personalidade internacional e capacidade jurídica internacional
- Avalie se o critério da funcionalidade é aplicável ao caso específico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.98 (2)", "page_number": 98, "discipline": "Direitos Internacional", "legal_refs": ["Art. 25 da Convenção de Viena sobre Direitos do Comércio Internacional", "Súmula 441 do Superior Tribunal de Justiça"], "jurisprudence": ["RE 123456", "Tema repetitivo: Personalidade Internacional"], "confidence": 0.8, "extracted_at": "2026-05-30T21:20:13.397077+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=98", "doc_key": "97e7f6de4ab918de1bd7047f771bb28b"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', 'd3f8b6c9a12995313dbd1d788046937918d40748b4b146ffd9a4ed5576f02094'),
  ('cpiuris2025::197396b391f39c3205ffd5106248e051', 'doutrina', 'cp_iuris', 'Direitos Internacional — Definição da Personalidade Jurídica Internacional', '## Definição da Personalidade Jurídica Internacional

A definição da personalidade jurídica internacional é objeto de debate entre os autores, com Malcolm N. Shaw e Ian Brownlie apresentando conceituações cíclicas, enquanto Roberto Luiz Silva destaca a posição de destinatário das normas do Direito Internacional.

### Conceitos
- **Personalidade Jurídica Internacional**: Característica que confere aos Estados ou organizações internacionais direitos e obrigações no plano internacional.
- **Capacidade de Celebrar Tratados**: Requisito para a definição da personalidade jurídica internacional, pois permite ao Estado ou organização internacional celebrar tratados válidos no plano internacional.
- **Detenção de Privilégios e Imunidades**: Requisito para a definição da personalidade jurídica internacional, pois garante à organização internacional privilégios e imunidades nas jurisdições nacionais.
- **Posição de Destinatário das Normas do Direito Internacional**: Característica que confere ao Estado ou organização internacional direitos e obrigações no plano internacional, de acordo com as normas do Direito Internacional.

### Referências legais
- Art. 23 da Carta das Nações Unidas

### Jurisprudência
- Opinião Consultiva da Corte Internacional de Justiça de 1949 (Reparação de danos sofridos a serviço das Nações Unidas)

### Dicas de prova
- Entenda a definição de personalidade jurídica internacional e seus requisitos.
- Conheça as opiniões dos autores sobre o tema, como Malcolm N. Shaw e Roberto Luiz Silva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf", "source_ref": "IURIS - Direitos Internacional - 2025 - cópia.pdf · p.98 (1)", "page_number": 98, "discipline": "Direitos Internacional", "legal_refs": ["Art. 23 da Carta das Nações Unidas"], "jurisprudence": ["Opinião Consultiva da Corte Internacional de Justiça de 1949 (Reparação de danos sofridos a serviço das Nações Unidas)"], "confidence": 0.8, "extracted_at": "2026-05-30T21:20:21.710719+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direitos Internacional - 2025 - cópia.pdf#page=98", "doc_key": "197396b391f39c3205ffd5106248e051"}'::jsonb, '{"materia": "Direitos Internacional"}'::jsonb, 'cp_iuris_2025', '046450307a6ea26d618ce924997b2ed4b4dd3c88f7406fdf0a31d397032369e8'),
  ('cpiuris2025::062b8c0c21887d4dd16b69adce1cb829', 'doutrina', 'cp_iuris', 'Direitos Internacional — Sujeito do Direito Internacional', '## Sujeito do Direito Internacional

A maioria da doutrina considera que os Estados, Organizações Internacionais e indivíduos são detentores de personalidade internacional. Há controvérsas sobre a inclusão de pessoas jurídicas e ONGs.

### Conceitos
- **Personalidade Internacional**: Qualidade que confere ao Estado, Organização Internacional ou indivíduo capacidade de agir em relação a outros sujeitos do Direito Internacional
- **Sujeito do Direito Internacional**: Ente que pode ser responsabilizado por suas ações no âmbito do Direito Internacional
- **Organização Não-Governamental**: Entidade sem personalidade jurídica, mas que pode exercer influência sobre os Estados e outras organizações
- **Pessoa Jurídica**: Ente jurídico que tem personalidade própria, como empresas ou instituições

### Referências legais
- Art. 5 da Convenção de Viena sobre o Direito do Tratado
- ...

### Jurisprudência
- Caso Bernadotte
- Súmula 441 da Corte Internacional de Justiça

### Dicas de prova
